INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53513, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "距離や時間がとても長いこと", "primary_collocate": null, "pronunciation": "ながし", "ipa": "naɡaɕi", "syllable_count": 3, "sentences": [{"text": "冬の夜は長し、眠れぬまま朝を待つ。", "target_word": "長し", "complexity_tier": "T3", "furigana": "冬[ふゆ]の夜[よる]は長[なが]し、眠[ねむ]れぬまま朝[あさ]を待[ま]つ。", "sentence_source": "generated"}, {"text": "山の道は長し、日が暮れるまでに着けるだろうか。", "target_word": "長し", "complexity_tier": "T3", "furigana": "山[やま]の道[みち]は長[なが]し、日[ひ]が暮[く]れるまでに着[つ]けるだろうか。", "sentence_source": "generated"}, {"text": "待つ時間は長し、時計の針が進まない。", "target_word": "長し", "complexity_tier": "T3", "furigana": "待[ま]つ時間[じかん]は長[なが]し、時計[とけい]の針[はり]が進[すす]まない。", "sentence_source": "generated"}, {"text": "人生は短く、芸術は長し。", "target_word": "長し", "complexity_tier": "T3", "furigana": "人生[じんせい]は短[みじか]く、芸術[げいじゅつ]は長[なが]し。", "sentence_source": "generated"}, {"text": "ふるさとへの道は長し、帰り着くのはいつになるか。", "target_word": "長し", "complexity_tier": "T3", "furigana": "ふるさとへの道[みち]は長[なが]し、帰[かえ]り着[つ]くのはいつになるか。", "sentence_source": "generated"}, {"text": "秋の夜は長し、窓の外で虫が鳴いている。", "target_word": "長し", "complexity_tier": "T3", "furigana": "秋[あき]の夜[よる]は長[なが]し、窓[まど]の外[そと]で虫[むし]が鳴[な]いている。", "sentence_source": "generated"}, {"text": "旅路は長し、まだ半分も来ていない。", "target_word": "長し", "complexity_tier": "T3", "furigana": "旅路[たびじ]は長[なが]し、まだ半分[はんぶん]も来[き]ていない。", "sentence_source": "generated"}, {"text": "川の流れは長し、海まで何日もかかる。", "target_word": "長し", "complexity_tier": "T3", "furigana": "川[かわ]の流[なが]れは長[なが]し、海[うみ]まで何日[なんにち]もかかる。", "sentence_source": "generated"}, {"text": "冬の日は短く、夏の日は長し。", "target_word": "長し", "complexity_tier": "T3", "furigana": "冬[ふゆ]の日[ひ]は短[みじか]く、夏[なつ]の日[ひ]は長[なが]し。", "sentence_source": "generated"}, {"text": "雪の山道は長し、夜になっても宿に着かない。", "target_word": "長し", "complexity_tier": "T3", "furigana": "雪[ゆき]の山道[やまみち]は長[なが]し、夜[よる]になっても宿[やど]に着[つ]かない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "長し", "label": "終止形"}, {"form": "長き", "label": "連体形"}, {"form": "長く", "label": "連用形"}, {"form": "長けれ", "label": "已然形"}], "register": "文語", "sense_fingerprint": "文語の終止形。距離や時間がとても長い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53513, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "長し", "is_correct": true, "explanation": "「冬の夜は長し」と言い切る文語の終止形で、ここに入る唯一の形。"}, {"text": "長き", "is_correct": false, "explanation": "連体形。名詞に続けて「長き夜」のように使う形で、読点の前では文を言い切れない。"}, {"text": "長けれ", "is_correct": false, "explanation": "已然形。「ば」「ども」などに続く形で、ここでは文を終えられない。"}, {"text": "長かろ", "is_correct": false, "explanation": "未然形。「う」「ず」などに続く形で、ここでは述語として言い切れない。"}], "explanations": {"長し": "「冬の夜は長し」と言い切る文語の終止形で、ここに入る唯一の形。", "長き": "連体形。名詞に続けて「長き夜」のように使う形で、読点の前では文を言い切れない。", "長けれ": "已然形。「ば」「ども」などに続く形で、ここでは文を終えられない。", "長かろ": "未然形。「う」「ず」などに続く形で、ここでは述語として言い切れない。"}, "sentence_index": 0, "correct_answer": "長し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この布は手に取ると硬く、重ねた部分の厚みは長し。", "explanation": "ここは〈厚い〉の意味。厚みは〈厚い〉で表し、〈長い〉は距離や時間に使うので合わない。"}, {"text": "このお茶は長し、味が濃く舌に残る。", "explanation": "ここは〈強い〉の意味。味や効き目の濃さを言う場面なので、長しは合わない。"}, {"text": "この荷物は持つと重さが長し、腕が痛い。", "explanation": "ここは〈重い〉の意味。重さは〈重い〉で表し、〈長い〉は距離や時間に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53513, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "長し", "is_correct": true, "explanation": "「旅路は長し」と言い切る文語の終止形で、ここに入る唯一の形。"}, {"text": "長から", "is_correct": false, "explanation": "未然形。「ず」「む」などに続く形で、ここでは文を終えられない。"}, {"text": "長けれ", "is_correct": false, "explanation": "已然形。「ば」「ども」に続く形で、ここでは文を言い切れない。"}, {"text": "長きに", "is_correct": false, "explanation": "連体形に助詞「に」が付いた形で、文を言い切れず成立しない。"}], "explanations": {"長し": "「旅路は長し」と言い切る文語の終止形で、ここに入る唯一の形。", "長から": "未然形。「ず」「む」などに続く形で、ここでは文を終えられない。", "長けれ": "已然形。「ば」「ども」に続く形で、ここでは文を言い切れない。", "長きに": "連体形に助詞「に」が付いた形で、文を言い切れず成立しない。"}, "sentence_index": 6, "correct_answer": "長し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋は窓からの光が長し、昼間もうす暗い。", "explanation": "ここは〈明るい〉の意味。光の明るさは〈明るい〉で表し、〈長い〉は距離や時間に使うので合わない。"}, {"text": "この水は温もりが長し、手を入れるとぬるい。", "explanation": "ここは〈温かい〉の意味。温度は〈温かい〉や〈冷たい〉で表し、〈長い〉は距離や時間に使うので合わない。"}, {"text": "このインクは発色が長し、紙に写ると色がかすむ。", "explanation": "ここは〈濃い〉の意味。色の濃淡は〈濃い〉で表し、〈長い〉は距離や時間に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53513, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "帰り道は長き、夜更けにようやく家に着く。", "corrected_sentence": "帰り道は長し、夜更けにようやく家に着く。", "error_description": "誤りは「長き」。正しくは終止形の「長し」。「長き」は連体形なので、読点の前で文を言い切れない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "長し", "is_correct": true, "explanation": "終止形。「山の道は長し、」と述語で言い切る形なので、ここに合う。"}, {"text": "長き", "is_correct": false, "explanation": "連体形。名詞に続けて「長き道」と使うので、読点の前では言い切れない。"}, {"text": "長から", "is_correct": false, "explanation": "未然形。「ず」「む」に続く形で、読点の前では述語として言い切れない。"}, {"text": "長けれ", "is_correct": false, "explanation": "已然形。「ば」「ども」に続く形で、ここでは言い切ることができない。"}], "correct_form": "長し", "base_form": "長し", "form_label": "終止形", "sentence_index": 1, "explanations": {"長し": "終止形。「山の道は長し、」と述語で言い切る形なので、ここに合う。", "長き": "連体形。名詞に続けて「長き道」と使うので、読点の前では言い切れない。", "長から": "未然形。「ず」「む」に続く形で、読点の前では述語として言い切れない。", "長けれ": "已然形。「ば」「ども」に続く形で、ここでは言い切ることができない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53513, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅路は長しき、まだ半分にも届かない。", "corrected_sentence": "旅路は長し、まだ半分にも届かない。", "error_description": "誤りは「長しき」。過去の「き」は連用形（長かり）に付くもので、終止形「長し」には付かない。「き」を外して「長し」とする。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "長し", "is_correct": true, "explanation": "終止形。「川の流れは長し、」と述語で言い切る形なので、ここに合う。"}, {"text": "長かり", "is_correct": false, "explanation": "連用形。「けり」「き」に続く形で、読点の前では述語として言い切れない。"}, {"text": "長かろ", "is_correct": false, "explanation": "未然形。「う」「ず」に続く形で、ここでは述語として言い切れない。"}, {"text": "長かれ", "is_correct": false, "explanation": "命令形。命令の形なので、事実を述べるこの文には合わない。"}], "correct_form": "長し", "base_form": "長し", "form_label": "終止形", "sentence_index": 7, "explanations": {"長し": "終止形。「川の流れは長し、」と述語で言い切る形なので、ここに合う。", "長かり": "連用形。「けり」「き」に続く形で、読点の前では述語として言い切れない。", "長かろ": "未然形。「う」「ず」に続く形で、ここでは述語として言い切れない。", "長かれ": "命令形。命令の形なので、事実を述べるこの文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
