INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53514, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "距離・時間・長さが普通よりも大きいこと。", "primary_collocate": null, "pronunciation": "ながし", "ipa": "naɡaɕi", "syllable_count": 3, "sentences": [{"text": "この橋は長し、渡るのに十分もかかる。", "target_word": "長し", "complexity_tier": "T3", "furigana": "この橋[はし]は長[なが]し、渡[わた]るのに十分[じっぷん]もかかる。", "sentence_source": "generated"}, {"text": "夏の昼は長し、夕方になってもまだ明るい。", "target_word": "長し", "complexity_tier": "T3", "furigana": "夏[なつ]の昼[ひる]は長[なが]し、夕方[ゆうがた]になってもまだ明[あか]るい。", "sentence_source": "generated"}, {"text": "彼の話は長し、聞いている者はみな退屈した。", "target_word": "長し", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は長[なが]し、聞[き]いている者[もの]はみな退屈[たいくつ]した。", "sentence_source": "generated"}, {"text": "その川は長し、地図の端から端まで続いている。", "target_word": "長し", "complexity_tier": "T3", "furigana": "その川[かわ]は長[なが]し、地図[ちず]の端[はし]から端[はし]まで続[つづ]いている。", "sentence_source": "generated"}, {"text": "待ち行列は長し、先頭が見えないほどだ。", "target_word": "長し", "complexity_tier": "T3", "furigana": "待[ま]ち行列[ぎょうれつ]は長[なが]し、先頭[せんとう]が見[み]えないほどだ。", "sentence_source": "generated"}, {"text": "彼女の髪は長し、腰まで届いている。", "target_word": "長し", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の髪[かみ]は長[なが]し、腰[こし]まで届[とど]いている。", "sentence_source": "generated"}, {"text": "この廊下は長し、端まで歩くと一分かかる。", "target_word": "長し", "complexity_tier": "T3", "furigana": "この廊下[ろうか]は長[なが]し、端[はし]まで歩[ある]くと一分[いっぷん]かかる。", "sentence_source": "generated"}, {"text": "校長の話は長し、生徒の足がしびれた。", "target_word": "長し", "complexity_tier": "T3", "furigana": "校長[こうちょう]の話[はなし]は長[なが]し、生徒[せいと]の足[あし]がしびれた。", "sentence_source": "generated"}, {"text": "今年の梅雨は長し、七月の末になっても明けない。", "target_word": "長し", "complexity_tier": "T3", "furigana": "今年[ことし]の梅雨[つゆ]は長[なが]し、七月[しちがつ]の末[すえ]になっても明[あ]けない。", "sentence_source": "generated"}, {"text": "トンネルは長し、出口の光がまだ見えない。", "target_word": "長し", "complexity_tier": "T3", "furigana": "トンネルは長[なが]し、出口[でぐち]の光[ひかり]がまだ見[み]えない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "長し", "label": "終止形"}, {"form": "長き", "label": "連体形"}, {"form": "長く", "label": "連用形"}, {"form": "長けれ", "label": "已然形"}], "register": "文語", "sense_fingerprint": "文語の終止形。長さや距離が普通より大きい", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e99e6a81-938c-4d61-b2b1-54ca739cd0db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53514, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "長し", "is_correct": true, "explanation": "「この橋は長し」と言い切る文語の終止形で、ここに入る唯一の形。"}, {"text": "長き", "is_correct": false, "explanation": "連体形。名詞に続ける形で、読点の前では文を言い切れない。"}, {"text": "長けれ", "is_correct": false, "explanation": "已然形。「ば」「ども」に続く形で、ここでは文を終えられない。"}, {"text": "長かろ", "is_correct": false, "explanation": "未然形。「う」「ず」に続く形で、ここでは述語として言い切れない。"}], "explanations": {"長し": "「この橋は長し」と言い切る文語の終止形で、ここに入る唯一の形。", "長き": "連体形。名詞に続ける形で、読点の前では文を言い切れない。", "長けれ": "已然形。「ば」「ども」に続く形で、ここでは文を終えられない。", "長かろ": "未然形。「う」「ず」に続く形で、ここでは述語として言い切れない。"}, "sentence_index": 0, "correct_answer": "長し"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この縄は太さが長し、握ると硬い。", "explanation": "ここは〈太い〉の意味。太さは〈太い〉で表し、〈長い〉は距離や時間に使うので合わない。"}, {"text": "夕焼けの雲は色の濃さが長し、空いっぱいに燃えている。", "explanation": "ここは〈濃い〉の意味。色の濃さは〈濃い〉で表し、〈長い〉は距離や時間に使うので合わない。"}, {"text": "この湖は水の冷たさが長し、泳ぐと震える。", "explanation": "ここは〈冷たい〉の意味。温度は〈冷たい〉で表し、〈長い〉は距離や時間などの長さに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53514, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "長し", "is_correct": true, "explanation": "「この廊下は長し」と言い切る文語の終止形で、ここに入る唯一の形。"}, {"text": "長から", "is_correct": false, "explanation": "未然形。「ず」「む」などに続く形で、ここでは文を終えられない。"}, {"text": "長けれ", "is_correct": false, "explanation": "已然形。「ば」「ども」に続く形で、ここでは文を言い切れない。"}, {"text": "長きに", "is_correct": false, "explanation": "連体形に助詞「に」が付いた形で、文を言い切れず成立しない。"}], "explanations": {"長し": "「この廊下は長し」と言い切る文語の終止形で、ここに入る唯一の形。", "長から": "未然形。「ず」「む」などに続く形で、ここでは文を終えられない。", "長けれ": "已然形。「ば」「ども」に続く形で、ここでは文を言い切れない。", "長きに": "連体形に助詞「に」が付いた形で、文を言い切れず成立しない。"}, "sentence_index": 6, "correct_answer": "長し"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このパンは噛み心地が長し、いつまでも固い。", "explanation": "ここは〈柔らかい〉の意味。噛んだ時の柔らかさは〈柔らかい〉で表し、〈長い〉は距離や時間などの長さに使うので合わない。"}, {"text": "この壁は黒ずみが長し、くすんだ灰色に見える。", "explanation": "ここは〈黒い〉の意味。色の濃さは〈黒い〉で表し、〈長い〉は距離や時間などの長さに使うので合わない。"}, {"text": "このカレーは、ぴりぴりする刺激が長し、舌がしびれる。", "explanation": "ここは〈辛い〉の意味。辛味の強さは〈辛い〉で表し、〈長い〉は距離や時間などの長さに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53514, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この橋は長けれ、渡るのに一時間もかかる。", "corrected_sentence": "この橋は長し、渡るのに一時間もかかる。", "error_description": "誤りは「長けれ」。正しくは終止形の「長し」。已然形は「ば」「ども」などに続く形で、読点の前で文を言い切れない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "長し", "is_correct": true, "explanation": "終止形。「夏の昼は長し、」と述語で言い切る形なので、ここに合う。"}, {"text": "長き", "is_correct": false, "explanation": "連体形。名詞に続けて「長き昼」と使うので、読点の前では言い切れない。"}, {"text": "長から", "is_correct": false, "explanation": "未然形。「ず」「む」に続く形で、ここでは述語として言い切れない。"}, {"text": "長けれ", "is_correct": false, "explanation": "已然形。「ば」「ども」に続く形で、ここでは言い切ることができない。"}], "correct_form": "長し", "base_form": "長し", "form_label": "終止形", "sentence_index": 1, "explanations": {"長し": "終止形。「夏の昼は長し、」と述語で言い切る形なので、ここに合う。", "長き": "連体形。名詞に続けて「長き昼」と使うので、読点の前では言い切れない。", "長から": "未然形。「ず」「む」に続く形で、ここでは述語として言い切れない。", "長けれ": "已然形。「ば」「ども」に続く形で、ここでは言い切ることができない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53514, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "トンネルは長き、出口の光がまだ見えてこない。", "corrected_sentence": "トンネルは長し、出口の光がまだ見えてこない。", "error_description": "誤りは「長き」。正しくは終止形の「長し」。連体形は名詞に続く形で、読点の前では文を言い切れない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "長し", "is_correct": true, "explanation": "終止形。「校長の話は長し、」と述語で言い切る形なので、ここに合う。"}, {"text": "長かり", "is_correct": false, "explanation": "連用形。「けり」「き」に続く形で、読点の前では述語として言い切れない。"}, {"text": "長かろ", "is_correct": false, "explanation": "未然形。「う」「ず」に続く形で、ここでは述語として言い切れない。"}, {"text": "長かれ", "is_correct": false, "explanation": "命令形。命令の形なので、事実を述べるこの文には合わない。"}], "correct_form": "長し", "base_form": "長し", "form_label": "終止形", "sentence_index": 7, "explanations": {"長し": "終止形。「校長の話は長し、」と述語で言い切る形なので、ここに合う。", "長かり": "連用形。「けり」「き」に続く形で、読点の前では述語として言い切れない。", "長かろ": "未然形。「う」「ず」に続く形で、ここでは述語として言い切れない。", "長かれ": "命令形。命令の形なので、事実を述べるこの文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de5096a9-8888-418f-bdaa-b71a018b98a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53515, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「大きな石を引きずって」の目的語を示す助詞。引きずられる対象を指定する。"}, {"text": "が", "is_correct": false, "explanation": "「石が引きずって」は主語になり、引きずられる対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「石に引きずって」は対象として成り立たず、引かれる物を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「石で引きずって」は手段を示すが、引かれる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「大きな石を引きずって」の目的語を示す助詞。引きずられる対象を指定する。", "が": "「石が引きずって」は主語になり、引きずられる対象を示せない。", "に": "「石に引きずって」は対象として成り立たず、引かれる物を示せない。", "で": "「石で引きずって」は手段を示すが、引かれる対象を表せない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
