INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53515, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "重い物を引いて、別の場所へ運ぶ。", "primary_collocate": null, "pronunciation": "ひきずる", "ipa": "çikizɯɾɯ", "syllable_count": 4, "sentences": [{"text": "重いテーブルを引きずって、部屋の隅に移動させた。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "重[おも]いテーブルを引[ひ]きずって、部屋[へや]の隅[すみ]に移動[いどう]させた。", "sentence_source": "generated"}, {"text": "工事の人が大きな石を引きずって、庭の外へ運んでいった。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "工事[こうじ]の人[ひと]が大[おお]きな石[いし]を引[ひ]きずって、庭[にわ]の外[そと]へ運[はこ]んでいった。", "sentence_source": "generated"}, {"text": "一人では持てないので、ソファーを引きずって隣の部屋まで運びます。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "一人[ひとり]では持[も]てないので、ソファーを引[ひ]きずって隣[となり]の部屋[へや]まで運[はこ]びます。", "sentence_source": "generated"}, {"text": "床を傷つけないように、タンスの下に布を敷いてから引きずった。", "target_word": "引きずった", "complexity_tier": "T3", "furigana": "床[ゆか]を傷[きず]つけないように、タンスの下[した]に布[ぬの]を敷[し]いてから引[ひ]きずった。", "sentence_source": "generated"}, {"text": "彼は重い荷物を引きずって、駅のホームを歩いていた。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "彼[かれ]は重[おも]い荷物[にもつ]を引[ひ]きずって、駅[えき]のホームを歩[ある]いていた。", "sentence_source": "generated"}, {"text": "台風のあと、折れた枝を引きずって道の端に寄せた。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "台風[たいふう]のあと、折[お]れた枝[えだ]を引[ひ]きずって道[みち]の端[はし]に寄[よ]せた。", "sentence_source": "generated"}, {"text": "男たちは、切り出した丸太を引きずって川まで運んだ。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "男[おとこ]たちは、切[き]り出[だ]した丸太[まるた]を引[ひ]きずって川[かわ]まで運[はこ]んだ。", "sentence_source": "generated"}, {"text": "重すぎて持ち上がらないので、引きずって運ぶしかなかった。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "重[おも]すぎて持[も]ち上[あ]がらないので、引[ひ]きずって運[はこ]ぶしかなかった。", "sentence_source": "generated"}, {"text": "引きずると音がうるさいので、そっと持ち上げて運んでください。", "target_word": "引きずる", "complexity_tier": "T3", "furigana": "引[ひ]きずると音[おと]がうるさいので、そっと持[も]ち上[あ]げて運[はこ]んでください。", "sentence_source": "generated"}, {"text": "雪の上を、大きな袋を引きずって歩く子どもの姿が見えた。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "雪[ゆき]の上[うえ]を、大[おお]きな袋[ふくろ]を引[ひ]きずって歩[ある]く子[こ]どもの姿[すがた]が見[み]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引きずる", "label": "終止形"}, {"form": "引きずり", "label": "連用形"}, {"form": "引きずって", "label": "て形"}, {"form": "引きずった", "label": "過去形"}, {"form": "引きずらない", "label": "否定形"}, {"form": "引きずれば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "重い物を持ち上げず引いて別の場所へ移す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53515, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引きずって", "is_correct": true, "explanation": "「重いテーブルを引きずって移動させた」の て形。地面に付けたまま運ぶ動作を表す正しい形。"}, {"text": "眺めて", "is_correct": false, "explanation": "「重いテーブルを眺めて移動させた」は意味が通らず、重い物を運ぶ文脈に合わない。"}, {"text": "叩いて", "is_correct": false, "explanation": "「叩いて移動させた」は運ぶ方法にならず、テーブルを動かす説明として合わない。"}, {"text": "折って", "is_correct": false, "explanation": "「折って移動させた」は物を壊す意味になり、運ぶ文脈に合わない。"}], "explanations": {"引きずって": "「重いテーブルを引きずって移動させた」の て形。地面に付けたまま運ぶ動作を表す正しい形。", "眺めて": "「重いテーブルを眺めて移動させた」は意味が通らず、重い物を運ぶ文脈に合わない。", "叩いて": "「叩いて移動させた」は運ぶ方法にならず、テーブルを動かす説明として合わない。", "折って": "「折って移動させた」は物を壊す意味になり、運ぶ文脈に合わない。"}, "sentence_index": 0, "correct_answer": "引きずって"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "男は大きな袋を両腕で引きずって、高いところにぶら下げた。", "explanation": "ここは〈吊るす〉（上から下げて固定する）の意味。引きずるは地面を滑らせて運ぶ動作なので、高く吊り下げる場面には使わない。"}, {"text": "重い箱を肩に引きずって、階段を上った。", "explanation": "ここは〈担ぐ〉（肩に乗せて運ぶ）の意味。引きずるは地面に付けたまま運ぶので、肩に乗せる動作には使わない。"}, {"text": "過去の失敗を引きずって、なかなか前へ進めない。", "explanation": "ここは〈後まで残す・長引かせる〉の意味。引きずるは物を引いて運ぶ動作で、過去の出来事が後まで残る意味には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53515, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引きずって", "is_correct": true, "explanation": "「丸太を引きずって川まで運んだ」の て形。地面に付けたまま運ぶ動作を表す正しい形。"}, {"text": "叱って", "is_correct": false, "explanation": "「丸太を叱って川まで運んだ」は叱る相手が人である動詞で、丸太には成り立たず運ぶ文脈に合わない。"}, {"text": "嗅いで", "is_correct": false, "explanation": "「丸太を嗅いで川まで運んだ」は匂いを確かめる動作で、運搬の方法としては意味が通らない。"}, {"text": "食べて", "is_correct": false, "explanation": "「丸太を食べて川まで運んだ」は丸太には成り立たず、運ぶ動作と合わない。"}], "explanations": {"引きずって": "「丸太を引きずって川まで運んだ」の て形。地面に付けたまま運ぶ動作を表す正しい形。", "叱って": "「丸太を叱って川まで運んだ」は叱る相手が人である動詞で、丸太には成り立たず運ぶ文脈に合わない。", "嗅いで": "「丸太を嗅いで川まで運んだ」は匂いを確かめる動作で、運搬の方法としては意味が通らない。", "食べて": "「丸太を食べて川まで運んだ」は丸太には成り立たず、運ぶ動作と合わない。"}, "sentence_index": 6, "correct_answer": "引きずって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大きな袋を両腕で抱えたまま、雪の上を引きずって歩く子どもが見えた。", "explanation": "ここは〈持つ〉（手で持ち続ける）の意味。引きずるは地面を滑らせて運ぶ動作で、腕で持ったまま運ぶ場面には使わない。"}, {"text": "雪の上で、大きな袋を引きずって、空中に放り上げる子どもが見えた。", "explanation": "ここは〈投げる〉（勢いよく飛ばす）の意味。引きずるは地面を滑らせて運ぶ動作なので、空中へ勢いよく飛ばす場面には使わない。"}, {"text": "雪の上で、大きな袋を引きずって、ボールのように跳ねさせる子どもが見えた。", "explanation": "ここは〈弾ませる〉（はずませて跳ね返らせる）の意味。引きずるは地面を滑らせて運ぶ動作なので、跳ねさせる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53515, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ベッドを引きずで、窓際まで運んだ。", "corrected_sentence": "ベッドを引きずって、窓際まで運んだ。", "error_description": "〈引きずる〉のて形は「引きずって」。「引きずで」は活用の誤りで、正しくは「引きずって」になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引きずって", "is_correct": true, "explanation": "「大きな石を引きずって、庭の外へ運んでいった」の て形。石を地面に付けて運ぶ動作を続ける正しい形。"}, {"text": "引きずれ", "is_correct": false, "explanation": "命令形。「引きずれ、庭の外へ運んでいった」は命令になり、事実を述べる文と合わない。"}, {"text": "引きずらない", "is_correct": false, "explanation": "否定形。石を引いて運んだ動作と合わない。"}, {"text": "引きずれば", "is_correct": false, "explanation": "仮定形。条件の文になり、実際の運搬の描写と合わない。"}], "correct_form": "引きずって", "base_form": "引きずる", "form_label": "て形", "sentence_index": 1, "explanations": {"引きずって": "「大きな石を引きずって、庭の外へ運んでいった」の て形。石を地面に付けて運ぶ動作を続ける正しい形。", "引きずれ": "命令形。「引きずれ、庭の外へ運んでいった」は命令になり、事実を述べる文と合わない。", "引きずらない": "否定形。石を引いて運んだ動作と合わない。", "引きずれば": "仮定形。条件の文になり、実際の運搬の描写と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53515, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "重い板を引きずりて、倉庫まで運んだ。", "corrected_sentence": "重い板を引きずって、倉庫まで運んだ。", "error_description": "〈引きずる〉のて形は「引きずって」。「引きずりて」は活用の誤りで、正しくは「引きずって」になる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引きずって", "is_correct": true, "explanation": "「重すぎて持ち上がらないので、引きずって運ぶしかなかった」のて形。持ち上げられないため引いて運ぶ方法を示す正しい形。"}, {"text": "引きずる", "is_correct": false, "explanation": "終止形。「引きずる、運ぶしかなかった」と文が続かず、方法を示す形として合わない。"}, {"text": "引きずら", "is_correct": false, "explanation": "未然形。「引きずら、運ぶしかなかった」と続けられず、文として成立しない。"}, {"text": "引きずれ", "is_correct": false, "explanation": "命令形。「引きずれ、運ぶしかなかった」は命令になり、状況の説明と合わない。"}], "correct_form": "引きずって", "base_form": "引きずる", "form_label": "て形", "sentence_index": 7, "explanations": {"引きずって": "「重すぎて持ち上がらないので、引きずって運ぶしかなかった」のて形。持ち上げられないため引いて運ぶ方法を示す正しい形。", "引きずる": "終止形。「引きずる、運ぶしかなかった」と文が続かず、方法を示す形として合わない。", "引きずら": "未然形。「引きずら、運ぶしかなかった」と続けられず、文として成立しない。", "引きずれ": "命令形。「引きずれ、運ぶしかなかった」は命令になり、状況の説明と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53516, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「荷物を引きずって」の目的語を示す助詞。引きずられる対象を指定する。"}, {"text": "が", "is_correct": false, "explanation": "「荷物が引きずって」は主語になり、引きずる対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「荷物に引きずって」は対象として成り立たず、引く対象を示せない。"}, {"text": "で", "is_correct": false, "explanation": "「荷物で引きずって」は手段を示すが、引かれる対象を表せない。"}], "correct_answer": "を", "explanations": {"を": "「荷物を引きずって」の目的語を示す助詞。引きずられる対象を指定する。", "が": "「荷物が引きずって」は主語になり、引きずる対象を示せない。", "に": "「荷物に引きずって」は対象として成り立たず、引く対象を示せない。", "で": "「荷物で引きずって」は手段を示すが、引かれる対象を表せない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
