INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53516, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かを引いて、別の場所へ運ぶ。", "primary_collocate": null, "pronunciation": "ひきずる", "ipa": "çikizɯɾɯ", "syllable_count": 4, "sentences": [{"text": "革の匂いが漂う暗闇の奥底で、長き眠りについていたそれを引きずり出した瞬間、埃っぽい記憶の粒子が舞い上がる。", "target_word": "引きずり", "complexity_tier": "T5", "furigana": "革[かわ]の匂[にお]いが漂[ただよ]う暗闇[くらやみ]の奥底[おくそこ]で、長[なが]き眠[ねむ]りについていたそれを引[ひ]きずり出[だ]した瞬間[しゅんかん]、埃[ほこり]っぽい記憶[きおく]の粒子[りゅうし]が舞[ま]い上[あ]がる。", "sentence_source": "mined"}, {"text": "重い荷物を引きずって、駅の改札まで歩いた。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "重[おも]い荷物[にもつ]を引[ひ]きずって、駅[えき]の改札[かいさつ]まで歩[ある]いた。", "sentence_source": "generated"}, {"text": "彼は倒れた木を引きずって、道の端まで運んだ。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "彼[かれ]は倒[たお]れた木[き]を引[ひ]きずって、道[みち]の端[はし]まで運[はこ]んだ。", "sentence_source": "generated"}, {"text": "子どもたちは大きな段ボール箱を引きずって、庭の奥へ運んだ。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "子[こ]どもたちは大[おお]きな段[だん]ボール箱[ばこ]を引[ひ]きずって、庭[にわ]の奥[おく]へ運[はこ]んだ。", "sentence_source": "generated"}, {"text": "漁師たちは、網にかかった大きな魚を浜まで引きずった。", "target_word": "引きずった", "complexity_tier": "T3", "furigana": "漁師[りょうし]たちは、網[あみ]にかかった大[おお]きな魚[さかな]を浜[はま]まで引[ひ]きずった。", "sentence_source": "generated"}, {"text": "引っ越しの日、タンスを引きずって運んだら、床に傷がついてしまった。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの日[ひ]、タンスを引[ひ]きずって運[はこ]んだら、床[ゆか]に傷[きず]がついてしまった。", "sentence_source": "generated"}, {"text": "雪道では、重い箱をそのまま引きずって運ぶこともできる。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "雪道[ゆきみち]では、重[おも]い箱[はこ]をそのまま引[ひ]きずって運[はこ]ぶこともできる。", "sentence_source": "generated"}, {"text": "兵士は動けなくなった仲間を、安全な場所まで引きずった。", "target_word": "引きずった", "complexity_tier": "T3", "furigana": "兵士[へいし]は動[うご]けなくなった仲間[なかま]を、安全[あんぜん]な場所[ばしょ]まで引[ひ]きずった。", "sentence_source": "generated"}, {"text": "収穫した大きなかぼちゃを、農家の人が倉庫まで引きずって運んだ。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "収穫[しゅうかく]した大[おお]きなかぼちゃを、農家[のうか]の人[ひと]が倉庫[そうこ]まで引[ひ]きずって運[はこ]んだ。", "sentence_source": "generated"}, {"text": "力が足りなかったので、重い袋を持ち上げずに引きずって運んだ。", "target_word": "引きずって", "complexity_tier": "T3", "furigana": "力[ちから]が足[た]りなかったので、重[おも]い袋[ふくろ]を持[も]ち上[あ]げずに引[ひ]きずって運[はこ]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "引きずる", "label": "終止形"}, {"form": "引きずり", "label": "連用形"}, {"form": "引きずって", "label": "て形"}, {"form": "引きずった", "label": "過去形"}, {"form": "引きずらない", "label": "否定形"}, {"form": "引きずれば", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "物を地面に付けたまま引いて別の場所へ運ぶ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53516, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引きずり", "is_correct": true, "explanation": "「〜ながら」は動詞の連用形に接続する。「重い箱を引きずりながら、倉庫の奥へ進んだ」と並行する動作を表す。"}, {"text": "叱り", "is_correct": false, "explanation": "「重い箱を叱りながら」は箱を叱る動作になり、運ぶ文脈と合わない。"}, {"text": "嗅ぎ", "is_correct": false, "explanation": "「重い箱を嗅ぎながら」は匂いを確かめる動作で、運搬の文脈に合わない。"}, {"text": "焦がし", "is_correct": false, "explanation": "「重い箱を焦がしながら」は箱を焦がす意味になり、運ぶ文脈に合わない。"}], "explanations": {"引きずり": "「〜ながら」は動詞の連用形に接続する。「重い箱を引きずりながら、倉庫の奥へ進んだ」と並行する動作を表す。", "叱り": "「重い箱を叱りながら」は箱を叱る動作になり、運ぶ文脈と合わない。", "嗅ぎ": "「重い箱を嗅ぎながら」は匂いを確かめる動作で、運搬の文脈に合わない。", "焦がし": "「重い箱を焦がしながら」は箱を焦がす意味になり、運ぶ文脈に合わない。"}, "sentence_index": 0, "correct_answer": "引きずり"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "子どもたちは大きな段ボール箱を引きずって、高いところにぶら下げた。", "explanation": "ここは〈吊るす〉（上から下げて固定する）の意味。引きずるは地面を滑らせて運ぶ動作なので、高く吊り下げる場面には使わない。"}, {"text": "子どもたちは大きな段ボール箱を肩に引きずって、庭の奥へ運んだ。", "explanation": "ここは〈担ぐ〉（肩に乗せて運ぶ）の意味。引きずるは地面に付けたまま運ぶので、肩に乗せる動作には使わない。"}, {"text": "綱引きで、子どもたちは綱を引きずって勝負した。", "explanation": "ここは〈引っ張る〉（力を込めて引く）の意味。地面に付けたまま運ぶ定義とは合わず、綱を引いて競う場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53516, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引きずって", "is_correct": true, "explanation": "「重い箱をそのまま引きずって運ぶ」の て形。地面に付けたまま運ぶ動作を表す正しい形。"}, {"text": "眺めて", "is_correct": false, "explanation": "「眺めて運ぶ」は成り立たず、重い箱を運ぶ動作と合わない。"}, {"text": "磨いて", "is_correct": false, "explanation": "「磨いて運ぶ」は動作の順序として不自然で、運ぶ方法の説明にならない。"}, {"text": "焦がして", "is_correct": false, "explanation": "「焦がして運ぶ」は意味が通らず、重い箱を運ぶ文脈に合わない。"}], "explanations": {"引きずって": "「重い箱をそのまま引きずって運ぶ」の て形。地面に付けたまま運ぶ動作を表す正しい形。", "眺めて": "「眺めて運ぶ」は成り立たず、重い箱を運ぶ動作と合わない。", "磨いて": "「磨いて運ぶ」は動作の順序として不自然で、運ぶ方法の説明にならない。", "焦がして": "「焦がして運ぶ」は意味が通らず、重い箱を運ぶ文脈に合わない。"}, "sentence_index": 6, "correct_answer": "引きずって"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもたちは大きな段ボール箱を胸に引きずって、庭の奥へ運んだ。", "explanation": "ここは〈抱える〉（胸に抱いて運ぶ）の意味。引きずるは地面に付けたまま引く動作なので、胸に抱える場面では使わない。"}, {"text": "子どもたちは大きな段ボール箱を引きずって、空高く持ち上げた。", "explanation": "ここは〈掲げる〉（高く掲げて見せる）の意味。引きずるは地面に付けたまま移す動作なので、空中に掲げる場面には使わない。"}, {"text": "子どもたちは大きな段ボール箱を、水の上に引きずって運んだ。", "explanation": "ここは〈浮かべて運ぶ〉の意味。引きずるは地面との接触を前提とするので、水の上で運ぶ様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53516, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大きな段ボールを引きずりて、倉庫まで運んだ。", "corrected_sentence": "大きな段ボールを引きずって、倉庫まで運んだ。", "error_description": "〈引きずる〉のて形は「引きずって」。「引きずりて」は活用の誤りで、正しくは「引きずって」になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "引きずって", "is_correct": true, "explanation": "「重い荷物を引きずって歩いた」の て形。荷物を地面に付けて引いた動作を続ける正しい形。"}, {"text": "引きずれ", "is_correct": false, "explanation": "命令形。「重い荷物を引きずれ、駅の改札まで歩いた」は命令になり、事実を述べる文と合わない。"}, {"text": "引きずらない", "is_correct": false, "explanation": "否定形。荷物を引いて運んだ事実と合わない。"}, {"text": "引きずれば", "is_correct": false, "explanation": "仮定形。条件の文になり、実際に運んだ動作の描写と合わない。"}], "correct_form": "引きずって", "base_form": "引きずる", "form_label": "て形", "sentence_index": 1, "explanations": {"引きずって": "「重い荷物を引きずって歩いた」の て形。荷物を地面に付けて引いた動作を続ける正しい形。", "引きずれ": "命令形。「重い荷物を引きずれ、駅の改札まで歩いた」は命令になり、事実を述べる文と合わない。", "引きずらない": "否定形。荷物を引いて運んだ事実と合わない。", "引きずれば": "仮定形。条件の文になり、実際に運んだ動作の描写と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53516, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "古い木箱を引きずら、物置まで運んだ。", "corrected_sentence": "古い木箱を引きずって、物置まで運んだ。", "error_description": "〈引きずる〉を続ける形は「引きずって」。「引きずら」は未然形で、後に続く「運んだ」とつながらない誤りになる。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "引きずった", "is_correct": true, "explanation": "「仲間を安全な場所まで引きずった」の過去形。仲間を地面に付けて運んだ事実を表す正しい形。"}, {"text": "引きずる", "is_correct": false, "explanation": "終止形の現在形。過去に運んだ出来事を述べる文では時制が合わない。"}, {"text": "引きずり", "is_correct": false, "explanation": "連用形。文を終えられず、述語として成り立たない。"}, {"text": "引きずれ", "is_correct": false, "explanation": "命令形。事実を述べる文ではなく、命令の文になってしまう。"}], "correct_form": "引きずった", "base_form": "引きずる", "form_label": "過去形", "sentence_index": 7, "explanations": {"引きずった": "「仲間を安全な場所まで引きずった」の過去形。仲間を地面に付けて運んだ事実を表す正しい形。", "引きずる": "終止形の現在形。過去に運んだ出来事を述べる文では時制が合わない。", "引きずり": "連用形。文を終えられず、述語として成り立たない。", "引きずれ": "命令形。事実を述べる文ではなく、命令の文になってしまう。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53519, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「買う」の対象を示す目的格の「を」。"}, {"text": "が", "is_correct": false, "explanation": "「履物が母と買いに行った」では、履物が行く主体になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「履物に」は行き先や対象を表すが、履物は行き先にならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "行き先を表す「へ」は、物を対象にする文には合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「買う」の対象を示す目的格の「を」。", "が": "「履物が母と買いに行った」では、履物が行く主体になり不自然。", "に": "「履物に」は行き先や対象を表すが、履物は行き先にならないので合わない。", "へ": "行き先を表す「へ」は、物を対象にする文には合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "対象・行き先", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53519, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「履物で歩く」の手段を示す「で」。"}, {"text": "を", "is_correct": false, "explanation": "「履物を長く歩いた」では、歩く対象にならず文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「履物と歩いた」は一緒に歩く相手の意味になり、文意に合わない。"}, {"text": "の", "is_correct": false, "explanation": "「履物の長く歩いた」では連体修飾が続かず、文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "正解。「履物で歩く」の手段を示す「で」。", "を": "「履物を長く歩いた」では、歩く対象にならず文が成り立たない。", "と": "「履物と歩いた」は一緒に歩く相手の意味になり、文意に合わない。", "の": "「履物の長く歩いた」では連体修飾が続かず、文が成り立たない。"}, "error_tags": {"で": "手段", "を": "目的語", "と": "共同の相手", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53519, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "足にはくものです。靴やサンダルなどがあります。", "primary_collocate": null, "pronunciation": "はきもの", "ipa": "hakʲimono", "syllable_count": 4, "sentences": [{"text": "夏の海辺では、サンダルのように軽い履物が楽でいい。", "target_word": "履物", "complexity_tier": "T3", "furigana": "夏[なつ]の海辺[うみべ]では、サンダルのように軽[かる]い履物[はきもの]が楽[らく]でいい。", "sentence_source": "generated"}, {"text": "運動会の前に、走りやすい履物を母と買いに行った。", "target_word": "履物", "complexity_tier": "T3", "furigana": "運動会[うんどうかい]の前[まえ]に、走[はし]りやすい履物[はきもの]を母[はは]と買[か]いに行[い]った。", "sentence_source": "generated"}, {"text": "家に入るとき、履物を脱いで玄関にきちんと並べた。", "target_word": "履物", "complexity_tier": "T3", "furigana": "家[いえ]に入[はい]るとき、履物[はきもの]を脱[ぬ]いで玄関[げんかん]にきちんと並[なら]べた。", "sentence_source": "generated"}, {"text": "履物が雨で濡れたので、乾くまで外に干しておいた。", "target_word": "履物", "complexity_tier": "T3", "furigana": "履物[はきもの]が雨[あめ]で濡[ぬ]れたので、乾[かわ]くまで外[そと]に干[ほ]しておいた。", "sentence_source": "generated"}, {"text": "古くなった履物は底がすり減って、歩きにくい。", "target_word": "履物", "complexity_tier": "T3", "furigana": "古[ふる]くなった履物[はきもの]は底[そこ]がすり減[へ]って、歩[ある]きにくい。", "sentence_source": "generated"}, {"text": "この店は靴やサンダルを中心に、いろいろな履物を売っている。", "target_word": "履物", "complexity_tier": "T3", "furigana": "この店[みせ]は靴[くつ]やサンダルを中心[ちゅうしん]に、いろいろな履物[はきもの]を売[う]っている。", "sentence_source": "generated"}, {"text": "寺に入るときは、履物を脱ぐ決まりになっている。", "target_word": "履物", "complexity_tier": "T3", "furigana": "寺[てら]に入[はい]るときは、履物[はきもの]を脱[ぬ]ぐ決[き]まりになっている。", "sentence_source": "generated"}, {"text": "足に合わない履物で長く歩いたら、かかとにまめができた。", "target_word": "履物", "complexity_tier": "T3", "furigana": "足[あし]に合[あ]わない履物[はきもの]で長[なが]く歩[ある]いたら、かかとにまめができた。", "sentence_source": "generated"}, {"text": "雪の日は、滑りにくい履物を選ぶと安心だ。", "target_word": "履物", "complexity_tier": "T3", "furigana": "雪[ゆき]の日[ひ]は、滑[すべ]りにくい履物[はきもの]を選[えら]ぶと安心[あんしん]だ。", "sentence_source": "generated"}, {"text": "兄は旅行に行くたびに、その土地ならではの履物を一足買ってくる。", "target_word": "履物", "complexity_tier": "T3", "furigana": "兄[あに]は旅行[りょこう]に行[い]くたびに、その土地[とち]ならではの履物[はきもの]を一足[いっそく]買[か]ってくる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "履物", "label": "基本形"}], "register": "標準（常体）", "sense_fingerprint": "足にはくものの総称（靴・サンダルなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53519, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文房具", "is_correct": false, "explanation": "「サンダルのように軽い文房具」では、履くものを述べる文意に合わない。"}, {"text": "履物", "is_correct": true, "explanation": "正解。サンダルのように軽い、足にはくものを指す語。"}, {"text": "植木鉢", "is_correct": false, "explanation": "植木鉢は足にはくものではないので、ここには入らない。"}, {"text": "砂糖", "is_correct": false, "explanation": "砂糖は足にはくものではなく、「楽でいい」の文意に合わない。"}], "explanations": {"文房具": "「サンダルのように軽い文房具」では、履くものを述べる文意に合わない。", "履物": "正解。サンダルのように軽い、足にはくものを指す語。", "植木鉢": "植木鉢は足にはくものではないので、ここには入らない。", "砂糖": "砂糖は足にはくものではなく、「楽でいい」の文意に合わない。"}, "sentence_index": 0, "correct_answer": "履物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ズボンが落ちないように、履物を腰に巻いて出かける。", "explanation": "ここは〈ベルト〉の意味。履物は足にはくもので、腰に巻くものではないので合わない。"}, {"text": "お祝いの日に、指に履物をはめた。", "explanation": "ここは〈指輪〉の意味。履物は指にはめるものではないので合わない。"}, {"text": "雨が降ってきたので、履物を広げて歩いた。", "explanation": "ここは〈傘〉の意味。履物は広げて雨をしのぐものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53519, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寝具", "is_correct": false, "explanation": "寺で寝具を脱ぐ決まりは意味が通らず、文に入らない。"}, {"text": "履物", "is_correct": true, "explanation": "正解。寺に入るときに脱ぐものとして、足にはくものを指す語。"}, {"text": "調味料", "is_correct": false, "explanation": "調味料は脱ぐものではないので、ここには入らない。"}, {"text": "食器", "is_correct": false, "explanation": "食器を脱ぐ決まりは成り立たないので、文に合わない。"}], "explanations": {"寝具": "寺で寝具を脱ぐ決まりは意味が通らず、文に入らない。", "履物": "正解。寺に入るときに脱ぐものとして、足にはくものを指す語。", "調味料": "調味料は脱ぐものではないので、ここには入らない。", "食器": "食器を脱ぐ決まりは成り立たないので、文に合わない。"}, "sentence_index": 6, "correct_answer": "履物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日差しが強いので、つばの広い履物をかぶって歩く。", "explanation": "ここは〈帽子〉の意味。履物は足にはくもので、頭にかぶるものではないので合わない。"}, {"text": "字が小さくて読めないので、履物をかけて本を開く。", "explanation": "ここは〈眼鏡〉の意味。眼鏡はかけるが、履物はかけるものではないので合わない。"}, {"text": "風で髪が乱れないように、履物で髪をとめた。", "explanation": "ここは〈髪留め〉の意味。髪をとめるのは髪留めで、履物では髪をとめられないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53519, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海辺では、履物で持って歩くと便利だ。", "corrected_sentence": "海辺では、履物を持って歩くと便利だ。", "error_description": "誤りは「履物で」。「持つ」の目的語は「を」で、「で」だと手段の意味になり不自然。正しくは「履物を持って」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53519, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暑い日は、通気性のよい履物を選ぼと快適だ。", "corrected_sentence": "暑い日は、通気性のよい履物を選ぶと快適だ。", "error_description": "誤りは「選ぼと」。「選ぶと」の形が正しく、「選ぼ」は意志形で「と」に続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53520, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「選ぶ」の対象を示す目的格の「を」。"}, {"text": "が", "is_correct": false, "explanation": "「履物が選ぶ」だと履物が選ぶ主体になり、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "「選ぶ」の対象には「に」は付かないので不自然。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、選ぶ対象を表す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "正解。「選ぶ」の対象を示す目的格の「を」。", "が": "「履物が選ぶ」だと履物が選ぶ主体になり、文が成り立たない。", "に": "「選ぶ」の対象には「に」は付かないので不自然。", "へ": "方向を示す「へ」は、選ぶ対象を表す文には合わない。"}, "error_tags": {"を": "目的語", "が": "主語", "に": "帰着点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53520, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "正解。「AをBと呼ぶ」の「と」で、呼び名を示す。"}, {"text": "の", "is_correct": false, "explanation": "「の」では呼び名を示せず、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すので、呼び名の文には合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を表すので、「と呼ぶ」の文には合わない。"}], "correct_answer": "と", "explanations": {"と": "正解。「AをBと呼ぶ」の「と」で、呼び名を示す。", "の": "「の」では呼び名を示せず、文が成り立たない。", "から": "「から」は起点を表すので、呼び名の文には合わない。", "より": "「より」は比較や起点を表すので、「と呼ぶ」の文には合わない。"}, "error_tags": {"と": "呼び名", "の": "連体修飾", "から": "起点", "より": "比較・起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53520, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "足を保護したり温めたりするために、足にはく道具のことです。靴やスリッパなどが含まれます。", "primary_collocate": null, "pronunciation": "はきもの", "ipa": "hakʲimono", "syllable_count": 4, "sentences": [{"text": "赤いブーツは、雨の日にもよく似合う履物だ。", "target_word": "履物", "complexity_tier": "T3", "furigana": "赤[あか]いブーツは、雨[あめ]の日[ひ]にもよく似[に]合[あ]う履物[はきもの]だ。", "sentence_source": "generated"}, {"text": "雨の日は濡れても平気なように、防水の履物を選ぶことにしている。", "target_word": "履物", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は濡[ぬ]れても平気[へいき]なように、防水[ぼうすい]の履物[はきもの]を選[えら]ぶことにしている。", "sentence_source": "generated"}, {"text": "日本の家では、玄関で履物を脱いでから部屋に上がるのが習慣だ。", "target_word": "履物", "complexity_tier": "T3", "furigana": "日本[にほん]の家[いえ]では、玄関[げんかん]で履物[はきもの]を脱[ぬ]いでから部屋[へや]に上[あ]がるのが習慣[しゅうかん]だ。", "sentence_source": "generated"}, {"text": "冬は足が冷えるので、厚い靴下と暖かい履物が欠かせない。", "target_word": "履物", "complexity_tier": "T3", "furigana": "冬[ふゆ]は足[あし]が冷[ひ]えるので、厚[あつ]い靴下[くつした]と暖[あたた]かい履物[はきもの]が欠[か]かせない。", "sentence_source": "generated"}, {"text": "山道を歩くなら、底が丈夫な履物でないと足を痛めてしまう。", "target_word": "履物", "complexity_tier": "T3", "furigana": "山道[やまみち]を歩[ある]くなら、底[そこ]が丈夫[じょうぶ]な履物[はきもの]でないと足[あし]を痛[いた]めてしまう。", "sentence_source": "generated"}, {"text": "旅館の入口で履物をそろえて置くと、仲居さんが笑顔でほめてくれた。", "target_word": "履物", "complexity_tier": "T3", "furigana": "旅館[りょかん]の入口[いりぐち]で履物[はきもの]をそろえて置[お]くと、仲居[なかい]さんが笑顔[えがお]でほめてくれた。", "sentence_source": "generated"}, {"text": "祭りの前に新しい履物を買ってもらい、子どもたちはうれしそうに歩いた。", "target_word": "履物", "complexity_tier": "T3", "furigana": "祭[まつ]りの前[まえ]に新[あたら]しい履物[はきもの]を買[か]ってもらい、子[こ]どもたちはうれしそうに歩[ある]いた。", "sentence_source": "generated"}, {"text": "靴もサンダルもスリッパも、足にはく物はまとめて履物と呼ぶ。", "target_word": "履物", "complexity_tier": "T3", "furigana": "靴[くつ]もサンダルもスリッパも、足[あし]にはく物[もの]はまとめて履物[はきもの]と呼[よ]ぶ。", "sentence_source": "generated"}, {"text": "砂浜では、熱い砂から足を守るために履物が必要だ。", "target_word": "履物", "complexity_tier": "T3", "furigana": "砂浜[すなはま]では、熱[あつ]い砂[すな]から足[あし]を守[まも]るために履物[はきもの]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "玄関に見慣れない履物があったので、客が来ていると分かった。", "target_word": "履物", "complexity_tier": "T3", "furigana": "玄関[げんかん]に見慣[みな]れない履物[はきもの]があったので、客[きゃく]が来[き]ていると分[わ]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "履物", "label": "基本形"}], "register": "標準（常体）", "sense_fingerprint": "足を守り温めるために足にはく道具の総称（靴・スリッパなど）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b809ef64-f595-4298-95cf-ff21c951f823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53520, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寝具", "is_correct": false, "explanation": "寝具は寝るときに使うもので、ブーツの文には入らない。"}, {"text": "履物", "is_correct": true, "explanation": "正解。履物は足にはくもので、赤いブーツを言い表す語として合う。"}, {"text": "調味料", "is_correct": false, "explanation": "調味料は料理に使うもので、ブーツには合わない。"}, {"text": "文房具", "is_correct": false, "explanation": "文房具は書くときなどに使うもので、ブーツの文には合わない。"}], "explanations": {"寝具": "寝具は寝るときに使うもので、ブーツの文には入らない。", "履物": "正解。履物は足にはくもので、赤いブーツを言い表す語として合う。", "調味料": "調味料は料理に使うもので、ブーツには合わない。", "文房具": "文房具は書くときなどに使うもので、ブーツの文には合わない。"}, "sentence_index": 0, "correct_answer": "履物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬は手が冷えるので、厚い履物をはめて出かける。", "explanation": "ここは〈手袋〉の意味。履物は足にはくもので、手にはめるものではないので合わない。"}, {"text": "寒い朝は、首に厚い履物をぐるぐる巻いて出かける。", "explanation": "ここは〈マフラー〉の意味。首に巻くのは履物ではないので合わない。"}, {"text": "寒い夜は、厚い履物を体の上に掛けて寝る。", "explanation": "ここは〈毛布〉の意味。履物は体に掛けて使うものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53520, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食器", "is_correct": false, "explanation": "「食器を買ってもらい、歩いた」は流れが合わず、文意に入らない。"}, {"text": "履物", "is_correct": true, "explanation": "正解。新しい履物を買ってもらい、うれしそうに歩くという文意に合う語。"}, {"text": "玩具", "is_correct": false, "explanation": "玩具は歩いて使うものではなく、「歩いた」の流れと合わない。"}, {"text": "植木鉢", "is_correct": false, "explanation": "植木鉢を買って歩くのは不自然で、文の流れに合わない。"}], "explanations": {"食器": "「食器を買ってもらい、歩いた」は流れが合わず、文意に入らない。", "履物": "正解。新しい履物を買ってもらい、うれしそうに歩くという文意に合う語。", "玩具": "玩具は歩いて使うものではなく、「歩いた」の流れと合わない。", "植木鉢": "植木鉢を買って歩くのは不自然で、文の流れに合わない。"}, "sentence_index": 6, "correct_answer": "履物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の日差しが強いので、つばの広い履物をかぶって出かける。", "explanation": "ここは〈帽子〉の意味。履物は足にはくもので、頭にかぶるものではないので合わない。"}, {"text": "時間を確かめるため、腕に履物を着けている。", "explanation": "ここは〈腕時計〉の意味。履物は腕に着けるものではないので合わない。"}, {"text": "細かい字を読むため、履物をかけて本を開いた。", "explanation": "ここは〈眼鏡〉の意味。眼鏡はかけるが、履物はかけるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53520, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の日は防水の履物が選ぶ。", "corrected_sentence": "雨の日は防水の履物を選ぶ。", "error_description": "誤りは「履物が」。「選ぶ」の目的語には「を」が必要で、「が」だと履物が選ぶ主体になり文が成り立たない。正しくは「履物を選ぶ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53520, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪の日は、滑りにくい履物を選んことが大切だ。", "corrected_sentence": "雪の日は、滑りにくい履物を選ぶことが大切だ。", "error_description": "誤りは「選んこと」。正しくは辞書形の「選ぶこと」。「選ん」は動詞の語形が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31942f30-1e5a-410a-912b-f5f20951208d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53527, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "自動詞「鳴る」の主語を示す「が」で、ここに正しく入る。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は自動詞「鳴る」には使えない。"}, {"text": "に", "is_correct": false, "explanation": "「ベルに鳴った」は不自然で、主語を示す「が」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は「鳴る」の文には合わない。"}], "correct_answer": "が", "explanations": {"が": "自動詞「鳴る」の主語を示す「が」で、ここに正しく入る。", "を": "目的語の「を」は自動詞「鳴る」には使えない。", "に": "「ベルに鳴った」は不自然で、主語を示す「が」が必要。", "へ": "方向を示す「へ」は「鳴る」の文には合わない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53527, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「押す」の目的語を示す「を」で、ベルを押すので正しい。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す「が」は、「押す」の目的語には使えない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示す「で」は、押す対象のベルには合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は、この文の構造に合わない。"}], "correct_answer": "を", "explanations": {"を": "「押す」の目的語を示す「を」で、ベルを押すので正しい。", "が": "主語を示す「が」は、「押す」の目的語には使えない。", "で": "手段を示す「で」は、押す対象のベルには合わない。", "より": "比較の「より」は、この文の構造に合わない。"}, "error_tags": {"が": "主語", "で": "手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53527, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "金属やプラスチックで作られた丸い形のもので、たたくと音が出ます。", "primary_collocate": null, "pronunciation": "べる", "ipa": "beɾɯ", "syllable_count": 2, "sentences": [{"text": "自転車のベルを鳴らして、前の人に知らせました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]のベルを鳴[な]らして、前[まえ]の人[ひと]に知[し]らせました。", "sentence_source": "generated"}, {"text": "玄関のベルが鳴ったので、ドアを開けました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "玄関[げんかん]のベルが鳴[な]ったので、ドアを開[あ]けました。", "sentence_source": "generated"}, {"text": "朝、目覚まし時計のベルで起きました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "朝[あさ]、目覚[めざ]まし時計[どけい]のベルで起[お]きました。", "sentence_source": "generated"}, {"text": "猫の首に小さなベルをつけました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "猫[ねこ]の首[くび]に小[ちい]さなベルをつけました。", "sentence_source": "generated"}, {"text": "授業の終わりを知らせるベルが、校内に響きました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の終[お]わりを知[し]らせるベルが、校内[こうない]に響[ひび]きました。", "sentence_source": "generated"}, {"text": "レストランの席には、店員を呼ぶベルが置いてあります。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "レストランの席[せき]には、店員[てんいん]を呼[よ]ぶベルが置[お]いてあります。", "sentence_source": "generated"}, {"text": "ベルの音が聞こえたので、電話に出ました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "ベルの音[おと]が聞[き]こえたので、電話[でんわ]に出[で]ました。", "sentence_source": "generated"}, {"text": "受付のベルを押すと、係の人が来ます。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "受付[うけつけ]のベルを押[お]すと、係[かかり]の人[ひと]が来[き]ます。", "sentence_source": "generated"}, {"text": "犬が走るたびに、首のベルが鳴ります。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "犬[いぬ]が走[はし]るたびに、首[くび]のベルが鳴[な]ります。", "sentence_source": "generated"}, {"text": "駅で発車のベルが鳴り、私は急いで電車に乗りました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "駅[えき]で発車[はっしゃ]のベルが鳴[な]り、私[わたし]は急[いそ]いで電車[でんしゃ]に乗[の]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ベル", "label": "基本形"}], "register": "polite", "sense_fingerprint": "自転車・玄関・時計などにある、鳴らして知らせる身近な小さい鈴や呼び鈴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53527, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ベル", "is_correct": true, "explanation": "自転車で音を鳴らして知らせる部品で、「鳴らして、知らせました」に合う。"}, {"text": "タイヤ", "is_correct": false, "explanation": "自転車の部品だが、鳴らして音を出すものではないので合わない。"}, {"text": "サドル", "is_correct": false, "explanation": "乗るための座席で、音を鳴らすものではないので合わない。"}, {"text": "ペダル", "is_correct": false, "explanation": "足で踏む部品で、鳴らして知らせるものではないので合わない。"}], "explanations": {"ベル": "自転車で音を鳴らして知らせる部品で、「鳴らして、知らせました」に合う。", "タイヤ": "自転車の部品だが、鳴らして音を出すものではないので合わない。", "サドル": "乗るための座席で、音を鳴らすものではないので合わない。", "ペダル": "足で踏む部品で、鳴らして知らせるものではないので合わない。"}, "sentence_index": 0, "correct_answer": "ベル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "疲れたので、帰ってすぐベルに入りました。", "explanation": "ここは〈ベッド〉（寝台）の意味。鈴のベルは入る場所ではないので合わない。"}, {"text": "花嫁は白いベルで顔を隠していました。", "explanation": "顔を隠すのは〈ベール〉（布）で、〈ベル〉（鈴）とは混同されやすいが別の語。"}, {"text": "寒かったので、コートのベルを締めました。", "explanation": "ここは〈ベルト〉（帯）の意味。鈴のベルは締めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53527, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ベル", "is_correct": true, "explanation": "鳴ると音が出るもので、「ベルの音が聞こえた」に合う。"}, {"text": "ハンカチ", "is_correct": false, "explanation": "布製品で音を出すものではないので、「の音」とは合わない。"}, {"text": "メガネ", "is_correct": false, "explanation": "視力を補う道具で、音が聞こえる対象ではないので合わない。"}, {"text": "ケーキ", "is_correct": false, "explanation": "食べ物で音を出すものではないので、「の音」とは合わない。"}], "explanations": {"ベル": "鳴ると音が出るもので、「ベルの音が聞こえた」に合う。", "ハンカチ": "布製品で音を出すものではないので、「の音」とは合わない。", "メガネ": "視力を補う道具で、音が聞こえる対象ではないので合わない。", "ケーキ": "食べ物で音を出すものではないので、「の音」とは合わない。"}, "sentence_index": 6, "correct_answer": "ベル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公園のベルに座って、本を読みました。", "explanation": "ここは〈ベンチ〉（腰掛け）の意味。鈴のベルは座るものではないので合わない。"}, {"text": "ベルで洗濯物を干しました。", "explanation": "〈ベランダ〉と混同。鈴は洗濯物を干す場所にならない。"}, {"text": "夏休みにベルに行って、チョコレートを買いました。", "explanation": "ここは〈ベルギー〉（国名）の意味。鈴のベルは行く先にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53527, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自転車のベルが鳴らして、道を空けてもらいました。", "corrected_sentence": "自転車のベルを鳴らして、道を空けてもらいました。", "error_description": "「鳴らす」は他動詞なので、ベルの後は「を」が正しい。「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53527, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベルを音が聞こえたので、ドアを開けました。", "corrected_sentence": "ベルの音が聞こえたので、ドアを開けました。", "error_description": "「ベルの音」の「の」が「を」になっている。「音」の前は「の」が正しく、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53528, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「正午を知らせる」の主語を示す「が」で、ここに正しく入る。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、すでに「正午を」があるので重ねられず合わない。"}, {"text": "に", "is_correct": false, "explanation": "「ベルに正午を知らせる」は不自然で、主語の「が」が必要。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」は、この文の主語にはならないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「正午を知らせる」の主語を示す「が」で、ここに正しく入る。", "を": "目的語の「を」は、すでに「正午を」があるので重ねられず合わない。", "に": "「ベルに正午を知らせる」は不自然で、主語の「が」が必要。", "へ": "方向を示す「へ」は、この文の主語にはならないので合わない。"}, "error_tags": {"を": "目的語", "に": "位置", "へ": "方向"}, "sentence_index": 0}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53528, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「ベルの内側」の「の」で、ベルと内側を結ぶので正しい。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」は、「当たる」の文では支える動詞がなく合わない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」は、ベルと内側を結ぶのには合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」は、棒が当たる先を示す文としては不自然で合わない。"}], "correct_answer": "の", "explanations": {"の": "「ベルの内側」の「の」で、ベルと内側を結ぶので正しい。", "を": "目的語の「を」は、「当たる」の文では支える動詞がなく合わない。", "で": "場所や手段を示す「で」は、ベルと内側を結ぶのには合わない。", "へ": "方向の「へ」は、棒が当たる先を示す文としては不自然で合わない。"}, "error_tags": {"を": "目的語", "で": "場所・手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53528, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "金属製などの円錐形または半球形の物体。内部に撞木を持ち、外部から衝撃を加えると鳴る仕組みになっている。時報や宗教儀式、装飾品などに用いられる。", "primary_collocate": null, "pronunciation": "べる", "ipa": "beɾɯ", "syllable_count": 2, "sentences": [{"text": "教会のベルが、正午を知らせました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "教会[きょうかい]のベルが、正午[しょうご]を知[し]らせました。", "sentence_source": "generated"}, {"text": "結婚式で、大きなベルが鳴らされました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]で、大[おお]きなベルが鳴[な]らされました。", "sentence_source": "generated"}, {"text": "古い時計台には、青銅で作られたベルがあります。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "古[ふる]い時計台[とけいだい]には、青銅[せいどう]で作[つく]られたベルがあります。", "sentence_source": "generated"}, {"text": "クリスマスの飾りに、金色のベルをつけました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "クリスマスの飾[かざ]りに、金色[きんいろ]のベルをつけました。", "sentence_source": "generated"}, {"text": "礼拝の前に、神父がベルを鳴らします。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "礼拝[れいはい]の前[まえ]に、神父[しんぷ]がベルを鳴[な]らします。", "sentence_source": "generated"}, {"text": "塔の上のベルは、毎時ちょうどに音を出します。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "塔[とう]の上[うえ]のベルは、毎時[まいじ]ちょうどに音[おと]を出[だ]します。", "sentence_source": "generated"}, {"text": "博物館には、二百年前のベルが展示されています。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]には、二百年[にひゃくねん]前[まえ]のベルが展示[てんじ]されています。", "sentence_source": "generated"}, {"text": "ベルの内側の棒が当たると、高い音が出ます。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "ベルの内側[うちがわ]の棒[ぼう]が当[あ]たると、高[たか]い音[おと]が出[で]ます。", "sentence_source": "generated"}, {"text": "港町では、霧の日に船のベルが鳴ります。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "港町[みなとまち]では、霧[きり]の日[ひ]に船[ふね]のベルが鳴[な]ります。", "sentence_source": "generated"}, {"text": "式の始まりを告げるベルの音が、広間に響きました。", "target_word": "ベル", "complexity_tier": "T3", "furigana": "式[しき]の始[はじ]まりを告[つ]げるベルの音[おと]が、広間[ひろま]に響[ひび]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ベル", "label": "基本形"}], "register": "polite", "sense_fingerprint": "教会・時計塔・儀式・飾りなどに使われる、内部に舌を持つ金属製の釣り鐘形の鐘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35216ce1-5f8f-42d2-939c-3c153ea82559') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53528, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ベル", "is_correct": true, "explanation": "正午を知らせる教会の鐘の一種で、「正午を知らせました」に合う。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓にかける布で、時を知らせることはないので合わない。"}, {"text": "ベンチ", "is_correct": false, "explanation": "座るための腰掛けで、時を知らせることはないので合わない。"}, {"text": "ポスター", "is_correct": false, "explanation": "壁に貼る紙で、時を知らせることはないので合わない。"}], "explanations": {"ベル": "正午を知らせる教会の鐘の一種で、「正午を知らせました」に合う。", "カーテン": "窓にかける布で、時を知らせることはないので合わない。", "ベンチ": "座るための腰掛けで、時を知らせることはないので合わない。", "ポスター": "壁に貼る紙で、時を知らせることはないので合わない。"}, "sentence_index": 0, "correct_answer": "ベル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はベルの料理人で、包丁の扱いが上手です。", "explanation": "ここは〈ベテラン〉（経験豊かな人）の意味。鈴のベルでは人を表せないので合わない。"}, {"text": "寝る前に、ベルに横になりました。", "explanation": "〈ベッド〉（寝台）と混同。鈴は横になる場所ではないので合わない。"}, {"text": "夏休みに、ベルへ一人旅をしました。", "explanation": "ここは〈ベルリン〉（都市名）の意味。鈴のベルは旅先にならないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53528, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ベル", "is_correct": true, "explanation": "博物館に展示される古い教会の鐘で、「展示されています」に合う。"}, {"text": "雨", "is_correct": false, "explanation": "空から降る水で、展示されるものではないので合わない。"}, {"text": "風", "is_correct": false, "explanation": "空気の動きで、展示されるものではないので合わない。"}, {"text": "霧", "is_correct": false, "explanation": "大気中の水滴で、展示されるものではないので合わない。"}], "explanations": {"ベル": "博物館に展示される古い教会の鐘で、「展示されています」に合う。", "雨": "空から降る水で、展示されるものではないので合わない。", "風": "空気の動きで、展示されるものではないので合わない。", "霧": "大気中の水滴で、展示されるものではないので合わない。"}, "sentence_index": 6, "correct_answer": "ベル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "式で、花嫁は白いベルを頭にかぶっていました。", "explanation": "ここは〈ベール〉（布）の意味で、〈ベル〉（鈴）とは混同されやすいが別の語。"}, {"text": "登山隊は、山のふもとをベルにしました。", "explanation": "ここは〈ベース〉（拠点）の意味。このベルは拠点として使うものではないので合わない。"}, {"text": "公園のベルに座りました。", "explanation": "〈ベンチ〉（腰掛け）と混同。鈴のベルは座るものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53528, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "教会のベルを、毎朝六時を知らせます。", "corrected_sentence": "教会のベルが、毎朝六時を知らせます。", "error_description": "「知らせる」の主語は「ベル」なので「が」が正しい。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53528, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "博物館の展示室には、古いベルを並んでいます。", "corrected_sentence": "博物館の展示室には、古いベルが並んでいます。", "error_description": "「並ぶ」は自動詞なので、主語のベルには「が」が必要。「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dca4172-5642-4f21-8f33-f600f83db5ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53539, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "書き換えられる対象（題名）を示す目的語の「を」。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。題名は書き換えの主体にならず、「題名が書き換えた」では文意が合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「題名の書き換えた」では文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "相手の「と」。題名を相手にして書き換えるという文意に合わない。"}], "correct_answer": "を", "explanations": {"を": "書き換えられる対象（題名）を示す目的語の「を」。", "が": "主語の「が」。題名は書き換えの主体にならず、「題名が書き換えた」では文意が合わない。", "の": "連体修飾の「の」。「題名の書き換えた」では文が成立しない。", "と": "相手の「と」。題名を相手にして書き換えるという文意に合わない。"}, "error_tags": {"が": "主語（題名は書き換えの主体にならない）", "の": "連体修飾（文が成立しない）", "と": "相手（文意に合わない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53539, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "書き換えの対象（文字）を示す他動詞の目的語「を」。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。文字は移動先ではなく、「文字へ書き換えた」では文意が合わない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。文字は書き換えの主体にならず、目的語のない「文字が書き換えた」は文意が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「文字の書き換えた」は名詞に続かず、文が成立しない。"}], "correct_answer": "を", "explanations": {"を": "書き換えの対象（文字）を示す他動詞の目的語「を」。", "へ": "方向の「へ」。文字は移動先ではなく、「文字へ書き換えた」では文意が合わない。", "が": "主語の「が」。文字は書き換えの主体にならず、目的語のない「文字が書き換えた」は文意が成り立たない。", "の": "連体修飾の「の」。「文字の書き換えた」は名詞に続かず、文が成立しない。"}, "error_tags": {"へ": "方向（移動先として文意に合わない）", "が": "主語（書き換える行為の主体にならない）", "の": "連体修飾（文が成立しない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53539, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "かいたものを、ほかのものにかえます。", "primary_collocate": null, "pronunciation": "かきかえる", "ipa": "kakikaeɾɯ", "syllable_count": 5, "sentences": [{"text": "先生は黒板の文字を消して、新しい答えに書き換えた。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "先生[せんせい]は黒板[こくばん]の文字[もじ]を消[け]して、新[あたら]しい答[こた]えに書[か]き換[か]えた。", "sentence_source": "generated"}, {"text": "間違いに気づいて、レポートの題名を書き換えた。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "間違[まちが]いに気[き]づいて、レポートの題名[だいめい]を書[か]き換[か]えた。", "sentence_source": "generated"}, {"text": "住所が変わったので、名簿の住所を書き換えてください。", "target_word": "書き換えて", "complexity_tier": "T3", "furigana": "住所[じゅうしょ]が変[か]わったので、名簿[めいぼ]の住所[じゅうしょ]を書[か]き換[か]えてください。", "sentence_source": "generated"}, {"text": "兄はメモの電話番号を、新しい番号に書き換えた。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "兄[あに]はメモの電話番号[でんわばんごう]を、新[あたら]しい番号[ばんごう]に書[か]き換[か]えた。", "sentence_source": "generated"}, {"text": "手紙の下書きを読み直して、失礼な部分を書き換えた。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "手紙[てがみ]の下書[したが]きを読[よ]み直[なお]して、失礼[しつれい]な部分[ぶぶん]を書[か]き換[か]えた。", "sentence_source": "generated"}, {"text": "この文は長すぎるので、短く書き換えたほうがいい。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "この文[ぶん]は長[なが]すぎるので、短[みじか]く書[か]き換[か]えたほうがいい。", "sentence_source": "generated"}, {"text": "母は古いレシピのノートを、見やすく書き換えている。", "target_word": "書き換えて", "complexity_tier": "T3", "furigana": "母[はは]は古[ふる]いレシピのノートを、見[み]やすく書[か]き換[か]えている。", "sentence_source": "generated"}, {"text": "予定が変わったので、カレンダーの文字を書き換えた。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "予定[よてい]が変[か]わったので、カレンダーの文字[もじ]を書[か]き換[か]えた。", "sentence_source": "generated"}, {"text": "彼は物語の終わりを書き換えて、悲しい結末を明るいものにした。", "target_word": "書き換えて", "complexity_tier": "T3", "furigana": "彼[かれ]は物語[ものがたり]の終[お]わりを書[か]き換[か]えて、悲[かな]しい結末[けつまつ]を明[あか]るいものにした。", "sentence_source": "generated"}, {"text": "作文の言葉を、もっと丁寧な言い方に書き換えました。", "target_word": "書き換えました", "complexity_tier": "T3", "furigana": "作文[さくぶん]の言葉[ことば]を、もっと丁寧[ていねい]な言[い]い方[かた]に書[か]き換[か]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "書き換える", "label": "dictionary form"}, {"form": "書き換えます", "label": "polite form"}, {"form": "書き換えない", "label": "negative form"}, {"form": "書き換えた", "label": "past form"}, {"form": "書き換えて", "label": "te-form"}, {"form": "書き換えれば", "label": "conditional form"}, {"form": "書き換えられる", "label": "potential/passive form"}, {"form": "書き換えよう", "label": "volitional form"}], "register": "neutral", "sense_fingerprint": "紙や黒板などに書いた文字・文章を別の文字・文章に直す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53539, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書き換えた", "is_correct": true, "explanation": "た形で文末に来て、「新しい答えに書き換えた」と文が完結する。"}, {"text": "書き換え", "is_correct": false, "explanation": "連用形で文末に置くと完結せず、「書き換え。」は文として成立しない。"}, {"text": "書き換えれば", "is_correct": false, "explanation": "仮定形で、続く主節がないと文が完結しない。"}, {"text": "書き換えず", "is_correct": false, "explanation": "連用の否定形で、文を終えられない。「書き換えず。」は不成立。"}], "explanations": {"書き換えた": "た形で文末に来て、「新しい答えに書き換えた」と文が完結する。", "書き換え": "連用形で文末に置くと完結せず、「書き換え。」は文として成立しない。", "書き換えれば": "仮定形で、続く主節がないと文が完結しない。", "書き換えず": "連用の否定形で、文を終えられない。「書き換えず。」は不成立。"}, "sentence_index": 0, "correct_answer": "書き換えた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "兄は古い壁紙を書き換えて、部屋を明るくした。", "explanation": "ここは〈張り替える〉の意味。壁紙は文字や内容ではないので、〈書き換える〉は使わない。"}, {"text": "兄は割れた皿を書き換えた。", "explanation": "ここは〈取り替える〉の意味。割れた皿を新しいものに替えることは書き換えるとは言わず、書かれた内容が対象でない。"}, {"text": "兄は自転車の色を書き換えた。", "explanation": "ここは〈塗り替える〉の意味。色を塗り直すことは書き換えるとは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53539, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "書き換えて", "is_correct": true, "explanation": "て形で、「〜いる」に続けて「書き換えている」となり、文が成立する。"}, {"text": "書き換えた", "is_correct": false, "explanation": "た形は「〜いる」に続かず、「見やすく書き換えたいる」は成立しない。"}, {"text": "書き換えます", "is_correct": false, "explanation": "丁寧な現在形は「〜いる」の前に入らず、「書き換えますいる」は不成立。"}, {"text": "書き換えたい", "is_correct": false, "explanation": "希望の形は「いる」につながらず、「書き換えたいいる」は不成立。"}], "explanations": {"書き換えて": "て形で、「〜いる」に続けて「書き換えている」となり、文が成立する。", "書き換えた": "た形は「〜いる」に続かず、「見やすく書き換えたいる」は成立しない。", "書き換えます": "丁寧な現在形は「〜いる」の前に入らず、「書き換えますいる」は不成立。", "書き換えたい": "希望の形は「いる」につながらず、「書き換えたいいる」は不成立。"}, "sentence_index": 6, "correct_answer": "書き換えて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は食器棚の場所を書き換えた。", "explanation": "ここは〈入れ替える〉（位置を入れ替える）の意味。場所の入れ替えは書き換えるとは言わない。"}, {"text": "父は自転車のベルを書き換えた。", "explanation": "ここは〈付け替える〉の意味。部品を取り付け直すことは書き換えるで言えない。"}, {"text": "先生は教室の机の配置を書き換えた。", "explanation": "ここは〈組み替える〉の意味。机の配置は文字や内容ではないので、〈書き換える〉の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53539, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "誤字に気づいて、掲示板の案内文に正しい表記に書き換えた。", "corrected_sentence": "誤字に気づいて、掲示板の案内文を正しい表記に書き換えた。", "error_description": "誤りは助詞の「に」。「書き換える」では書き換える対象（案内文）に「を」をつける。「案内文に」では対象が示されず、文が不自然になる。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "書き換えた", "is_correct": true, "explanation": "過去の完了を表し、「間違いに気づいて、題名を書き換えた」と順序が合う。"}, {"text": "書き換え", "is_correct": false, "explanation": "連用形。文末に置くと文が完結せず、「題名を書き換え。」は成立しない。"}, {"text": "書き換えれば", "is_correct": false, "explanation": "仮定形。続く主節がないと文が完結せず、過去の行為も表さない。"}, {"text": "書き換えて", "is_correct": false, "explanation": "て形。文末に置けず、文が完結しない。"}], "correct_form": "書き換えた", "base_form": "書き換える", "form_label": "過去形", "sentence_index": 1, "explanations": {"書き換えた": "過去の完了を表し、「間違いに気づいて、題名を書き換えた」と順序が合う。", "書き換え": "連用形。文末に置くと文が完結せず、「題名を書き換え。」は成立しない。", "書き換えれば": "仮定形。続く主節がないと文が完結せず、過去の行為も表さない。", "書き換えて": "て形。文末に置けず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53539, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ミスに気づき、張り紙の日付を書き換えたた。", "corrected_sentence": "ミスに気づき、張り紙の日付を書き換えた。", "error_description": "誤りは「書き換えたた」。過去の「た」を重ねた形で、正しくは「書き換えた」と「た」は一度だけ使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "書き換えた", "is_correct": true, "explanation": "過去の完了を表し、「予定が変わったので文字を書き換えた」と文意が合う。"}, {"text": "書き換えられた", "is_correct": false, "explanation": "受身の過去形になり、「文字を」の目的語と合わず、「文字が書き換えられた」にすれば主語が変わる。"}, {"text": "書き換えず", "is_correct": false, "explanation": "連用の否定形。文末に置くと文が完結しない。"}, {"text": "書き換えられ", "is_correct": false, "explanation": "連用形で文末に置けず、文が完結しない。"}], "correct_form": "書き換えた", "base_form": "書き換える", "form_label": "過去形", "sentence_index": 7, "explanations": {"書き換えた": "過去の完了を表し、「予定が変わったので文字を書き換えた」と文意が合う。", "書き換えられた": "受身の過去形になり、「文字を」の目的語と合わず、「文字が書き換えられた」にすれば主語が変わる。", "書き換えず": "連用の否定形。文末に置くと文が完結しない。", "書き換えられ": "連用形で文末に置けず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53540, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "変化後の内容を表す「に」。「新しい情報に書き換えた」で、書き換えた先の内容を示し、文意に合う。"}, {"text": "が", "is_correct": false, "explanation": "主語を表す「が」。書き換える行為の主体にならず、「新しい情報が書き換えた」は文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「新しい情報の書き換えた」は名詞に続かず、文が成立しない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」。ここは比べる文脈がなく、文意に合わない。"}], "correct_answer": "に", "explanations": {"に": "変化後の内容を表す「に」。「新しい情報に書き換えた」で、書き換えた先の内容を示し、文意に合う。", "が": "主語を表す「が」。書き換える行為の主体にならず、「新しい情報が書き換えた」は文が成り立たない。", "の": "連体修飾の「の」。「新しい情報の書き換えた」は名詞に続かず、文が成立しない。", "より": "比較を表す「より」。ここは比べる文脈がなく、文意に合わない。"}, "error_tags": {"が": "主語（書き換える行為の主体にならない）", "より": "比較（文意に合わない）", "の": "連体修飾（文が成立しない）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53540, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "書き換える行為の対象（プログラムの一部）を示す他動詞の目的語「を」。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「一部の書き換えた」は名詞に続かず、文が成立しない。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「一部が書き換えた」では目的語がなく、文意が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。書き換えの対象は方向を表さず、「一部へ書き換えた」は不自然。"}], "correct_answer": "を", "explanations": {"を": "書き換える行為の対象（プログラムの一部）を示す他動詞の目的語「を」。", "の": "連体修飾の「の」。「一部の書き換えた」は名詞に続かず、文が成立しない。", "が": "主語の「が」。「一部が書き換えた」では目的語がなく、文意が成り立たない。", "へ": "方向の「へ」。書き換えの対象は方向を表さず、「一部へ書き換えた」は不自然。"}, "error_tags": {"へ": "方向（書き換えの対象ではない）", "の": "連体修飾（文が成立しない）", "が": "主語（書き換える行為の主体にならない）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53540, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "すでに書かれた文字や内容などを、別のものに変更すること。", "primary_collocate": null, "pronunciation": "かきかえる", "ipa": "kakikaeɾɯ", "syllable_count": 5, "sentences": [{"text": "古いメモの文字を、どう書き換えているのか。", "target_word": "書き換え", "complexity_tier": "T3", "furigana": "古[ふる]いメモの文字[もじ]を、どう書[か]き換[か]えているのか。", "sentence_source": "generated"}, {"text": "古いデータが残っていたので、新しい情報に書き換えた。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "古[ふる]いデータが残[のこ]っていたので、新[あたら]しい情報[じょうほう]に書[か]き換[か]えた。", "sentence_source": "generated"}, {"text": "彼は不正に会社の記録を書き換えて、解雇された。", "target_word": "書き換えて", "complexity_tier": "T3", "furigana": "彼[かれ]は不正[ふせい]に会社[かいしゃ]の記録[きろく]を書[か]き換[か]えて、解雇[かいこ]された。", "sentence_source": "generated"}, {"text": "この発見は、これまでの教科書の内容を書き換えるほど重要だ。", "target_word": "書き換える", "complexity_tier": "T3", "furigana": "この発見[はっけん]は、これまでの教科書[きょうかしょ]の内容[ないよう]を書[か]き換[か]えるほど重要[じゅうよう]だ。", "sentence_source": "generated"}, {"text": "祖父は病気になってから、遺言書を書き換えた。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "祖父[そふ]は病気[びょうき]になってから、遺言書[ゆいごんしょ]を書[か]き換[か]えた。", "sentence_source": "generated"}, {"text": "設定ファイルを書き換えてから、もう一度ソフトを起動してください。", "target_word": "書き換えて", "complexity_tier": "T3", "furigana": "設定[せってい]ファイルを書[か]き換[か]えてから、もう一度[いちど]ソフトを起動[きどう]してください。", "sentence_source": "generated"}, {"text": "新しい法律ができたので、契約書の古い条文を書き換えなければならない。", "target_word": "書き換え", "complexity_tier": "T3", "furigana": "新[あたら]しい法律[ほうりつ]ができたので、契約書[けいやくしょ]の古[ふる]い条文[じょうぶん]を書[か]き換[か]えなければならない。", "sentence_source": "generated"}, {"text": "開発者はウイルス対策のため、プログラムの一部を書き換えた。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "開発者[かいはつしゃ]はウイルス対策[たいさく]のため、プログラムの一部[いちぶ]を書[か]き換[か]えた。", "sentence_source": "generated"}, {"text": "編集者は読みにくい文章を、やさしい表現に書き換えた。", "target_word": "書き換えた", "complexity_tier": "T3", "furigana": "編集者[へんしゅうしゃ]は読[よ]みにくい文章[ぶんしょう]を、やさしい表現[ひょうげん]に書[か]き換[か]えた。", "sentence_source": "generated"}, {"text": "市は古い規則を書き換えることで、手続きを簡単にした。", "target_word": "書き換える", "complexity_tier": "T3", "furigana": "市[し]は古[ふる]い規則[きそく]を書[か]き換[か]えることで、手続[てつづ]きを簡単[かんたん]にした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "書き換える", "label": "dictionary form"}, {"form": "書き換えます", "label": "polite form"}, {"form": "書き換えない", "label": "negative form"}, {"form": "書き換えた", "label": "past form"}, {"form": "書き換えて", "label": "te-form"}, {"form": "書き換えれば", "label": "conditional form"}, {"form": "書き換えられる", "label": "potential/passive form"}, {"form": "書き換えよう", "label": "volitional form"}], "register": "neutral", "sense_fingerprint": "すでにある文字・データ・内容を別の内容に変更する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e064089-d9b2-48bf-a97c-c43dc8016428') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53540, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "書き換え", "is_correct": true, "explanation": "連用形。「どう〜ている」の空所に入り、「書き換えている」の語幹になる。"}, {"text": "書き換えた", "is_correct": false, "explanation": "た形は「〜ている」につながらず、「どう書き換えたている」は成立しない。"}, {"text": "書き換えて", "is_correct": false, "explanation": "て形を入れると「書き換えてている」となり、「ている」と重なって成立しない。"}, {"text": "書き換えよう", "is_correct": false, "explanation": "意向形は「〜ている」に続かず、「どう書き換えようているのか」は成立しない。"}], "explanations": {"書き換え": "連用形。「どう〜ている」の空所に入り、「書き換えている」の語幹になる。", "書き換えた": "た形は「〜ている」につながらず、「どう書き換えたている」は成立しない。", "書き換えて": "て形を入れると「書き換えてている」となり、「ている」と重なって成立しない。", "書き換えよう": "意向形は「〜ている」に続かず、「どう書き換えようているのか」は成立しない。"}, "sentence_index": 0, "correct_answer": "書き換え"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "古い蛍光灯を新しい電球に書き換えた。", "explanation": "ここは〈置き換える〉（物を別の物に取り替える）の意味。書き換えるは文字や記録など書かれた内容を変えることに使い、電球の取り替えには言わない。"}, {"text": "壊れた部品を書き換えて、機械を直した。", "explanation": "ここは〈交換する〉の意味。部品の取り替えは書き換えるでは言わず、書かれたものが対象になる。"}, {"text": "この発見は、教室の窓ガラスを書き換えるほど重要だ。", "explanation": "ここは〈取り替える〉（ものを新しいものに替える）の意味。窓ガラスは文字や内容が書かれたものではないので、〈書き換える〉の対象にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53540, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "書き換え", "is_correct": true, "explanation": "連用形。「書き換えなければならない」と続く形で、文意が成立する。"}, {"text": "書き換えれば", "is_correct": false, "explanation": "仮定形は「なければならない」に続かず、「書き換えればなければならない」は成立しない。"}, {"text": "書き換えたい", "is_correct": false, "explanation": "希望の形は「なければならない」に続けられず、「書き換えたいなければ」は不成立。"}, {"text": "書き換えず", "is_correct": false, "explanation": "連用の否定形は「なければならない」の前に置けず、「書き換えずなければならない」は成立しない。"}], "explanations": {"書き換え": "連用形。「書き換えなければならない」と続く形で、文意が成立する。", "書き換えれば": "仮定形は「なければならない」に続かず、「書き換えればなければならない」は成立しない。", "書き換えたい": "希望の形は「なければならない」に続けられず、「書き換えたいなければ」は不成立。", "書き換えず": "連用の否定形は「なければならない」の前に置けず、「書き換えずなければならない」は成立しない。"}, "sentence_index": 6, "correct_answer": "書き換え"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "席の順番を書き換えて、みんなで座り直した。", "explanation": "ここは〈入れ替える〉（順序を入れ替える）の意味。順番は書かれた内容ではないので、〈書き換える〉は使わない。"}, {"text": "壊れた鍵を書き換えて、家に入った。", "explanation": "ここは〈取り替える〉の意味。鍵の取り替えは書き換えるでは言わず、書かれたものが対象にならない。"}, {"text": "市は古い建物を書き換えて、新しい図書館にした。", "explanation": "ここは〈作り替える〉の意味。建物を造り直すことは作り替えるで言い、文字や内容を変える〈書き換える〉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53540, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい法律に合わせて、会社は就業規則を書き換えるた。", "corrected_sentence": "新しい法律に合わせて、会社は就業規則を書き換えた。", "error_description": "誤りは「書き換えるた」。辞書形に「た」を直接つけた形で、正しい過去形は「書き換えた」。一段動詞は「る」を取ってから「た」をつける。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "書き換えた", "is_correct": true, "explanation": "過去の完了を表し、「残っていたので、新しい情報に書き換えた」と文意が合う。"}, {"text": "書き換え", "is_correct": false, "explanation": "連用形。文末に置けず、「新しい情報に書き換え。」は文が完結しない。"}, {"text": "書き換えれば", "is_correct": false, "explanation": "仮定形。続く主節がないと文が完結せず、過去の行為も表さない。"}, {"text": "書き換えて", "is_correct": false, "explanation": "て形。文末に置けず、文が完結しない。"}], "correct_form": "書き換えた", "base_form": "書き換える", "form_label": "過去形", "sentence_index": 1, "explanations": {"書き換えた": "過去の完了を表し、「残っていたので、新しい情報に書き換えた」と文意が合う。", "書き換え": "連用形。文末に置けず、「新しい情報に書き換え。」は文が完結しない。", "書き換えれば": "仮定形。続く主節がないと文が完結せず、過去の行為も表さない。", "書き換えて": "て形。文末に置けず、文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53540, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ウイルスが見つかったので、古いプログラムが書き換えた。", "corrected_sentence": "ウイルスが見つかったので、古いプログラムを書き換えた。", "error_description": "誤りは助詞の「が」。「書き換える」は対象を取る他動詞なので、書き換えられる対象には「を」をつける。「が」では主語になり、文が成立しない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "書き換えた", "is_correct": true, "explanation": "過去の完了を表し、「開発者は一部を書き換えた」と文意が合う。"}, {"text": "書き換えたら", "is_correct": false, "explanation": "仮定の形で、文末に置くと文が完結しない。"}, {"text": "書き換えたり", "is_correct": false, "explanation": "並列の形で、文が途中で終わり完結しない。"}, {"text": "書き換えず", "is_correct": false, "explanation": "連用の否定形で、文末に置くと文が完結しない。"}], "correct_form": "書き換えた", "base_form": "書き換える", "form_label": "過去形", "sentence_index": 7, "explanations": {"書き換えた": "過去の完了を表し、「開発者は一部を書き換えた」と文意が合う。", "書き換えたら": "仮定の形で、文末に置くと文が完結しない。", "書き換えたり": "並列の形で、文が途中で終わり完結しない。", "書き換えず": "連用の否定形で、文末に置くと文が完結しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbebb45-cebd-47cf-89f4-b90296c7b97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
