INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53547, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "よいことの中でいちばんすばらしいです。", "primary_collocate": null, "pronunciation": "さいこう", "ipa": "saikoː", "syllable_count": 4, "sentences": [{"text": "このラーメンは、とてもおいしくて最高です。", "target_word": "最高", "complexity_tier": "T3", "furigana": "このラーメンは、とてもおいしくて最高[さいこう]です。", "sentence_source": "generated"}, {"text": "天気がよくて、今日は最高の気分です。", "target_word": "最高", "complexity_tier": "T3", "furigana": "天気[てんき]がよくて、今日[きょう]は最高[さいこう]の気分[きぶん]です。", "sentence_source": "generated"}, {"text": "友だちと見た花火は、最高でした。", "target_word": "最高", "complexity_tier": "T3", "furigana": "友[とも]だちと見[み]た花火[はなび]は、最高[さいこう]でした。", "sentence_source": "generated"}, {"text": "温泉に入って、ビールを飲むのは最高です。", "target_word": "最高", "complexity_tier": "T3", "furigana": "温泉[おんせん]に入[はい]って、ビールを飲[の]むのは最高[さいこう]です。", "sentence_source": "generated"}, {"text": "休みの日に寝るのは、私には最高のぜいたくです。", "target_word": "最高", "complexity_tier": "T3", "furigana": "休[やす]みの日[ひ]に寝[ね]るのは、私[わたし]には最高[さいこう]のぜいたくです。", "sentence_source": "generated"}, {"text": "最高の天気なので、公園でお弁当を食べましょう。", "target_word": "最高", "complexity_tier": "T3", "furigana": "最高[さいこう]の天気[てんき]なので、公園[こうえん]でお弁当[べんとう]を食[た]べましょう。", "sentence_source": "generated"}, {"text": "旅行は雨でしたが、食事は最高でした。", "target_word": "最高", "complexity_tier": "T3", "furigana": "旅行[りょこう]は雨[あめ]でしたが、食事[しょくじ]は最高[さいこう]でした。", "sentence_source": "generated"}, {"text": "みんなで歌った夜は、最高の思い出です。", "target_word": "最高", "complexity_tier": "T3", "furigana": "みんなで歌[うた]った夜[よる]は、最高[さいこう]の思[おも]い出[で]です。", "sentence_source": "generated"}, {"text": "このソファはやわらかくて、座ると最高です。", "target_word": "最高", "complexity_tier": "T3", "furigana": "このソファはやわらかくて、座[すわ]ると最高[さいこう]です。", "sentence_source": "generated"}, {"text": "試合に勝った日のご飯は、私にとって最高の味です。", "target_word": "最高", "complexity_tier": "T3", "furigana": "試合[しあい]に勝[か]った日[ひ]のご飯[はん]は、私[わたし]にとって最高[さいこう]の味[あじ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最高", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "気持ちや経験が、これ以上ないほどすばらしいこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): ソファ (Zipf 3.8), やわらかく (Zipf 2.78), 座る (Zipf 3.9)']::text[], '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53547, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最高", "is_correct": true, "explanation": "よいことの中で一番すばらしいという意味。おいしさを最上級で褒める文に合う。"}, {"text": "最悪", "is_correct": false, "explanation": "最も悪い状態という意味。「とてもおいしくて最悪です」は文の内容と矛盾し、空所に入らない。"}, {"text": "平凡", "is_correct": false, "explanation": "ごく普通という意味。「とてもおいしくて平凡です」は褒める文と矛盾して入らない。"}, {"text": "苦手", "is_correct": false, "explanation": "得意でないという意味。「おいしくて苦手です」は文の内容と合わない。"}], "explanations": {"最高": "よいことの中で一番すばらしいという意味。おいしさを最上級で褒める文に合う。", "最悪": "最も悪い状態という意味。「とてもおいしくて最悪です」は文の内容と矛盾し、空所に入らない。", "平凡": "ごく普通という意味。「とてもおいしくて平凡です」は褒める文と矛盾して入らない。", "苦手": "得意でないという意味。「おいしくて苦手です」は文の内容と合わない。"}, "sentence_index": 0, "correct_answer": "最高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この山は、周りの山の中で最高の高さを持っている。", "explanation": "ここは〈程度が一番高い〉の意味（別の義項）。高さの比較で、よい経験をほめる〈すばらしい〉の意味ではない。"}, {"text": "この箱は、今まで運んだ中で重さが最高だった。", "explanation": "ここは〈程度が一番高い〉の意味（別の義項）。重さの比較で、評価の〈すばらしい〉の意味ではない。"}, {"text": "今年の参加者は、去年の最高の人数に達しなかった。", "explanation": "ここは〈程度が一番高い〉の意味（別の義項）。人数の上限を表し、評価の〈すばらしい〉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53547, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最高", "is_correct": true, "explanation": "すぐれているという意味。雨の旅行とは対照的に、食事がすばらしかったという文に合う。"}, {"text": "文房具", "is_correct": false, "explanation": "文房具という意味。食事の評価としては成り立たない。"}, {"text": "改札", "is_correct": false, "explanation": "駅で切符を確かめる場所という意味。食事の評価としては成り立たない。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まるという意味。食事の評価として「停電でした」は意味が通らない。"}], "explanations": {"最高": "すぐれているという意味。雨の旅行とは対照的に、食事がすばらしかったという文に合う。", "文房具": "文房具という意味。食事の評価としては成り立たない。", "改札": "駅で切符を確かめる場所という意味。食事の評価としては成り立たない。", "停電": "電気が止まるという意味。食事の評価として「停電でした」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "最高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会場の収容人数は、今年の最高に達した。", "explanation": "ここは〈程度が一番高い〉の意味（別の義項）。人数の上限を表し、評価の〈すばらしい〉ではない。"}, {"text": "この店の売り上げは、今年の最高を記録した。", "explanation": "ここは〈程度が一番高い〉の意味（別の義項）。数量の上限を表し、評価の〈すばらしい〉ではない。"}, {"text": "この機械は、工場の中で最高の速さで動く。", "explanation": "ここは〈程度が一番高い〉の意味（別の義項）。速さの上限を表し、評価の〈すばらしい〉ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53547, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この山からの眺めは、最高のです。", "corrected_sentence": "この山からの眺めは、最高です。", "error_description": "「最高」は名詞なので「最高です」と続ける。「最高のです」の「の」は余分で、ここでは使えない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53547, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この旅館の夕食は、本当に最高くでした。", "corrected_sentence": "この旅館の夕食は、本当に最高でした。", "error_description": "「最高」は名詞（形容動詞）なので、「く」は付かない。「最高くでした」は誤りで、正しくは「最高でした」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53548, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最低", "is_correct": true, "explanation": "最高の対義語。程度や水準が一番低いことを表し、最高と対になる。"}, {"text": "平均", "is_correct": false, "explanation": "全体の中央の値を表す語で、程度の上下を対比する語ではない。"}, {"text": "中間", "is_correct": false, "explanation": "上と下の間を表す語で、最高と対になる語ではない。"}, {"text": "普通", "is_correct": false, "explanation": "特に優れても劣ってもない状態を表す語で、最高と対になる語ではない。"}], "correct_answer": "最低", "explanations": {"最低": "最高の対義語。程度や水準が一番低いことを表し、最高と対になる。", "平均": "全体の中央の値を表す語で、程度の上下を対比する語ではない。", "中間": "上と下の間を表す語で、最高と対になる語ではない。", "普通": "特に優れても劣ってもない状態を表す語で、最高と対になる語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53548, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最低", "is_correct": true, "explanation": "最高の対義語。程度や水準が一番低いことを表し、最高と対になる。"}, {"text": "平凡", "is_correct": false, "explanation": "特にすぐれた点がないという意味で、程度の上下を対比する語ではない。"}, {"text": "中庸", "is_correct": false, "explanation": "かたよらない真ん中の立場という意味で、最高と対になる語ではない。"}, {"text": "普段", "is_correct": false, "explanation": "いつもの状態という意味で、程度の上下を対比する語ではない。"}], "correct_answer": "最低", "explanations": {"最低": "最高の対義語。程度や水準が一番低いことを表し、最高と対になる。", "平凡": "特にすぐれた点がないという意味で、程度の上下を対比する語ではない。", "中庸": "かたよらない真ん中の立場という意味で、最高と対になる語ではない。", "普段": "いつもの状態という意味で、程度の上下を対比する語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53548, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "程度や水準が他のすべてを上回っていること。また、そのさま。最もすぐれている状態。", "primary_collocate": null, "pronunciation": "さいこう", "ipa": "saikoː", "syllable_count": 4, "sentences": [{"text": "今日の気温は、最高で三十度まで上がるでしょう。", "target_word": "最高", "complexity_tier": "T3", "furigana": "今日[きょう]の気温[きおん]は、最高[さいこう]で三十度[さんじゅうど]まで上[あ]がるでしょう。", "sentence_source": "generated"}, {"text": "この店は、町でも最高の水準の料理を出します。", "target_word": "最高", "complexity_tier": "T3", "furigana": "この店[みせ]は、町[まち]でも最高[さいこう]の水準[すいじゅん]の料理[りょうり]を出[だ]します。", "sentence_source": "generated"}, {"text": "富士山は、日本の山の中で最高の高さです。", "target_word": "最高", "complexity_tier": "T3", "furigana": "富士山[ふじさん]は、日本[にほん]の山[やま]の中[なか]で最高[さいこう]の高[たか]さです。", "sentence_source": "generated"}, {"text": "この部屋は、最高の安全基準を守って作られました。", "target_word": "最高", "complexity_tier": "T3", "furigana": "この部屋[へや]は、最高[さいこう]の安全[あんぜん]基準[きじゅん]を守[まも]って作[つく]られました。", "sentence_source": "generated"}, {"text": "最高の成績を取った人には、賞が出ます。", "target_word": "最高", "complexity_tier": "T3", "furigana": "最高[さいこう]の成績[せいせき]を取[と]った人[ひと]には、賞[しょう]が出[で]ます。", "sentence_source": "generated"}, {"text": "入場料は最高で千円です。それ以上は取りません。", "target_word": "最高", "complexity_tier": "T3", "furigana": "入場料[にゅうじょうりょう]は最高[さいこう]で千円[せんえん]です。それ以上[いじょう]は取[と]りません。", "sentence_source": "generated"}, {"text": "この車は、世界で最高の技術を使っています。", "target_word": "最高", "complexity_tier": "T3", "furigana": "この車[くるま]は、世界[せかい]で最高[さいこう]の技術[ぎじゅつ]を使[つか]っています。", "sentence_source": "generated"}, {"text": "彼のジャンプは、大会で最高の高さでした。", "target_word": "最高", "complexity_tier": "T3", "furigana": "彼[かれ]のジャンプは、大会[たいかい]で最高[さいこう]の高[たか]さでした。", "sentence_source": "generated"}, {"text": "最高の品質を守るため、毎日検査をします。", "target_word": "最高", "complexity_tier": "T3", "furigana": "最高[さいこう]の品質[ひんしつ]を守[まも]るため、毎日[まいにち]検査[けんさ]をします。", "sentence_source": "generated"}, {"text": "この会議で最高の決定権を持つのは社長です。", "target_word": "最高", "complexity_tier": "T3", "furigana": "この会議[かいぎ]で最高[さいこう]の決定権[けっていけん]を持[も]つのは社長[しゃちょう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "最高", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "程度や水準が他のどれよりも上であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53548, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最高", "is_correct": true, "explanation": "程度が一番高いという意味。「最高で三十度まで上がる」は気温の上限を表し、文に合う。"}, {"text": "最寄り", "is_correct": false, "explanation": "一番近いという意味。「最寄りで三十度」では気温の話として意味が通らない。"}, {"text": "最初", "is_correct": false, "explanation": "はじめという意味。「最初で三十度まで」では上限を表せず、文が成り立たない。"}, {"text": "同時", "is_correct": false, "explanation": "同じときという意味。「同時で三十度まで」は気温の表現として通らない。"}], "explanations": {"最高": "程度が一番高いという意味。「最高で三十度まで上がる」は気温の上限を表し、文に合う。", "最寄り": "一番近いという意味。「最寄りで三十度」では気温の話として意味が通らない。", "最初": "はじめという意味。「最初で三十度まで」では上限を表せず、文が成り立たない。", "同時": "同じときという意味。「同時で三十度まで」は気温の表現として通らない。"}, "sentence_index": 0, "correct_answer": "最高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この旅行は、家族にとって最高だった。", "explanation": "ここは〈すばらしい〉の意味（別の義項）。評価の表現で、程度の上限を表すのではない。"}, {"text": "今日の天気は、ピクニックにとって最高だった。", "explanation": "ここは〈すばらしい〉の意味（別の義項）。評価の表現で、程度の上限を表すのではない。"}, {"text": "この映画は、私にとって最高だと思う。", "explanation": "ここは〈すばらしい〉の意味（別の義項）。評価の表現で、程度の上限を表すのではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53548, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最高", "is_correct": true, "explanation": "すぐれているという意味。世界で一番すぐれた技術を使っている、という文に合う。"}, {"text": "文房具", "is_correct": false, "explanation": "文房具という意味。「世界で文房具の技術」では文の意味が通らない。"}, {"text": "中断", "is_correct": false, "explanation": "途中でやめるという意味。技術を修飾する語としては成り立たない。"}, {"text": "夜間", "is_correct": false, "explanation": "夜の時間帯という意味。「世界で夜間の技術」は意味が通らない。"}], "explanations": {"最高": "すぐれているという意味。世界で一番すぐれた技術を使っている、という文に合う。", "文房具": "文房具という意味。「世界で文房具の技術」では文の意味が通らない。", "中断": "途中でやめるという意味。技術を修飾する語としては成り立たない。", "夜間": "夜の時間帯という意味。「世界で夜間の技術」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "最高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この旅館の露天風呂は、疲れを取るのに最高だった。", "explanation": "ここは〈すばらしい〉の意味（別の義項）。評価の表現で、程度の上限を表すのではない。"}, {"text": "このゲームは、子どもたちにとって最高だった。", "explanation": "ここは〈すばらしい〉の意味（別の義項）。評価の表現で、程度の上限を表すのではない。"}, {"text": "この料理は、家族みんなにとって最高だった。", "explanation": "ここは〈すばらしい〉の意味（別の義項）。評価の表現で、程度の上限を表すのではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53548, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今日の気温は、最高が二十五度まで上がるでしょう。", "corrected_sentence": "今日の気温は、最高で二十五度まで上がるでしょう。", "error_description": "「最高」の後に続く助詞は「で」。「最高が」では「最高」が主語になってしまい、上限を表す「最高で」の形にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53548, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この工場は、世界で最高へ技術を使っています。", "corrected_sentence": "この工場は、世界で最高の技術を使っています。", "error_description": "「最高」に続く助詞は「の」。「最高へ」では方向を表す助詞になり、「最高の技術」のように名詞を修飾する形にならない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
