INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53552, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "七日間続く期間のことです", "primary_collocate": null, "pronunciation": "うぃーく", "ipa": "wiːkɯ", "syllable_count": 3, "sentences": [{"text": "店は、七日間続くウィークに合わせて特別なセールを始めた。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "店[みせ]は、七日間[なのかかん]続[つづ]くウィークに合[あ]わせて特別[とくべつ]なセールを始[はじ]めた。", "sentence_source": "generated"}, {"text": "「ウィーク」は英語で、七日間続く期間を表す言葉です。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "「ウィーク」は英語[えいご]で、七日間[なのかかん]続[つづ]く期間[きかん]を表[あらわ]す言葉[ことば]です。", "sentence_source": "generated"}, {"text": "英語の「ウィーク」とは、七日間続く期間のことです。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "英語[えいご]の「ウィーク」とは、七日間[なのかかん]続[つづ]く期間[きかん]のことです。", "sentence_source": "generated"}, {"text": "「ウィーク」と言えば、七日間続く期間を指すのが普通です。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "「ウィーク」と言[い]えば、七日間[なのかかん]続[つづ]く期間[きかん]を指[さ]すのが普通[ふつう]です。", "sentence_source": "generated"}, {"text": "辞書によると、「ウィーク」は七日間続く期間という意味です。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "辞書[じしょ]によると、「ウィーク」は七日間[なのかかん]続[つづ]く期間[きかん]という意味[いみ]です。", "sentence_source": "generated"}, {"text": "「ウィーク」の意味を調べたら、七日間続く期間のことだった。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "「ウィーク」の意味[いみ]を調[しら]べたら、七日間[なのかかん]続[つづ]く期間[きかん]のことだった。", "sentence_source": "generated"}, {"text": "「ウィーク」という外来語は、七日間続く期間を指す。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "「ウィーク」という外来語[がいらいご]は、七日間[なのかかん]続[つづ]く期間[きかん]を指[さ]す。", "sentence_source": "generated"}, {"text": "外来語の「ウィーク」は、七日間続く期間を意味している。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "外来語[がいらいご]の「ウィーク」は、七日間[なのかかん]続[つづ]く期間[きかん]を意味[いみ]している。", "sentence_source": "generated"}, {"text": "「ウィーク」は、七日間続く期間をまとめて呼ぶときに使う言葉だ。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "「ウィーク」は、七日間[なのかかん]続[つづ]く期間[きかん]をまとめて呼[よ]ぶときに使[つか]う言葉[ことば]だ。", "sentence_source": "generated"}, {"text": "「ウィーク」は七日間続く期間を表す、外来語のひとつだ。", "target_word": "ウィーク", "complexity_tier": "T3", "furigana": "「ウィーク」は七日間[なのかかん]続[つづ]く期間[きかん]を表[あらわ]す、外来語[がいらいご]のひとつだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ウィーク", "label": "基本形"}], "register": "一般", "sense_fingerprint": "行事やセールなどのために設けられた、七日間続く特別な期間。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53552, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ウィーク", "is_correct": true, "explanation": "〈七日間続く期間〉を表す語で、セールに合わせた期間の文脈に合う。"}, {"text": "テーブル", "is_correct": false, "explanation": "〈テーブル〉は食卓や机の意味で、行事の期間を指せないためこの空欄には入らない。"}, {"text": "ガーデン", "is_correct": false, "explanation": "〈ガーデン〉は庭園の意味で、期間を表すこの文脈には合わない。"}, {"text": "ブルー", "is_correct": false, "explanation": "〈ブルー〉は色の意味で、行事の期間を示す語として文に収まらない。"}], "explanations": {"ウィーク": "〈七日間続く期間〉を表す語で、セールに合わせた期間の文脈に合う。", "テーブル": "〈テーブル〉は食卓や机の意味で、行事の期間を指せないためこの空欄には入らない。", "ガーデン": "〈ガーデン〉は庭園の意味で、期間を表すこの文脈には合わない。", "ブルー": "〈ブルー〉は色の意味で、行事の期間を示す語として文に収まらない。"}, "sentence_index": 0, "correct_answer": "ウィーク"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ウィークは、毎年の会計を区切る一年の期間だ。", "explanation": "ここは〈会計年度〉の意味を混同している。〈ウィーク〉は七日間の期間で、一年を区切る会計年度を指すものではないので合わない。"}, {"text": "ウィークは、毎週日曜日に開く市場のことだ。", "explanation": "ここは〈市〉（定期的に開かれる市場）の意味を混同している。〈ウィーク〉は七日間の期間で、市場が開かれる場所や日を指す語ではないので合わない。"}, {"text": "提出のウィークは、来週の金曜日だ。", "explanation": "ここは〈期限〉の意味を混同している。〈ウィーク〉は期間そのものを指し、締め切りの日を表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53552, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ウィーク", "is_correct": true, "explanation": "〈七日間続く期間を指す外来語〉で、文の内容と一致する。"}, {"text": "マンスリー", "is_correct": false, "explanation": "〈マンスリー〉は一か月の意味で、七日間の期間を指す語ではない。"}, {"text": "デイリー", "is_correct": false, "explanation": "〈デイリー〉は毎日の意味で、七日間続く期間とは合わない。"}, {"text": "ロングラン", "is_correct": false, "explanation": "〈ロングラン〉は長期間の上演や公開を指し、七日間と限定する語ではない。"}], "explanations": {"ウィーク": "〈七日間続く期間を指す外来語〉で、文の内容と一致する。", "マンスリー": "〈マンスリー〉は一か月の意味で、七日間の期間を指す語ではない。", "デイリー": "〈デイリー〉は毎日の意味で、七日間続く期間とは合わない。", "ロングラン": "〈ロングラン〉は長期間の上演や公開を指し、七日間と限定する語ではない。"}, "sentence_index": 6, "correct_answer": "ウィーク"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ウィークは、毎年の大晦日に行う大掃除のことだ。", "explanation": "ここは〈年末〉の意味を混同している。〈ウィーク〉は七日間の期間で、大晦日に行う大掃除を指す語ではないので合わない。"}, {"text": "ウィークは、会社員が朝早く出勤する日だ。", "explanation": "ここは〈平日〉の意味を混同している。〈ウィーク〉は七日間の期間で、出勤する一日を指す語ではないので合わない。"}, {"text": "ウィークは二十四時間だ。", "explanation": "ここは〈一日〉の意味を混同している。〈ウィーク〉は七日間の期間で、二十四時間を表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53552, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "七日間続くウィークを、新作が次々と発表された。", "corrected_sentence": "七日間続くウィークに、新作が次々と発表された。", "error_description": "誤りは〈を〉。期間を示すのは〈に〉が正しい。〈を〉は目的語に付く助詞で、受身の〈発表された〉と合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53552, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年のウィークを、会場は一般公開される。", "corrected_sentence": "来年のウィークに、会場は一般公開される。", "error_description": "誤りは〈を〉。時期を示すのは〈に〉が正しい。〈を〉は目的語に付く助詞で、受身の〈一般公開される〉と合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53553, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈追い求める〉の目的語を示すので〈を〉が正しい。〈アヴァンギャルド〉は追い求める対象になる。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すが、〈追い求めた〉の主語は〈彼〉なので、ここでは目的語を示す助詞が必要。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は相手や方向を示し、〈追い求める〉の目的語には付かないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "〈で〉は手段や場所を示し、〈追い求める〉の目的語を表せないので合わない。"}], "correct_answer": "を", "explanations": {"を": "〈追い求める〉の目的語を示すので〈を〉が正しい。〈アヴァンギャルド〉は追い求める対象になる。", "が": "〈が〉は主語を示すが、〈追い求めた〉の主語は〈彼〉なので、ここでは目的語を示す助詞が必要。", "に": "〈に〉は相手や方向を示し、〈追い求める〉の目的語には付かないので合わない。", "で": "〈で〉は手段や場所を示し、〈追い求める〉の目的語を表せないので合わない。"}, "error_tags": {"が": "主語", "に": "方向・相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53553, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈テーマにした〉の対象を示すので〈を〉が正しい。〈アヴァンギャルド〉が展覧会のテーマになっている。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は方向や到達を示し、〈テーマにした〉の対象は表せないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示すので、対象を取る〈テーマにした〉には合わない。"}, {"text": "より", "is_correct": false, "explanation": "〈より〉は比較を示すので、〈テーマにした〉の対象とは結びつかず文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "〈テーマにした〉の対象を示すので〈を〉が正しい。〈アヴァンギャルド〉が展覧会のテーマになっている。", "へ": "〈へ〉は方向や到達を示し、〈テーマにした〉の対象は表せないので合わない。", "から": "〈から〉は起点を示すので、対象を取る〈テーマにした〉には合わない。", "より": "〈より〉は比較を示すので、〈テーマにした〉の対象とは結びつかず文が成り立たない。"}, "error_tags": {"へ": "方向・到達", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53553, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "世の中よりも先に新しい考えや形を作ることです。みんながまだ見たことのない面白いデザインに使います。", "primary_collocate": null, "pronunciation": "あゔぁんぎゃるど", "ipa": "avaŋɡʲarɯdo", "syllable_count": 6, "sentences": [{"text": "二十世紀初頭、パリではアヴァンギャルドと呼ばれる芸術運動が盛んになった。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "二十世紀[にじっせいき]初頭[しょとう]、パリではアヴァンギャルドと呼[よ]ばれる芸術[げいじゅつ]運動[うんどう]が盛[さか]んになった。", "sentence_source": "generated"}, {"text": "彼は生涯、映画のアヴァンギャルドを追い求めた。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "彼[かれ]は生涯[しょうがい]、映画[えいが]のアヴァンギャルドを追[お]い求[もと]めた。", "sentence_source": "generated"}, {"text": "この雑誌は、デザインのアヴァンギャルドを紹介する特集を組んだ。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "この雑誌[ざっし]は、デザインのアヴァンギャルドを紹介[しょうかい]する特集[とくしゅう]を組[く]んだ。", "sentence_source": "generated"}, {"text": "ロシアのアヴァンギャルドの画家たちは、新しい色と形を探していた。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "ロシアのアヴァンギャルドの画家[がか]たちは、新[あたら]しい色[いろ]と形[かたち]を探[さが]していた。", "sentence_source": "generated"}, {"text": "アヴァンギャルドは、最初は理解されなくても、後に常識になることが多い。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "アヴァンギャルドは、最初[さいしょ]は理解[りかい]されなくても、後[のち]に常識[じょうしき]になることが多[おお]い。", "sentence_source": "generated"}, {"text": "若いデザイナーたちが、アヴァンギャルドの精神で古い型を破ろうとしている。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "若[わか]いデザイナーたちが、アヴァンギャルドの精神[せいしん]で古[ふる]い型[かた]を破[やぶ]ろうとしている。", "sentence_source": "generated"}, {"text": "アヴァンギャルドを名乗るなら、誰もやっていない表現に挑戦すべきだ。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "アヴァンギャルドを名乗[なの]るなら、誰[だれ]もやっていない表現[ひょうげん]に挑戦[ちょうせん]すべきだ。", "sentence_source": "generated"}, {"text": "博物館では、日本のアヴァンギャルドをテーマにした展覧会が開かれている。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、日本[にほん]のアヴァンギャルドをテーマにした展覧会[てんらんかい]が開[ひら]かれている。", "sentence_source": "generated"}, {"text": "批評家は彼の作品を、現代アヴァンギャルドの代表作と評した。", "target_word": "アヴァンギャルド", "complexity_tier": "T4", "furigana": "批評家[ひひょうか]は彼[かれ]の作品[さくひん]を、現代[げんだい]アヴァンギャルドの代表作[だいひょうさく]と評[ひょう]した。", "sentence_source": "generated"}, {"text": "アヴァンギャルドの時代の詩人は、言葉の並べ方さえ変えようとした。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "アヴァンギャルドの時代[じだい]の詩人[しじん]は、言葉[ことば]の並[なら]べ方[かた]さえ変[か]えようとした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アヴァンギャルド", "label": "基本形"}], "register": "一般", "sense_fingerprint": "芸術運動や精神としての前衛。世に先がけて新しい考えや形を生み出すこと。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53553, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アヴァンギャルド", "is_correct": true, "explanation": "〈世に先がけて新しい考えや形を生む芸術運動〉を指し、パリの芸術運動という文脈に合う。"}, {"text": "カフェ", "is_correct": false, "explanation": "〈カフェ〉は喫茶店の意味で、芸術運動を表す語としては文に入らない。"}, {"text": "マーケット", "is_correct": false, "explanation": "〈マーケット〉は市場の意味で、芸術運動の名称としては合わない。"}, {"text": "カレー", "is_correct": false, "explanation": "〈カレー〉は料理の意味で、芸術運動の名称としては文に入らない。"}], "explanations": {"アヴァンギャルド": "〈世に先がけて新しい考えや形を生む芸術運動〉を指し、パリの芸術運動という文脈に合う。", "カフェ": "〈カフェ〉は喫茶店の意味で、芸術運動を表す語としては文に入らない。", "マーケット": "〈マーケット〉は市場の意味で、芸術運動の名称としては合わない。", "カレー": "〈カレー〉は料理の意味で、芸術運動の名称としては文に入らない。"}, "sentence_index": 0, "correct_answer": "アヴァンギャルド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼はアヴァンギャルドの立場から、昔ながらの制度を守ると主張した。", "explanation": "ここは〈保守〉の意味を混同している。〈アヴァンギャルド〉は世の中より先に新しい考えや形を作ることで、古い制度を守る立場を表す語ではないので合わない。"}, {"text": "社会のアヴァンギャルドを守ることは、大切な責任だ。", "explanation": "ここは〈規範〉の意味を混同している。〈アヴァンギャルド〉は新しい考えを先に生み出す運動や精神で、守るべき決まりを指す語ではないので合わない。"}, {"text": "来年のアヴァンギャルドは、英語で話せるようになることだ。", "explanation": "ここは〈目標〉の意味を混同している。〈アヴァンギャルド〉は新しい考えや形を先に作る運動や精神で、将来の目標を表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53553, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アヴァンギャルド", "is_correct": true, "explanation": "〈世に先がけて新しい考えや形を生む運動や精神〉を指し、〈名乗る〉と〈挑戦すべき〉の文脈に合う。"}, {"text": "マニュアル", "is_correct": false, "explanation": "〈マニュアル〉は手順書の意味で、挑戦する精神を表す語としては文脈に合わない。"}, {"text": "ユニフォーム", "is_correct": false, "explanation": "〈ユニフォーム〉は制服の意味で、挑戦する精神を表す語としては文脈に合わない。"}, {"text": "ルーティン", "is_correct": false, "explanation": "〈ルーティン〉は決まった作業の流れを指し、挑戦する精神とは合わない。"}], "explanations": {"アヴァンギャルド": "〈世に先がけて新しい考えや形を生む運動や精神〉を指し、〈名乗る〉と〈挑戦すべき〉の文脈に合う。", "マニュアル": "〈マニュアル〉は手順書の意味で、挑戦する精神を表す語としては文脈に合わない。", "ユニフォーム": "〈ユニフォーム〉は制服の意味で、挑戦する精神を表す語としては文脈に合わない。", "ルーティン": "〈ルーティン〉は決まった作業の流れを指し、挑戦する精神とは合わない。"}, "sentence_index": 6, "correct_answer": "アヴァンギャルド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作品は、何百年も読み継がれてきたアヴァンギャルドだ。", "explanation": "ここは〈古典〉の意味を混同している。〈アヴァンギャルド〉は新しい考えを先に生み出す運動や精神で、長く読み継がれた古い作品を指す語ではないので合わない。"}, {"text": "この地方には、古くからのアヴァンギャルドが残っている。", "explanation": "ここは〈慣習〉の意味を混同している。〈アヴァンギャルド〉は世の中より先に新しい形を作ることで、古くから残る慣習を指す語ではないので合わない。"}, {"text": "アヴァンギャルドでは、借金は早く返すべきだと考えられている。", "explanation": "ここは〈常識〉の意味を混同している。〈アヴァンギャルド〉は常識にとらわれず新しい考えを先に作る精神で、常識どおりの判断を表す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53553, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "若い画家たちは、アヴァンギャルドくて精神で、新しい色と形を探している。", "corrected_sentence": "若い画家たちは、アヴァンギャルドの精神で、新しい色と形を探している。", "error_description": "誤りは〈くて〉。アヴァンギャルドを名詞〈精神〉の前で使うときは〈の〉（名詞修飾）が正しい。〈くて〉は形容詞の活用で、この語には付かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53553, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "美術館では、現代のアヴァンギャルドを作品が並んでいる。", "corrected_sentence": "美術館では、現代のアヴァンギャルドの作品が並んでいる。", "error_description": "誤りは〈を〉。名詞を修飾するのは〈の〉が正しい。〈を〉は目的語に付くが、〈並んでいる〉は自動詞なので文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53554, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53554, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53554, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "芸術やファッションなどで、従来の常識にとらわれず、革新的で実験的な手法や作品のこと。また、そのような性質を持つさま。", "primary_collocate": null, "pronunciation": "あゔぁんぎゃるど", "ipa": "avaŋɡʲarɯdo", "syllable_count": 6, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "アヴァンギャルド", "complexity_tier": "T4", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材[そざい]使[づか]いは、一般[いっぱん]消費者[しょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "彼女のアヴァンギャルドな衣装は、普通の服に慣れた観客を驚かせた。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "彼女[かのじょ]のアヴァンギャルドな衣装[いしょう]は、普通[ふつう]の服[ふく]に慣[な]れた観客[かんきゃく]を驚[おどろ]かせた。", "sentence_source": "generated"}, {"text": "この劇団はアヴァンギャルドな演出で知られ、台本どおりに進まない舞台が多い。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "この劇団[げきだん]はアヴァンギャルドな演出[えんしゅつ]で知[し]られ、台本[だいほん]どおりに進[すす]まない舞台[ぶたい]が多[おお]い。", "sentence_source": "generated"}, {"text": "あの画家の絵はあまりにアヴァンギャルドで、最初は誰も理解できなかった。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "あの画家[がか]の絵[え]はあまりにアヴァンギャルドで、最初[さいしょ]は誰[だれ]も理解[りかい]できなかった。", "sentence_source": "generated"}, {"text": "伝統的な着物を、アヴァンギャルドに作り変えたデザイナーがいる。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "伝統的[でんとうてき]な着物[きもの]を、アヴァンギャルドに作[つく]り変[か]えたデザイナーがいる。", "sentence_source": "generated"}, {"text": "アヴァンギャルドな音楽は、聞き慣れた旋律を壊すところが面白い。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "アヴァンギャルドな音楽[おんがく]は、聞[き]き慣[な]れた旋律[せんりつ]を壊[こわ]すところが面白[おもしろ]い。", "sentence_source": "generated"}, {"text": "建築家は、常識にとらわれないアヴァンギャルドな外観の美術館を設計した。", "target_word": "アヴァンギャルド", "complexity_tier": "T4", "furigana": "建築家[けんちくか]は、常識[じょうしき]にとらわれないアヴァンギャルドな外観[がいかん]の美術館[びじゅつかん]を設計[せっけい]した。", "sentence_source": "generated"}, {"text": "彼の髪型はアヴァンギャルドすぎて、会社では浮いてしまった。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "彼[かれ]の髪型[かみがた]はアヴァンギャルドすぎて、会社[かいしゃ]では浮[う]いてしまった。", "sentence_source": "generated"}, {"text": "保守的な審査員には、このアヴァンギャルドな映画は受け入れがたかった。", "target_word": "アヴァンギャルド", "complexity_tier": "T4", "furigana": "保守的[ほしゅてき]な審査員[しんさいん]には、このアヴァンギャルドな映画[えいが]は受[う]け入[い]れがたかった。", "sentence_source": "generated"}, {"text": "展覧会ではアヴァンギャルドな作品が並び、来場者は首をかしげながら見ていた。", "target_word": "アヴァンギャルド", "complexity_tier": "T3", "furigana": "展覧会[てんらんかい]ではアヴァンギャルドな作品[さくひん]が並[なら]び、来場者[らいじょうしゃ]は首[くび]をかしげながら見[み]ていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "アヴァンギャルドだ", "label": "終止形"}, {"form": "アヴァンギャルドな", "label": "連体形"}, {"form": "アヴァンギャルドに", "label": "連用形"}, {"form": "アヴァンギャルドで", "label": "連用形（て形）"}], "register": "一般", "sense_fingerprint": "常識を破る革新的で実験的な、衣装・演出・作品などの性質やさま。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54842205-00cb-4fdc-9186-59c75684bbbd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53554, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "アヴァンギャルド", "is_correct": true, "explanation": "〈常識にとらわれず革新的〉という意味で、前後の〈拒絶〉と〈強烈な渇望〉の文脈に合う。"}, {"text": "平凡", "is_correct": false, "explanation": "〈平凡〉は目立たない普通さを表し、常識を拒絶して強烈な渇望を生む造形とは意味が逆になる。"}, {"text": "素朴", "is_correct": false, "explanation": "〈素朴〉は飾らない自然さを表し、革新的な造形を説明する語としては文脈に合わない。"}, {"text": "穏当", "is_correct": false, "explanation": "〈穏当〉は穏やかで無難な様子を表し、一般消費者を驚かせる強い造形の説明に合わない。"}], "explanations": {"アヴァンギャルド": "〈常識にとらわれず革新的〉という意味で、前後の〈拒絶〉と〈強烈な渇望〉の文脈に合う。", "平凡": "〈平凡〉は目立たない普通さを表し、常識を拒絶して強烈な渇望を生む造形とは意味が逆になる。", "素朴": "〈素朴〉は飾らない自然さを表し、革新的な造形を説明する語としては文脈に合わない。", "穏当": "〈穏当〉は穏やかで無難な様子を表し、一般消費者を驚かせる強い造形の説明に合わない。"}, "sentence_index": 0, "correct_answer": "アヴァンギャルド"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の服は、常識どおりのアヴァンギャルドな色合いで、街ではまったく目立たない。", "explanation": "ここは〈地味・保守的〉の意味を混同している。〈アヴァンギャルド〉は常識にとらわれない革新性を指すので、常識どおりで目立たない様子には合わない。"}, {"text": "この店は、アヴァンギャルドな定番の味を、昔から変えずに守っている。", "explanation": "ここは〈定番〉の意味を混同している。〈定番〉は昔からの決まった型を指し、常識を破る革新性とは反対なので合わない。"}, {"text": "この曲は、誰もが知る主流のアヴァンギャルドな流行歌だ。", "explanation": "ここは〈主流・流行〉の意味を混同している。〈アヴァンギャルド〉は常識を破る少数派の革新性を指すので、誰もが知る主流の流行歌には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53554, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "アヴァンギャルド", "is_correct": true, "explanation": "〈常識にとらわれず革新的〉の意味で、建築家が美術館の外観を設計した文脈に合う。"}, {"text": "退屈", "is_correct": false, "explanation": "〈退屈〉は面白みがない様子で、常識にとらわれない外観の説明としては合わない。"}, {"text": "凡庸", "is_correct": false, "explanation": "〈凡庸〉は平凡で優れた点がない意味で、革新的な外観を表す語としては文脈に合わない。"}, {"text": "無難", "is_correct": false, "explanation": "〈無難〉は当たり障りのない様子で、常識にとらわれない設計という文脈と合わない。"}], "explanations": {"アヴァンギャルド": "〈常識にとらわれず革新的〉の意味で、建築家が美術館の外観を設計した文脈に合う。", "退屈": "〈退屈〉は面白みがない様子で、常識にとらわれない外観の説明としては合わない。", "凡庸": "〈凡庸〉は平凡で優れた点がない意味で、革新的な外観を表す語としては文脈に合わない。", "無難": "〈無難〉は当たり障りのない様子で、常識にとらわれない設計という文脈と合わない。"}, "sentence_index": 6, "correct_answer": "アヴァンギャルド"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の文章は、誰にでも書ける平凡なアヴァンギャルドさで、読んでも印象に残らない。", "explanation": "ここは〈平凡・ありふれた〉の意味を混同している。〈アヴァンギャルド〉は常識を破る独自の革新性を指すので、ありふれた文章の様子には合わない。"}, {"text": "この学校では、アヴァンギャルドな決まりごとを、何十年も変えずに守ってきた。", "explanation": "ここは〈慣例〉の意味を混同している。〈アヴァンギャルド〉は常識を破る革新性を指すので、昔から変えずに守られてきた決まりには合わない。"}, {"text": "この喫茶店は、古風なアヴァンギャルドの内装で、昭和の雰囲気を残している。", "explanation": "ここは〈古風〉の意味を混同している。〈アヴァンギャルド〉は常識を破る新しさを指すので、昭和風の古い雰囲気を表す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53554, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼女の衣装は、アヴァンギャルドくて、人目を引いた。", "corrected_sentence": "彼女の衣装は、アヴァンギャルドで、人目を引いた。", "error_description": "誤りは〈くて〉。アヴァンギャルドは形容動詞なので、活用は〈で〉が正しい。〈くて〉は形容詞の活用であり、この語には付かない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "アヴァンギャルドな", "is_correct": true, "explanation": "後ろの名詞「衣装」を修飾する連体形なので正しい。"}, {"text": "アヴァンギャルドだ", "is_correct": false, "explanation": "終止形で、名詞「衣装」の前には置けず修飾できない。"}, {"text": "アヴァンギャルドに", "is_correct": false, "explanation": "連用形で、「衣装」を修飾する形にはならない。"}, {"text": "アヴァンギャルドで", "is_correct": false, "explanation": "連用形（て形）で、名詞「衣装」に直接続く形ではない。"}], "correct_form": "アヴァンギャルドな", "base_form": "アヴァンギャルド", "form_label": "形容動詞・連体形", "sentence_index": 1, "explanations": {"アヴァンギャルドな": "後ろの名詞「衣装」を修飾する連体形なので正しい。", "アヴァンギャルドだ": "終止形で、名詞「衣装」の前には置けず修飾できない。", "アヴァンギャルドに": "連用形で、「衣装」を修飾する形にはならない。", "アヴァンギャルドで": "連用形（て形）で、名詞「衣装」に直接続く形ではない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53554, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の髪型はアヴァンギャルドの、同僚は驚いた。", "corrected_sentence": "彼の髪型はアヴァンギャルドで、同僚は驚いた。", "error_description": "誤りは〈の〉。形容動詞の連用形〈で〉が正しい。〈の〉は名詞に付く助詞なので、〈同僚は驚いた〉と続く文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "アヴァンギャルド", "is_correct": true, "explanation": "「すぎ」の前に来る語幹の形で、「アヴァンギャルドすぎて」は〈度を超えて革新的〉を表すので正しい。"}, {"text": "アヴァンギャルドだった", "is_correct": false, "explanation": "過去の終止形で、「すぎ」の前には置けず、文が成り立たないので誤り。"}, {"text": "アヴァンギャルドであり", "is_correct": false, "explanation": "「である」の連用中止形で、「すぎ」に続けると文の骨格が崩れるので誤り。"}, {"text": "アヴァンギャルドだろう", "is_correct": false, "explanation": "推量の終止形で、「すぎ」の前に置くと文が成り立たないので誤り。"}], "correct_form": "アヴァンギャルド", "base_form": "アヴァンギャルド", "form_label": "語幹（「すぎ」の前）", "sentence_index": 7, "explanations": {"アヴァンギャルド": "「すぎ」の前に来る語幹の形で、「アヴァンギャルドすぎて」は〈度を超えて革新的〉を表すので正しい。", "アヴァンギャルドだった": "過去の終止形で、「すぎ」の前には置けず、文が成り立たないので誤り。", "アヴァンギャルドであり": "「である」の連用中止形で、「すぎ」に続けると文の骨格が崩れるので誤り。", "アヴァンギャルドだろう": "推量の終止形で、「すぎ」の前に置くと文が成り立たないので誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff086190-8d31-4d2f-9145-ce4bea701137') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53555, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「箸の使いが丁寧」と主語を示し、文が成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「使いを丁寧」は形容詞「丁寧」に目的語が続かず不自然。"}, {"text": "に", "is_correct": false, "explanation": "「使いに丁寧」は位置や相手を示す形で、この文の構造に合わない。"}, {"text": "で", "is_correct": false, "explanation": "「使いで丁寧」は手段の形で、主語と述語の関係が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「箸の使いが丁寧」と主語を示し、文が成り立つ。", "を": "「使いを丁寧」は形容詞「丁寧」に目的語が続かず不自然。", "に": "「使いに丁寧」は位置や相手を示す形で、この文の構造に合わない。", "で": "「使いで丁寧」は手段の形で、主語と述語の関係が成り立たない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53555, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「コンロの使いを教わって」と目的語を示し、文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「使いが教わって」は主語になり、教わる対象として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「使いで教わって」は手段の形で、教わる内容を示せない。"}, {"text": "へ", "is_correct": false, "explanation": "「使いへ教わって」は方向を示す形で、この文に合わない。"}], "correct_answer": "を", "explanations": {"を": "「コンロの使いを教わって」と目的語を示し、文が成り立つ。", "が": "「使いが教わって」は主語になり、教わる対象として成り立たない。", "で": "「使いで教わって」は手段の形で、教わる内容を示せない。", "へ": "「使いへ教わって」は方向を示す形で、この文に合わない。"}, "error_tags": {"が": "主語", "で": "手段", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53555, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものをどうやって使うかという意味です。", "primary_collocate": null, "pronunciation": "つかい", "ipa": "tsɯkai", "syllable_count": 3, "sentences": [{"text": "包丁の使いが上手な人は、野菜を早く切れます。", "target_word": "使い", "complexity_tier": "T3", "furigana": "包丁[ほうちょう]の使[つか]いが上手[じょうず]な人[ひと]は、野菜[やさい]を早[はや]く切[き]れます。", "sentence_source": "generated"}, {"text": "箸の使いが丁寧なので、食事の姿がきれいです。", "target_word": "使い", "complexity_tier": "T3", "furigana": "箸[はし]の使[つか]いが丁寧[ていねい]なので、食事[しょくじ]の姿[すがた]がきれいです。", "sentence_source": "generated"}, {"text": "道具の使いを間違えると、けがをします。", "target_word": "使い", "complexity_tier": "T3", "furigana": "道具[どうぐ]の使[つか]いを間違[まちが]えると、けがをします。", "sentence_source": "generated"}, {"text": "ナイフの使いに慣れるまで、時間がかかります。", "target_word": "使い", "complexity_tier": "T3", "furigana": "ナイフの使[つか]いに慣[な]れるまで、時間[じかん]がかかります。", "sentence_source": "generated"}, {"text": "この機械は、使いを覚えれば誰でも動かせます。", "target_word": "使い", "complexity_tier": "T3", "furigana": "この機械[きかい]は、使[つか]いを覚[おぼ]えれば誰[だれ]でも動[うご]かせます。", "sentence_source": "generated"}, {"text": "はさみの使いが荒いと、すぐに壊れます。", "target_word": "使い", "complexity_tier": "T3", "furigana": "はさみの使[つか]いが荒[あら]いと、すぐに壊[こわ]れます。", "sentence_source": "generated"}, {"text": "先生は、筆の使いを一つずつ手本で示してくれました。", "target_word": "使い", "complexity_tier": "T3", "furigana": "先生[せんせい]は、筆[ふで]の使[つか]いを一[ひと]つずつ手本[てほん]で示[しめ]してくれました。", "sentence_source": "generated"}, {"text": "コンロの使いを教わって、初めての料理を安全に作れました。", "target_word": "使い", "complexity_tier": "T3", "furigana": "コンロの使[つか]いを教[おそ]わって、初[はじ]めての料理[りょうり]を安全[あんぜん]に作[つく]れました。", "sentence_source": "generated"}, {"text": "工具の使いが上手な父は、棚を手早く直します。", "target_word": "使い", "complexity_tier": "T3", "furigana": "工具[こうぐ]の使[つか]いが上手[じょうず]な父[ちち]は、棚[たな]を手早[てばや]く直[なお]します。", "sentence_source": "generated"}, {"text": "火の使いを教わってから、安全にキャンプができます。", "target_word": "使い", "complexity_tier": "T3", "furigana": "火[ひ]の使[つか]いを教[おそ]わってから、安全[あんぜん]にキャンプができます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使い", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "道具やお金などをどう使うかという使い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53555, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使い", "is_correct": true, "explanation": "「包丁の使い」は扱い方の意味で、「上手な人」と自然につながる。"}, {"text": "重さ", "is_correct": false, "explanation": "「包丁の重さが上手」は続かず、扱い方の話にならない。"}, {"text": "値段", "is_correct": false, "explanation": "「包丁の値段が上手」は意味が通らない。"}, {"text": "刃", "is_correct": false, "explanation": "「包丁の刃が上手」は続かず、扱いの上手さを表せない。"}], "explanations": {"使い": "「包丁の使い」は扱い方の意味で、「上手な人」と自然につながる。", "重さ": "「包丁の重さが上手」は続かず、扱い方の話にならない。", "値段": "「包丁の値段が上手」は意味が通らない。", "刃": "「包丁の刃が上手」は続かず、扱いの上手さを表せない。"}, "sentence_index": 0, "correct_answer": "使い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母に使いを頼まれて、牛乳を買いに行きました。", "explanation": "ここは〈お使い（用事を頼まれて行くこと）〉の意味。ものの使い方の意味では合わない。"}, {"text": "王様の使いが、遠くの村から手紙を持って来ました。", "explanation": "ここは〈使者〉の意味。道具の使い方とは合わない。"}, {"text": "この機械は使いが高く、大量の材料も速く処理できます。", "explanation": "ここは〈性能（機械の働きの良さ）〉の意味。使い方には高い・低いの評価がないので、性能の話には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53555, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使い", "is_correct": true, "explanation": "「筆の使いを教える」は使い方を教える意味で成り立つ。"}, {"text": "汚れ", "is_correct": false, "explanation": "「筆の汚れを教える」は意味が通らず、汚れは教わるものではない。"}, {"text": "寿命", "is_correct": false, "explanation": "「筆の寿命を教える」は使い方の指導とは合わない。"}, {"text": "値段", "is_correct": false, "explanation": "「筆の値段を一つずつ教える」は使い方の指導ではない。"}], "explanations": {"使い": "「筆の使いを教える」は使い方を教える意味で成り立つ。", "汚れ": "「筆の汚れを教える」は意味が通らず、汚れは教わるものではない。", "寿命": "「筆の寿命を教える」は使い方の指導とは合わない。", "値段": "「筆の値段を一つずつ教える」は使い方の指導ではない。"}, "sentence_index": 6, "correct_answer": "使い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "機械は使いを怠ると、すぐに壊れます。", "explanation": "ここは〈手入れ（保つための世話）〉の意味。使いを怠るとは言わず、手入れを怠ると言う。"}, {"text": "車に燃料の使いを補給しました。", "explanation": "ここは〈補給（足りないものを足す）〉の意味。使い方は燃料のように補給できない。"}, {"text": "部屋の使いを掃除して、物を片づけました。", "explanation": "ここは〈清掃（汚れを取ること）〉の意味。使い方は汚れを取る対象にならないので、「部屋を掃除して」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53555, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい包丁の使いを慣れるまで、少し時間がかかります。", "corrected_sentence": "新しい包丁の使いに慣れるまで、少し時間がかかります。", "error_description": "「慣れる」は「〜に慣れる」と続けるので、「使いを」ではなく「使いに」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53555, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ガスの使いを消してから、料理を始めました。", "corrected_sentence": "ガスの使いを学んでから、料理を始めました。", "error_description": "「使い（使い方）」は「学ぶ」ものなので、「消す」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
