INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53556, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「石の使いを学ぶ」と目的語を示し、文が成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「使いが学ぶ」は主語として並ぶが、使い方は学ぶ主体になれず成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「石の使いへ学ぶ」は方向の形で、この文に合わない。"}, {"text": "と", "is_correct": false, "explanation": "「石の使いと学ぶ」は共同の形で、学ぶ対象として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「石の使いを学ぶ」と目的語を示し、文が成り立つ。", "が": "「使いが学ぶ」は主語として並ぶが、使い方は学ぶ主体になれず成り立たない。", "へ": "「石の使いへ学ぶ」は方向の形で、この文に合わない。", "と": "「石の使いと学ぶ」は共同の形で、学ぶ対象として成り立たない。"}, "error_tags": {"へ": "方向", "と": "相手・共同", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53556, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を利用したり処理したりする方法。特に材料や技術の扱い方を指します。", "primary_collocate": null, "pronunciation": "つかい", "ipa": "tsɯkai", "syllable_count": 3, "sentences": [{"text": "絵の具の使いが上手で、色がとてもきれいです。", "target_word": "使い", "complexity_tier": "T3", "furigana": "絵[え]の具[ぐ]の使[つか]いが上手[じょうず]で、色[いろ]がとてもきれいです。", "sentence_source": "generated"}, {"text": "木材の使いに工夫があるので、家が長持ちします。", "target_word": "使い", "complexity_tier": "T3", "furigana": "木材[もくざい]の使[つか]いに工夫[くふう]があるので、家[いえ]が長持[ながも]ちします。", "sentence_source": "generated"}, {"text": "糸の使いが細かいので、この服はほどけません。", "target_word": "使い", "complexity_tier": "T3", "furigana": "糸[いと]の使[つか]いが細[こま]かいので、この服[ふく]はほどけません。", "sentence_source": "generated"}, {"text": "彼女は布の使いがうまく、少ない布で服を作ります。", "target_word": "使い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は布[ぬの]の使[つか]いがうまく、少[すく]ない布[ぬの]で服[ふく]を作[つく]ります。", "sentence_source": "generated"}, {"text": "材料の使いに無駄がなく、料理が安くできます。", "target_word": "使い", "complexity_tier": "T3", "furigana": "材料[ざいりょう]の使[つか]いに無駄[むだ]がなく、料理[りょうり]が安[やす]くできます。", "sentence_source": "generated"}, {"text": "色の使いが派手な画家なので、絵が目立ちます。", "target_word": "使い", "complexity_tier": "T3", "furigana": "色[いろ]の使[つか]いが派手[はで]な画家[がか]なので、絵[え]が目立[めだ]ちます。", "sentence_source": "generated"}, {"text": "鉄の使いを工夫すれば、橋を軽く作れます。", "target_word": "使い", "complexity_tier": "T3", "furigana": "鉄[てつ]の使[つか]いを工夫[くふう]すれば、橋[はし]を軽[かる]く作[つく]れます。", "sentence_source": "generated"}, {"text": "石の使いを学ぶために、職人のもとで働いています。", "target_word": "使い", "complexity_tier": "T3", "furigana": "石[いし]の使[つか]いを学[まな]ぶために、職人[しょくにん]のもとで働[はたら]いています。", "sentence_source": "generated"}, {"text": "紙の使いが上手な人は、一枚から箱を作ります。", "target_word": "使い", "complexity_tier": "T3", "furigana": "紙[かみ]の使[つか]いが上手[じょうず]な人[ひと]は、一枚[いちまい]から箱[はこ]を作[つく]ります。", "sentence_source": "generated"}, {"text": "光の使いがうまい写真は、見る人の心に残ります。", "target_word": "使い", "complexity_tier": "T3", "furigana": "光[ひかり]の使[つか]いがうまい写真[しゃしん]は、見[み]る人[ひと]の心[こころ]に残[のこ]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "使い", "label": "基本形"}], "register": "丁寧", "sense_fingerprint": "材料や技術をどう扱い生かすかという方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53556, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使い", "is_correct": true, "explanation": "「絵の具の使いが上手」は材料の扱い方の意味で、「色がきれい」とつながる。"}, {"text": "種類", "is_correct": false, "explanation": "「絵の具の種類が上手」は続かず、扱いの上手さを表せない。"}, {"text": "値段", "is_correct": false, "explanation": "「絵の具の値段が上手」は意味が通らない。"}, {"text": "量", "is_correct": false, "explanation": "「絵の具の量が上手」は扱い方の話にならない。"}], "explanations": {"使い": "「絵の具の使いが上手」は材料の扱い方の意味で、「色がきれい」とつながる。", "種類": "「絵の具の種類が上手」は続かず、扱いの上手さを表せない。", "値段": "「絵の具の値段が上手」は意味が通らない。", "量": "「絵の具の量が上手」は扱い方の話にならない。"}, "sentence_index": 0, "correct_answer": "使い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母に使いを頼まれて、布を買いに行きました。", "explanation": "ここは〈お使い〉の意味。材料の扱い方の意味では合わない。"}, {"text": "この店は布の使いが安く、一枚から服を作ってくれます。", "explanation": "ここは〈値段〉の意味。使い方には安い・高いの値段がないので、値段の話には使えない。"}, {"text": "王様の使いが、遠くの国から布を届けました。", "explanation": "ここは〈使者〉の意味。材料や技術の扱い方とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53556, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使い", "is_correct": true, "explanation": "「鉄の使いを工夫すれば」は材料の扱い方の意味で、橋を軽く作る話と合う。"}, {"text": "色", "is_correct": false, "explanation": "「鉄の色を工夫すれば橋を軽く作れる」は文の意味が通らない。"}, {"text": "値段", "is_correct": false, "explanation": "「鉄の値段を工夫すれば」は橋を軽くする話にならない。"}, {"text": "寿命", "is_correct": false, "explanation": "「鉄の寿命を工夫すれば」は橋を軽く作ることと結びつかない。"}], "explanations": {"使い": "「鉄の使いを工夫すれば」は材料の扱い方の意味で、橋を軽く作る話と合う。", "色": "「鉄の色を工夫すれば橋を軽く作れる」は文の意味が通らない。", "値段": "「鉄の値段を工夫すれば」は橋を軽くする話にならない。", "寿命": "「鉄の寿命を工夫すれば」は橋を軽く作ることと結びつかない。"}, "sentence_index": 6, "correct_answer": "使い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は使いが明るく、商品がよく見えます。", "explanation": "ここは〈照明〉の意味。使い方は「明るい」と言えず、照明の話にならない。"}, {"text": "この機械は使いが長く、十年以上使えます。", "explanation": "ここは〈寿命〉の意味。使い方は時間の長さを表さない。"}, {"text": "この橋は使いが高く、大きな地震にも耐えます。", "explanation": "ここは〈強度〉の意味。使い方の高さでは強さを表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53556, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "竹の使いに工夫すれば、軽い道具が作れます。", "corrected_sentence": "竹の使いを工夫すれば、軽い道具が作れます。", "error_description": "「工夫する」は目的語に「を」を取るので、「使いに」ではなく「使いを」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53556, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "金属の使いを消せば、道具を長持ちさせられます。", "corrected_sentence": "金属の使いを学べば、道具を長持ちさせられます。", "error_description": "「使い」は「学ぶ」ものなので、「消す」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53561, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拙劣", "is_correct": true, "explanation": "「拙劣」は下手でまずいことで、「巧妙」の対義語として辞書に並ぶ。"}, {"text": "穏やか", "is_correct": false, "explanation": "「穏やか」は穏和で落ち着いた様子で、「巧妙」の対義語ではない。"}, {"text": "豪快", "is_correct": false, "explanation": "「豪快」は大きく勢いのある様子で、「巧妙」の対義語ではない。"}, {"text": "大胆", "is_correct": false, "explanation": "「大胆」は物怖じしない様子で、「巧妙」の対義語ではない。"}], "correct_answer": "拙劣", "explanations": {"拙劣": "「拙劣」は下手でまずいことで、「巧妙」の対義語として辞書に並ぶ。", "穏やか": "「穏やか」は穏和で落ち着いた様子で、「巧妙」の対義語ではない。", "豪快": "「豪快」は大きく勢いのある様子で、「巧妙」の対義語ではない。", "大胆": "「大胆」は物怖じしない様子で、「巧妙」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
