INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53561, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "すごく上手に物事をするさまです。", "primary_collocate": null, "pronunciation": "こうみょう", "ipa": "koːmʲoː", "syllable_count": 4, "sentences": [{"text": "手品師の巧妙な手の動きに、客は全く気づかなかった。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "手品師[てじなし]の巧妙[こうみょう]な手[て]の動[うご]きに、客[きゃく]は全[まった]く気[き]づかなかった。", "sentence_source": "generated"}, {"text": "犯人は巧妙にアリバイを作っていた。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "犯人[はんにん]は巧妙[こうみょう]にアリバイを作[つく]っていた。", "sentence_source": "generated"}, {"text": "その作家は巧妙な話の運び方で、読者を最後まで引きつける。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "その作家[さっか]は巧妙[こうみょう]な話[はなし]の運[はこ]び方[かた]で、読者[どくしゃ]を最後[さいご]まで引[ひ]きつける。", "sentence_source": "generated"}, {"text": "巧妙な言い方で、彼は責任を逃れた。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "巧妙[こうみょう]な言[い]い方[かた]で、彼[かれ]は責任[せきにん]を逃[のが]れた。", "sentence_source": "generated"}, {"text": "巧妙な罠に、さすがの探偵も引っかかった。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "巧妙[こうみょう]な罠[わな]に、さすがの探偵[たんてい]も引[ひ]っかかった。", "sentence_source": "generated"}, {"text": "彼女は巧妙に話題を変えて、嫌な質問をかわした。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は巧妙[こうみょう]に話題[わだい]を変[か]えて、嫌[いや]な質問[しつもん]をかわした。", "sentence_source": "generated"}, {"text": "この絵には、光と影が巧妙に描かれている。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "この絵[え]には、光[ひかり]と影[かげ]が巧妙[こうみょう]に描[えが]かれている。", "sentence_source": "generated"}, {"text": "巧妙な手口の詐欺が、最近ふえている。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "巧妙[こうみょう]な手口[てぐち]の詐欺[さぎ]が、最近[さいきん]ふえている。", "sentence_source": "generated"}, {"text": "猫は巧妙に人の目をぬすんで、魚を持っていった。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "猫[ねこ]は巧妙[こうみょう]に人[ひと]の目[め]をぬすんで、魚[さかな]を持[も]っていった。", "sentence_source": "generated"}, {"text": "営業の彼は巧妙な話し方で、客に商品を買わせた。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "営業[えいぎょう]の彼[かれ]は巧妙[こうみょう]な話[はな]し方[かた]で、客[きゃく]に商品[しょうひん]を買[か]わせた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巧妙だ", "label": "終止形"}, {"form": "巧妙な", "label": "連体形"}, {"form": "巧妙に", "label": "連用形"}, {"form": "巧妙で", "label": "て形"}], "register": "neutral", "sense_fingerprint": "やり方がとても上手で、うまく物事を運ぶさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8503e420-2e43-4260-ba32-e792b859c9e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53561, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巧妙", "is_correct": true, "explanation": "「巧妙」は手際よく策を使うさまで、手の動きを修飾する文に合う。"}, {"text": "陰気", "is_correct": false, "explanation": "「陰気」は暗く沈んだ雰囲気を表すので、手の動きを修飾すると意味が通らない。"}, {"text": "愉快", "is_correct": false, "explanation": "「愉快」は楽しく気持ちがよいことで、手の動きの説明には合わない。"}, {"text": "厳粛", "is_correct": false, "explanation": "「厳粛」は引き締まって重々しいことで、手の動きを修飾する文には合わない。"}], "explanations": {"巧妙": "「巧妙」は手際よく策を使うさまで、手の動きを修飾する文に合う。", "陰気": "「陰気」は暗く沈んだ雰囲気を表すので、手の動きを修飾すると意味が通らない。", "愉快": "「愉快」は楽しく気持ちがよいことで、手の動きの説明には合わない。", "厳粛": "「厳粛」は引き締まって重々しいことで、手の動きを修飾する文には合わない。"}, "sentence_index": 0, "correct_answer": "巧妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は巧妙に荷物を放り投げ、中身を壊した。", "explanation": "ここは〈雑〉の意味。雑な扱いは雑で言い、巧妙は上手な手際に使うので合わない。"}, {"text": "彼は泳ぎが巧妙で、どの選手よりも速い。", "explanation": "ここは〈巧み〉の意味。技能の上手さは巧みで言い、巧妙は仕組みや策のうまさに使うので合わない。"}, {"text": "旅行の準備は巧妙に慌ただしく済まされていた。", "explanation": "ここは〈慌ただしい〉の意味。忙しく落ち着かない様子を言うので、巧妙（手際の良さ）とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53561, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巧妙", "is_correct": true, "explanation": "「巧妙」は手際よく工夫して描く様子で、光と影の描き方を表す文に合う。"}, {"text": "凶暴", "is_correct": false, "explanation": "「凶暴」は荒々しく乱暴なことで、描き方を修飾する文には合わない。"}, {"text": "冷淡", "is_correct": false, "explanation": "「冷淡」は思いやりがなく冷たいことで、描き方を説明する文には合わない。"}, {"text": "軽薄", "is_correct": false, "explanation": "「軽薄」は考えや態度が浅はかなことで、絵の描き方を表す文には合わない。"}], "explanations": {"巧妙": "「巧妙」は手際よく工夫して描く様子で、光と影の描き方を表す文に合う。", "凶暴": "「凶暴」は荒々しく乱暴なことで、描き方を修飾する文には合わない。", "冷淡": "「冷淡」は思いやりがなく冷たいことで、描き方を説明する文には合わない。", "軽薄": "「軽薄」は考えや態度が浅はかなことで、絵の描き方を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "巧妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この模型は巧妙に塗られたが、塗りむらが多く粗末だ。", "explanation": "ここは〈粗末〉の意味。出来が悪くてみすぼらしいことは粗末で言い、巧妙は上手な出来栄えに使うので合わない。"}, {"text": "ベテランの職人は、巧妙に大きな器を割ってしまった。", "explanation": "ここは〈不注意〉の意味。うっかり失敗することは不注意で言い、巧妙は上手な手際を指すので合わない。"}, {"text": "この腕時計は巧妙に作られたが、三日で止まった。", "explanation": "ここは〈粗悪〉の意味。質が悪く壊れやすいことは粗悪で言い、巧妙は上手な出来栄えに使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53561, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "犯人は巧妙に手口で証拠を隠していた。", "corrected_sentence": "犯人は巧妙な手口で証拠を隠していた。", "error_description": "形状詞は名詞の前で「な」の形にする。「巧妙に」は連用形で、名詞「手口」の前に置いたのが誤り。正しくは「巧妙な手口」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "巧妙に", "is_correct": true, "explanation": "文中の形。連用形で、後ろの「作っていた」を修飾している。"}, {"text": "巧妙だ", "is_correct": false, "explanation": "終止形。文を言い切る形で、動詞を修飾する位置には合わない。"}, {"text": "巧妙ならば", "is_correct": false, "explanation": "仮定形。条件を述べる形で、動詞の前の位置には合わない。"}, {"text": "巧妙で", "is_correct": false, "explanation": "て形。文をつなぐ形で、動詞を修飾する位置には合わない。"}], "correct_form": "巧妙に", "base_form": "巧妙だ", "form_label": "連用形", "sentence_index": 1, "explanations": {"巧妙に": "文中の形。連用形で、後ろの「作っていた」を修飾している。", "巧妙だ": "終止形。文を言い切る形で、動詞を修飾する位置には合わない。", "巧妙ならば": "仮定形。条件を述べる形で、動詞の前の位置には合わない。", "巧妙で": "て形。文をつなぐ形で、動詞を修飾する位置には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53561, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は巧妙の作戦で相手の裏をかいた。", "corrected_sentence": "彼は巧妙な作戦で相手の裏をかいた。", "error_description": "形状詞は名詞を修飾するとき「な」を使う。「巧妙の」は「の」を付けた誤りで、正しくは「巧妙な作戦」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "巧妙な", "is_correct": true, "explanation": "文中の形。連体形で後ろの「詐欺」を修飾している。"}, {"text": "巧妙だった", "is_correct": false, "explanation": "過去の終止形。文を言い切る形で、名詞の前には置けない。"}, {"text": "巧妙さ", "is_correct": false, "explanation": "名詞化した形。後ろの名詞「手口」を直接修飾できない。"}, {"text": "巧妙だろう", "is_correct": false, "explanation": "推量の形。文末で使う形で、名詞「手口」の前には置けない。"}], "correct_form": "巧妙な", "base_form": "巧妙だ", "form_label": "連体形", "sentence_index": 7, "explanations": {"巧妙な": "文中の形。連体形で後ろの「詐欺」を修飾している。", "巧妙だった": "過去の終止形。文を言い切る形で、名詞の前には置けない。", "巧妙さ": "名詞化した形。後ろの名詞「手口」を直接修飾できない。", "巧妙だろう": "推量の形。文末で使う形で、名詞「手口」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53562, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拙劣", "is_correct": true, "explanation": "下手で出来が悪いという意味で、工夫のある上手さの対義語として辞書に並ぶ。"}, {"text": "丁寧", "is_correct": false, "explanation": "注意深さを表す語で、巧妙の対義語ではない。"}, {"text": "確実", "is_correct": false, "explanation": "確かさを表す語で、工夫の有無を基準とする対義関係には入らない。"}, {"text": "誠実", "is_correct": false, "explanation": "真心を表す語で、巧妙さとは別の評価軸にある。"}], "correct_answer": "拙劣", "explanations": {"拙劣": "下手で出来が悪いという意味で、工夫のある上手さの対義語として辞書に並ぶ。", "丁寧": "注意深さを表す語で、巧妙の対義語ではない。", "確実": "確かさを表す語で、工夫の有無を基準とする対義関係には入らない。", "誠実": "真心を表す語で、巧妙さとは別の評価軸にある。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53562, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稚拙", "is_correct": true, "explanation": "幼く未熟な出来を表し、工夫のある巧みさの対義語として辞書に並ぶ。"}, {"text": "大胆", "is_correct": false, "explanation": "思い切りの良さを表す語で、巧妙さと対立する語ではない。"}, {"text": "簡潔", "is_correct": false, "explanation": "無駄がない様子を表し、工夫の反対語ではない。"}, {"text": "厳格", "is_correct": false, "explanation": "厳しさを表す語で、巧妙の対義語とは関係しない。"}], "correct_answer": "稚拙", "explanations": {"稚拙": "幼く未熟な出来を表し、工夫のある巧みさの対義語として辞書に並ぶ。", "大胆": "思い切りの良さを表す語で、巧妙さと対立する語ではない。", "簡潔": "無駄がない様子を表し、工夫の反対語ではない。", "厳格": "厳しさを表す語で、巧妙の対義語とは関係しない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53562, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事を非常に上手に、また工夫して行うさま。", "primary_collocate": null, "pronunciation": "こうみょう", "ipa": "koːmʲoː", "syllable_count": 4, "sentences": [{"text": "巧妙な仕掛けのおもちゃで、子どもたちは何時間も遊んだ。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "巧妙[こうみょう]な仕掛[しか]けのおもちゃで、子[こ]どもたちは何時間[なんじかん]も遊[あそ]んだ。", "sentence_source": "generated"}, {"text": "この時計は、内部が巧妙に設計されている。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "この時計[とけい]は、内部[ないぶ]が巧妙[こうみょう]に設計[せっけい]されている。", "sentence_source": "generated"}, {"text": "昔の大工は巧妙な工夫で、釘を使わずに家を建てた。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "昔[むかし]の大工[だいく]は巧妙[こうみょう]な工夫[くふう]で、釘[くぎ]を使[つか]わずに家[いえ]を建[た]てた。", "sentence_source": "generated"}, {"text": "巧妙な宣伝方法のおかげで、新商品はよく売れた。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "巧妙[こうみょう]な宣伝[せんでん]方法[ほうほう]のおかげで、新商品[しんしょうひん]はよく売[う]れた。", "sentence_source": "generated"}, {"text": "推理小説の巧妙なトリックに、最後まで気づかなかった。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "推理[すいり]小説[しょうせつ]の巧妙[こうみょう]なトリックに、最後[さいご]まで気[き]づかなかった。", "sentence_source": "generated"}, {"text": "敵は地形を巧妙に利用して、わが軍を追いつめた。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "敵[てき]は地形[ちけい]を巧妙[こうみょう]に利用[りよう]して、わが軍[ぐん]を追[お]いつめた。", "sentence_source": "generated"}, {"text": "彼女の巧妙なアイデアで、費用を半分に減らせた。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の巧妙[こうみょう]なアイデアで、費用[ひよう]を半分[はんぶん]に減[へ]らせた。", "sentence_source": "generated"}, {"text": "この庭は、景色を巧妙に取り入れて作られている。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "この庭[にわ]は、景色[けしき]を巧妙[こうみょう]に取[と]り入[い]れて作[つく]られている。", "sentence_source": "generated"}, {"text": "巧妙な仕組みの鍵なので、簡単には開けられない。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "巧妙[こうみょう]な仕組[しく]みの鍵[かぎ]なので、簡単[かんたん]には開[あ]けられない。", "sentence_source": "generated"}, {"text": "彼は巧妙に時間を割り振って、三つの仕事を終えた。", "target_word": "巧妙", "complexity_tier": "T3", "furigana": "彼[かれ]は巧妙[こうみょう]に時間[じかん]を割[わ]り振[ふ]って、三[みっ]つの仕事[しごと]を終[お]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "巧妙だ", "label": "終止形"}, {"form": "巧妙な", "label": "連体形"}, {"form": "巧妙に", "label": "連用形"}, {"form": "巧妙で", "label": "て形"}], "register": "neutral", "sense_fingerprint": "工夫をこらして、非常に上手に物事を行うさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8503e420-2e43-4260-ba32-e792b859c9e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53562, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巧妙", "is_correct": true, "explanation": "工夫をこらして上手に作られた様子を表し、仕掛けを修飾する語として自然に入る。"}, {"text": "退屈", "is_correct": false, "explanation": "面白みがないという意味で、何時間も遊んだ文脈と矛盾する。"}, {"text": "乱暴", "is_correct": false, "explanation": "荒っぽく扱う様子を表し、仕掛けの作りを述べる文脈に合わない。"}, {"text": "危険", "is_correct": false, "explanation": "安全性に問題があるという意味で、子どもが何時間も遊ぶ文脈には合わない。"}], "explanations": {"巧妙": "工夫をこらして上手に作られた様子を表し、仕掛けを修飾する語として自然に入る。", "退屈": "面白みがないという意味で、何時間も遊んだ文脈と矛盾する。", "乱暴": "荒っぽく扱う様子を表し、仕掛けの作りを述べる文脈に合わない。", "危険": "安全性に問題があるという意味で、子どもが何時間も遊ぶ文脈には合わない。"}, "sentence_index": 0, "correct_answer": "巧妙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜明け前に、空が巧妙に明るくなった。", "explanation": "「次第に」の意味で巧妙を使っているが、巧妙は人が工夫して上手に行うさまを表すので、空の明るさの変化には合わない。"}, {"text": "痛みが巧妙に強くなった。", "explanation": "〈ひどく〉の意味で巧妙を使っているが、巧妙は工夫をこらして上手に行うさまを表すので、痛みの程度には使えない。"}, {"text": "寒さで手が巧妙に震えた。", "explanation": "〈わざと〉の意味で巧妙を使っているが、寒さによる震えは意図しない反応なので、工夫の意味の巧妙とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53562, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巧妙", "is_correct": true, "explanation": "工夫の鋭さを表し、アイデアを修飾する語として自然に入る。"}, {"text": "無関係", "is_correct": false, "explanation": "関係がないという意味で、費用削減の結果を述べる文脈に合わない。"}, {"text": "退屈", "is_correct": false, "explanation": "面白みがないという意味で、アイデアの工夫を表す語として合わない。"}, {"text": "不愉快", "is_correct": false, "explanation": "不快だという意味で、うまく費用を減らせた文脈と合わない。"}], "explanations": {"巧妙": "工夫の鋭さを表し、アイデアを修飾する語として自然に入る。", "無関係": "関係がないという意味で、費用削減の結果を述べる文脈に合わない。", "退屈": "面白みがないという意味で、アイデアの工夫を表す語として合わない。", "不愉快": "不快だという意味で、うまく費用を減らせた文脈と合わない。"}, "sentence_index": 6, "correct_answer": "巧妙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は英語が巧妙で、海外の仕事もこなせる。", "explanation": "「流暢」の意味で巧妙を使っているが、巧妙は仕掛けや工夫の出来映えに使う語で、語学の運用力には合わない。"}, {"text": "彼女は巧妙に悲しみを感じて、涙をこぼした。", "explanation": "〈しみじみ〉の意味で巧妙を使っているが、巧妙は工夫をこらして上手に行うさまを表すので、感情の深さには使えない。"}, {"text": "寝ぼけた彼は、ドアにぶつかって巧妙に転んだ。", "explanation": "〈うっかり〉の意味で巧妙を使っているが、巧妙は意図して工夫する行為の様子を表すので、無意識の転倒には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53562, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この装置は、内部が巧妙で組み立てられている。", "corrected_sentence": "この装置は、内部が巧妙に組み立てられている。", "error_description": "「巧妙で」は誤り。後ろの「組み立てられている」を修飾するので、連用形の「巧妙に」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "巧妙に", "is_correct": true, "explanation": "形容動詞の連用形で、後ろの動詞「設計されている」を修飾する形として正しい。"}, {"text": "巧妙な", "is_correct": false, "explanation": "連体形で名詞を修飾する形。動詞の組み立てを修飾する位置には入らない。"}, {"text": "巧妙だ", "is_correct": false, "explanation": "文を言い切る終止形で、「内部が〜組み立てられている」の修飾語の位置に合わない。"}, {"text": "巧妙で", "is_correct": false, "explanation": "て形で文をつなぐ形。ここでは動詞を修飾できない。"}], "correct_form": "巧妙に", "base_form": "巧妙だ", "form_label": "連用形", "sentence_index": 1, "explanations": {"巧妙に": "形容動詞の連用形で、後ろの動詞「設計されている」を修飾する形として正しい。", "巧妙な": "連体形で名詞を修飾する形。動詞の組み立てを修飾する位置には入らない。", "巧妙だ": "文を言い切る終止形で、「内部が〜組み立てられている」の修飾語の位置に合わない。", "巧妙で": "て形で文をつなぐ形。ここでは動詞を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53562, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の巧妙やり方で、費用を半分に減らせた。", "corrected_sentence": "彼の巧妙なやり方で、費用を半分に減らせた。", "error_description": "「巧妙やり方」は誤り。名詞「やり方」を修飾する形容動詞の連体形「巧妙な」が必要で、「な」が抜けている。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "巧妙に", "is_correct": true, "explanation": "形容動詞の連用形で、後ろの動詞「取り入れて作られている」を修飾する形として正しい。"}, {"text": "巧妙でない", "is_correct": false, "explanation": "否定形で、肯定の文脈には入らない。"}, {"text": "巧妙だった", "is_correct": false, "explanation": "過去の形で、現在の状態を述べる文には合わない。"}, {"text": "巧妙であった", "is_correct": false, "explanation": "文語的な過去の形で、この文の口語的な流れには合わない。"}], "correct_form": "巧妙に", "base_form": "巧妙だ", "form_label": "連用形", "sentence_index": 7, "explanations": {"巧妙に": "形容動詞の連用形で、後ろの動詞「取り入れて作られている」を修飾する形として正しい。", "巧妙でない": "否定形で、肯定の文脈には入らない。", "巧妙だった": "過去の形で、現在の状態を述べる文には合わない。", "巧妙であった": "文語的な過去の形で、この文の口語的な流れには合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f1835bf-2bc9-4d4f-a274-2532833631e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
