INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53563, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "きれいな心で、わるいことやずるいことをしないさま。", "primary_collocate": null, "pronunciation": "いさぎよい", "ipa": "isaɡijoi", "syllable_count": 5, "sentences": [{"text": "彼は潔い人で、ずるいことを一度もしません。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "彼[かれ]は潔[いさぎよ]い人[ひと]で、ずるいことを一度[いちど]もしません。", "sentence_source": "generated"}, {"text": "潔い心を持つ先生は、お金を受け取りませんでした。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "潔[いさぎよ]い心[こころ]を持[も]つ先生[せんせい]は、お金[かね]を受[う]け取[と]りませんでした。", "sentence_source": "generated"}, {"text": "正直で潔い子どもは、悪いことを見ても黙りません。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "正直[しょうじき]で潔[いさぎよ]い子[こ]どもは、悪[わる]いことを見[み]ても黙[だま]りません。", "sentence_source": "generated"}, {"text": "祖父は潔い人で、うそを言ったことがありません。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "祖父[そふ]は潔[いさぎよ]い人[ひと]で、うそを言[い]ったことがありません。", "sentence_source": "generated"}, {"text": "潔い態度の彼女は、みんなに信頼されています。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "潔[いさぎよ]い態度[たいど]の彼女[かのじょ]は、みんなに信頼[しんらい]されています。", "sentence_source": "generated"}, {"text": "潔い政治家なので、お金の使い道をすべて見せました。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "潔[いさぎよ]い政治家[せいじか]なので、お金[かね]の使[つか]い道[みち]をすべて見[み]せました。", "sentence_source": "generated"}, {"text": "あの店主は潔くて、悪い品は売らないと決めています。", "target_word": "潔くて", "complexity_tier": "T3", "furigana": "あの店主[てんしゅ]は潔[いさぎよ]くて、悪[わる]い品[しな]は売[う]らないと決[き]めています。", "sentence_source": "generated"}, {"text": "潔い人は、かくしごとをせず、はっきり話します。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "潔[いさぎよ]い人[ひと]は、かくしごとをせず、はっきり話[はな]します。", "sentence_source": "generated"}, {"text": "彼女の潔い生き方を、私は尊敬しています。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の潔[いさぎよ]い生[い]き方[かた]を、私[わたし]は尊敬[そんけい]しています。", "sentence_source": "generated"}, {"text": "あの子は潔いので、友だちのものを黙って使いません。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "あの子[こ]は潔[いさぎよ]いので、友[とも]だちのものを黙[だま]って使[つか]いません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潔い", "label": "基本形"}, {"form": "潔く", "label": "連用形"}, {"form": "潔かった", "label": "過去形"}, {"form": "潔くない", "label": "否定形"}], "register": "丁寧", "sense_fingerprint": "心が正しく、ずるいことをしない様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53563, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潔い", "is_correct": true, "explanation": "「ずるいことを一度もしない」人を表し、文脈と合う。"}, {"text": "厚い", "is_correct": false, "explanation": "「厚い人」は心の正しさの意味にならず、文が通らない。"}, {"text": "涼しい", "is_correct": false, "explanation": "「涼しい人」は性格を表す語として不自然で、文の意味に合わない。"}, {"text": "臭い", "is_correct": false, "explanation": "「臭い人」は人柄の意味にならず、文脈と矛盾する。"}], "explanations": {"潔い": "「ずるいことを一度もしない」人を表し、文脈と合う。", "厚い": "「厚い人」は心の正しさの意味にならず、文が通らない。", "涼しい": "「涼しい人」は性格を表す語として不自然で、文の意味に合わない。", "臭い": "「臭い人」は人柄の意味にならず、文脈と矛盾する。"}, "sentence_index": 0, "correct_answer": "潔い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は潔い性格で、いつも約束を破ります。", "explanation": "ここは〈不誠実（約束を守らないこと）〉の意味。「潔い」は約束を守る清さを表すので、約束を破る人には使わない。"}, {"text": "彼は潔い服で、みんなの注目を集めました。", "explanation": "ここは〈派手（人目を引く華やかさ）〉の意味。「潔い」は心の正しさや割り切りを表し、見た目の華やかさには使わない。"}, {"text": "彼は潔くて、いつも答えがはっきりしません。", "explanation": "「潔い」は心の清さを表すので、答えを曖昧にする様子とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53563, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潔くて", "is_correct": true, "explanation": "「店主は潔くて」と性質を並べる形で、後半の「悪い品は売らない」と合う。"}, {"text": "重くて", "is_correct": false, "explanation": "「店主は重くて」は性格の意味にならず、文脈と合わない。"}, {"text": "暑くて", "is_correct": false, "explanation": "「店主は暑くて」は人柄の意味にならず、文が通らない。"}, {"text": "狭くて", "is_correct": false, "explanation": "「店主は狭くて」は性格の意味として不自然で、文脈と合わない。"}], "explanations": {"潔くて": "「店主は潔くて」と性質を並べる形で、後半の「悪い品は売らない」と合う。", "重くて": "「店主は重くて」は性格の意味にならず、文脈と合わない。", "暑くて": "「店主は暑くて」は人柄の意味にならず、文が通らない。", "狭くて": "「店主は狭くて」は性格の意味として不自然で、文脈と合わない。"}, "sentence_index": 6, "correct_answer": "潔くて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は潔い態度で、みんなを見下しました。", "explanation": "ここは〈高慢（人を見下す態度）〉の意味。「潔い」は心の正しさを表すので、見下す態度には使わない。"}, {"text": "潔い人は、友だちの悪口を言いふらします。", "explanation": "ここは〈陰険（ひそかに人を陥れること）〉の意味。「潔い」は悪口や卑劣な行いをしない清さを表すので、陰険な人には使わない。"}, {"text": "潔い彼は、またうそをつきました。", "explanation": "ここは〈嘘つき（うそを言うこと）〉の意味。「潔い」はうそをつかない清さを表すので、うそつきの人には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53563, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "あの人は潔いの性格なので、約束を必ず守ります。", "corrected_sentence": "あの人は潔い性格なので、約束を必ず守ります。", "error_description": "い形容詞「潔い」は名詞の前に直接置くので、「潔いの性格」の「の」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "潔い", "is_correct": true, "explanation": "「潔い心」と名詞を直接修飾する形で、連体形の基本形と一致する。"}, {"text": "潔く", "is_correct": false, "explanation": "連用形で、名詞を修飾する形ではないため、「潔く心」は成り立たない。"}, {"text": "潔くて", "is_correct": false, "explanation": "接続の形で、名詞「心」を直接修飾できない。"}, {"text": "潔ければ", "is_correct": false, "explanation": "仮定形で、名詞「心」を修飾する形にならない。"}], "correct_form": "潔い", "base_form": "潔い", "form_label": "連体形", "sentence_index": 1, "explanations": {"潔い": "「潔い心」と名詞を直接修飾する形で、連体形の基本形と一致する。", "潔く": "連用形で、名詞を修飾する形ではないため、「潔く心」は成り立たない。", "潔くて": "接続の形で、名詞「心」を直接修飾できない。", "潔ければ": "仮定形で、名詞「心」を修飾する形にならない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53563, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの子は潔いく、友だちのものを勝手に使いませんでした。", "corrected_sentence": "あの子は潔く、友だちのものを勝手に使いませんでした。", "error_description": "い形容詞「潔い」の連用形は「潔く」で、「潔いく」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "潔い", "is_correct": true, "explanation": "「潔い人」と名詞を直接修飾する形で、連体形の基本形と一致する。"}, {"text": "潔さ", "is_correct": false, "explanation": "名詞なので「潔さ人は」と名詞を修飾できず、文が成り立たない。"}, {"text": "潔かろう", "is_correct": false, "explanation": "推量形で、事実を述べるこの文には合わない。"}, {"text": "潔そう", "is_correct": false, "explanation": "様子を表す形で、「潔そう人」と直接名詞を修飾できず文が成り立たない。"}], "correct_form": "潔い", "base_form": "潔い", "form_label": "連体形", "sentence_index": 7, "explanations": {"潔い": "「潔い人」と名詞を直接修飾する形で、連体形の基本形と一致する。", "潔さ": "名詞なので「潔さ人は」と名詞を修飾できず、文が成り立たない。", "潔かろう": "推量形で、事実を述べるこの文には合わない。", "潔そう": "様子を表す形で、「潔そう人」と直接名詞を修飾できず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53564, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "未練がましい", "is_correct": true, "explanation": "未練を残して執着する様子を表し、「未練を残さず割り切る」意味の対義語にあたる。"}, {"text": "明るい", "is_correct": false, "explanation": "性格の明るさを表す語で、この意味の対義語ではない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さを表す語で、この意味の対義語ではない。"}, {"text": "柔らかい", "is_correct": false, "explanation": "態度や物の感触を表す語で、この意味の対義語ではない。"}], "correct_answer": "未練がましい", "explanations": {"未練がましい": "未練を残して執着する様子を表し、「未練を残さず割り切る」意味の対義語にあたる。", "明るい": "性格の明るさを表す語で、この意味の対義語ではない。", "遅い": "速さを表す語で、この意味の対義語ではない。", "柔らかい": "態度や物の感触を表す語で、この意味の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
