INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53564, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "未練を残さず、負けや責任をきっぱり受け入れるさま。物事を割り切ってすっきりしていること。", "primary_collocate": null, "pronunciation": "いさぎよい", "ipa": "isaɡijoi", "syllable_count": 5, "sentences": [{"text": "負けたあと、潔く相手に拍手を送りました。", "target_word": "潔く", "complexity_tier": "T3", "furigana": "負[ま]けたあと、潔[いさぎよ]く相手[あいて]に拍手[はくしゅ]を送[おく]りました。", "sentence_source": "generated"}, {"text": "彼は失敗を潔く認めて、みんなにあやまりました。", "target_word": "潔く", "complexity_tier": "T3", "furigana": "彼[かれ]は失敗[しっぱい]を潔[いさぎよ]く認[みと]めて、みんなにあやまりました。", "sentence_source": "generated"}, {"text": "社長は潔くやめることを決めました。", "target_word": "潔く", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は潔[いさぎよ]くやめることを決[き]めました。", "sentence_source": "generated"}, {"text": "潔い態度で負けを認めたので、みんなが彼を好きになりました。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "潔[いさぎよ]い態度[たいど]で負[ま]けを認[みと]めたので、みんなが彼[かれ]を好[す]きになりました。", "sentence_source": "generated"}, {"text": "試合に負けたのに、彼女は潔く握手に応じました。", "target_word": "潔く", "complexity_tier": "T3", "furigana": "試合[しあい]に負[ま]けたのに、彼女[かのじょ]は潔[いさぎよ]く握手[あくしゅ]に応[おう]じました。", "sentence_source": "generated"}, {"text": "言い訳をせず、潔く責任を取りました。", "target_word": "潔く", "complexity_tier": "T3", "furigana": "言[い]い訳[わけ]をせず、潔[いさぎよ]く責任[せきにん]を取[と]りました。", "sentence_source": "generated"}, {"text": "迷わず潔く古い服を全部捨てたら、部屋がすっきりしました。", "target_word": "潔く", "complexity_tier": "T3", "furigana": "迷[まよ]わず潔[いさぎよ]く古[ふる]い服[ふく]を全部[ぜんぶ]捨[す]てたら、部屋[へや]がすっきりしました。", "sentence_source": "generated"}, {"text": "彼女は潔く席をゆずって、次の人に場所をあけました。", "target_word": "潔く", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は潔[いさぎよ]く席[せき]をゆずって、次[つぎ]の人[ひと]に場所[ばしょ]をあけました。", "sentence_source": "generated"}, {"text": "選手は潔い引退を発表し、ファンに感謝しました。", "target_word": "潔い", "complexity_tier": "T3", "furigana": "選手[せんしゅ]は潔[いさぎよ]い引退[いんたい]を発表[はっぴょう]し、ファンに感謝[かんしゃ]しました。", "sentence_source": "generated"}, {"text": "潔くあきらめる気持ちも、ときには大切です。", "target_word": "潔く", "complexity_tier": "T3", "furigana": "潔[いさぎよ]くあきらめる気持[きも]ちも、ときには大切[たいせつ]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "潔い", "label": "基本形"}, {"form": "潔く", "label": "連用形"}, {"form": "潔かった", "label": "過去形"}, {"form": "潔くない", "label": "否定形"}], "register": "丁寧", "sense_fingerprint": "未練を残さず、負けや責任をきっぱり受け入れる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84de0b38-39dc-4a53-bd7e-1244cd628c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53564, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潔く", "is_correct": true, "explanation": "「潔く拍手を送る」は未練なく相手を称える意味で、文脈と合う。"}, {"text": "重たく", "is_correct": false, "explanation": "「重たく拍手を送る」は意味が通らず、拍手の様子としても不自然。"}, {"text": "恥ずかしく", "is_correct": false, "explanation": "「恥ずかしく拍手を送る」は敗者への態度として不自然で、文の意味に合わない。"}, {"text": "疑わしく", "is_correct": false, "explanation": "「疑わしく拍手を送る」は称賛の意味にならず、文脈と合わない。"}], "explanations": {"潔く": "「潔く拍手を送る」は未練なく相手を称える意味で、文脈と合う。", "重たく": "「重たく拍手を送る」は意味が通らず、拍手の様子としても不自然。", "恥ずかしく": "「恥ずかしく拍手を送る」は敗者への態度として不自然で、文の意味に合わない。", "疑わしく": "「疑わしく拍手を送る」は称賛の意味にならず、文脈と合わない。"}, "sentence_index": 0, "correct_answer": "潔く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "犯人は見つかったのに、潔く逃げ出しました。", "explanation": "ここは〈卑怯（こそこそ逃げること）〉の意味。「潔い」はずるいことをしない清さを表すので、逃げ出す行いとは合わない。"}, {"text": "彼は負けたのに潔く、何度も言い訳を続けました。", "explanation": "「潔い」は未練を残さない意味で、何度も言い訳を続ける態度とは矛盾する。"}, {"text": "彼は失敗を潔く誤魔化して、うやむやにしました。", "explanation": "ここは〈誤魔化す（事実をごまかすこと）〉の意味。「潔い」は割り切ってすっきりする意味なので、ごまかす行いには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53564, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潔く", "is_correct": true, "explanation": "「潔く古い服を捨てる」と動作を修飾し、未練なく手放す意味で文と合う。"}, {"text": "細く", "is_correct": false, "explanation": "「細く捨てる」は動作の様子として意味が通らない。"}, {"text": "厚く", "is_correct": false, "explanation": "「厚く捨てる」は文脈と合わず、不自然。"}, {"text": "薄く", "is_correct": false, "explanation": "「薄く捨てる」は意味が通らず、迷いなく処分する様子とも合わない。"}], "explanations": {"潔く": "「潔く古い服を捨てる」と動作を修飾し、未練なく手放す意味で文と合う。", "細く": "「細く捨てる」は動作の様子として意味が通らない。", "厚く": "「厚く捨てる」は文脈と合わず、不自然。", "薄く": "「薄く捨てる」は意味が通らず、迷いなく処分する様子とも合わない。"}, "sentence_index": 6, "correct_answer": "潔く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は潔く相手を脅して、契約を結ばせました。", "explanation": "ここは〈脅迫（力ずくで従わせること）〉の意味。「潔い」はずるい手段を使わない清さを表すので、脅す行いには使わない。"}, {"text": "彼は潔く迷い続け、なかなか契約書にサインしませんでした。", "explanation": "ここは〈優柔不断（迷ってなかなか決められないこと）〉の意味。「潔く」は迷わず割り切る意味なので、迷い続ける様子には使わない。"}, {"text": "彼は潔く不正をして、賞を取りました。", "explanation": "ここは〈不正（ずるいことをすること）〉の意味。「潔い」はずるいことをしない清さなので、不正とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53564, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "負けを潔く認めに、次の大会に進みました。", "corrected_sentence": "負けを潔く認めて、次の大会に進みました。", "error_description": "「認める」の連用形の後は「て」が必要で、「認めに」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "潔く", "is_correct": true, "explanation": "「潔く認めて」と動詞「認める」を修飾する連用形で、文の意味に合う。"}, {"text": "潔い", "is_correct": false, "explanation": "基本形で、動詞「認めて」を修飾する形にはならない。"}, {"text": "潔かった", "is_correct": false, "explanation": "過去形で、動作の様子を表す文に合わない。"}, {"text": "潔くない", "is_correct": false, "explanation": "否定形で、「潔くなく認めて」は文の意味と反対になる。"}], "correct_form": "潔く", "base_form": "潔い", "form_label": "連用形", "sentence_index": 1, "explanations": {"潔く": "「潔く認めて」と動詞「認める」を修飾する連用形で、文の意味に合う。", "潔い": "基本形で、動詞「認めて」を修飾する形にはならない。", "潔かった": "過去形で、動作の様子を表す文に合わない。", "潔くない": "否定形で、「潔くなく認めて」は文の意味と反対になる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53564, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼女は負けを潔い認めて、拍手を受けました。", "corrected_sentence": "彼女は負けを潔く認めて、拍手を受けました。", "error_description": "「認める」を修飾するには連用形の「潔く」が必要で、「潔い」のままでは使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "潔く", "is_correct": true, "explanation": "「潔く席をゆずって」と動詞「ゆずって」を修飾する連用形で、文の意味に合う。"}, {"text": "潔さ", "is_correct": false, "explanation": "名詞なので動詞を修飾できず、「潔さ席をゆずって」は成り立たない。"}, {"text": "潔そう", "is_correct": false, "explanation": "様子を表す形で、動詞の前に直接置くことができず文が成り立たない。"}, {"text": "潔かろう", "is_correct": false, "explanation": "推量の形で、動作の様子を述べる文には合わず、文の構造も成り立たない。"}], "correct_form": "潔く", "base_form": "潔い", "form_label": "連用形", "sentence_index": 7, "explanations": {"潔く": "「潔く席をゆずって」と動詞「ゆずって」を修飾する連用形で、文の意味に合う。", "潔さ": "名詞なので動詞を修飾できず、「潔さ席をゆずって」は成り立たない。", "潔そう": "様子を表す形で、動詞の前に直接置くことができず文が成り立たない。", "潔かろう": "推量の形で、動作の様子を述べる文には合わず、文の構造も成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9173378-f1ed-4444-b1b4-0a035bb09049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53565, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「枝に降り立つ」の「に」で、着地点を示します。"}, {"text": "を", "is_correct": false, "explanation": "「枝を降り立つ」は降り立つを他動詞のように扱う誤りです。"}, {"text": "が", "is_correct": false, "explanation": "「枝が降り立つ」では枝が主語になり、すずめの着地を表せません。"}, {"text": "と", "is_correct": false, "explanation": "「枝と降り立つ」は並列になり、着地点を示せません。"}], "correct_answer": "に", "explanations": {"に": "「枝に降り立つ」の「に」で、着地点を示します。", "を": "「枝を降り立つ」は降り立つを他動詞のように扱う誤りです。", "が": "「枝が降り立つ」では枝が主語になり、すずめの着地を表せません。", "と": "「枝と降り立つ」は並列になり、着地点を示せません。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "飛び立つ", "is_correct": true, "explanation": "地面から空へ出発する意味で、降り立つの対義語として辞書に並べられる語です。"}, {"text": "歩く", "is_correct": false, "explanation": "地上の移動を表す動詞で、空から下りる動きの対義にはなりません。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠を表す動詞で、降下の動きとは対になりません。"}, {"text": "拾う", "is_correct": false, "explanation": "物を取る動作で、降りる動きの対義語にはなりません。"}], "correct_answer": "飛び立つ", "explanations": {"飛び立つ": "地面から空へ出発する意味で、降り立つの対義語として辞書に並べられる語です。", "歩く": "地上の移動を表す動詞で、空から下りる動きの対義にはなりません。", "眠る": "睡眠を表す動詞で、降下の動きとは対になりません。", "拾う": "物を取る動作で、降りる動きの対義語にはなりません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
