INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53565, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "飛行機や鳥が地面につきます。空から下りてきて止まることです。", "primary_collocate": null, "pronunciation": "おりたつ", "ipa": "oɾitatsɯ", "syllable_count": 4, "sentences": [{"text": "飛行機が空港にゆっくり降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "ひこうきがくうこうにゆっくりおりたつ。", "sentence_source": "generated"}, {"text": "すずめが庭の木の枝に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "すずめがにわのきのえだにおりたつ。", "sentence_source": "generated"}, {"text": "空から一羽のハトが、広場に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "そらからいちわのハトが、ひろばにおりたつ。", "sentence_source": "generated"}, {"text": "小さな水上機が湖に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "ちいさなすいじょうきがみずうみにおりたつ。", "sentence_source": "generated"}, {"text": "気球が畑の真ん中に降り立つと、農家の人が驚いた。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "ききゅうがはたけのまんなかにおりたつと、のうかのひとがおどろいた。", "sentence_source": "generated"}, {"text": "タカが獲物を見つけて、地面に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "タカがえものをみつけて、じめんにおりたつ。", "sentence_source": "generated"}, {"text": "霧が晴れたころ、旅客機が無事に滑走路へ降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "きりがはれたころ、りょかくきがぶじにかっそうろへおりたつ。", "sentence_source": "generated"}, {"text": "白鳥が静かな川に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "はくちょうがしずかなかわにおりたつ。", "sentence_source": "generated"}, {"text": "救助のヘリが、山の広い場所に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "きゅうじょのヘリが、やまのひろいばしょにおりたつ。", "sentence_source": "generated"}, {"text": "朝早く、カラスがごみ置き場に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "あさはやく、カラスがごみおきばにおりたつ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "降り立つ", "label": "辞書形"}, {"form": "降り立ち", "label": "連用形"}, {"form": "降り立たない", "label": "否定形"}, {"form": "降り立った", "label": "過去形"}, {"form": "降り立って", "label": "て形"}, {"form": "降り立てば", "label": "仮定形"}, {"form": "降り立とう", "label": "意志形"}], "register": "標準（やや書き言葉）", "sense_fingerprint": "空から下りてきて地面や水面に止まること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53565, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降り立つ", "is_correct": true, "explanation": "「空港にゆっくり降り立つ」は、飛行機が着陸する意味で、この文脈に合います。"}, {"text": "騒ぐ", "is_correct": false, "explanation": "飛行機は騒がないため、「空港に騒ぐ」は着陸の文として成り立ちません。"}, {"text": "眠る", "is_correct": false, "explanation": "飛行機は眠らないため、着陸を表す文脈に合いません。"}, {"text": "凍る", "is_correct": false, "explanation": "「空港に凍る」は着陸の動作を表さず、文の意味が通りません。"}], "explanations": {"降り立つ": "「空港にゆっくり降り立つ」は、飛行機が着陸する意味で、この文脈に合います。", "騒ぐ": "飛行機は騒がないため、「空港に騒ぐ」は着陸の文として成り立ちません。", "眠る": "飛行機は眠らないため、着陸を表す文脈に合いません。", "凍る": "「空港に凍る」は着陸の動作を表さず、文の意味が通りません。"}, "sentence_index": 0, "correct_answer": "降り立つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "石が崖から降り立つ。", "explanation": "ここは〈落下する〉の意味です。降り立つは機体や生き物が地面に下りて着く意味で、石の落下には使いません。"}, {"text": "鳥の群れが一斉に空へ降り立つ。", "explanation": "ここは〈舞い上がる〉の意味です。降り立つは下りて着く動きで、上昇には使いません。"}, {"text": "バスが停留所に降り立つ。", "explanation": "ここは〈停車する〉の意味です。降り立つは空から下りて着く動きで、車が止まることには使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53565, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降り立つ", "is_correct": true, "explanation": "「滑走路へ降り立つ」は、旅客機が着陸する意味で、この文脈に合います。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "旅客機は叫ばないため、「滑走路へ叫ぶ」は着陸の文として成り立ちません。"}, {"text": "踊る", "is_correct": false, "explanation": "旅客機は踊らないため、着陸の動作を表す文脈に合いません。"}, {"text": "割る", "is_correct": false, "explanation": "「滑走路へ割る」は着陸の動作を表さず、文の意味が通りません。"}], "explanations": {"降り立つ": "「滑走路へ降り立つ」は、旅客機が着陸する意味で、この文脈に合います。", "叫ぶ": "旅客機は叫ばないため、「滑走路へ叫ぶ」は着陸の文として成り立ちません。", "踊る": "旅客機は踊らないため、着陸の動作を表す文脈に合いません。", "割る": "「滑走路へ割る」は着陸の動作を表さず、文の意味が通りません。"}, "sentence_index": 6, "correct_answer": "降り立つ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客が座席に降り立つ。", "explanation": "ここは〈着席する〉の意味です。降り立つは地面や水面に下りて着く意味で、座席に座る動作には使いません。"}, {"text": "紙吹雪が舞台に降り立つ。", "explanation": "ここは〈舞い落ちる〉の意味です。降り立つは生き物や機体が地面に下りて着く意味で、紙吹雪が舞い落ちる動きには使いません。"}, {"text": "泥が池の底に降り立つ。", "explanation": "ここは〈沈殿する〉の意味です。降り立つは空から下りて着く動きで、物が沈み積もる場合には使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53565, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夕方、大きなワシが山の斜面を降り立つ。", "corrected_sentence": "夕方、大きなワシが山の斜面に降り立つ。", "error_description": "「降り立つ」の到達先は「に」で示します。「を」は到達先を表せないため誤りです。正しくは「斜面に」です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "降り立つ", "is_correct": true, "explanation": "「枝に降り立つ」の辞書形で、すずめが止まる事実を文末で述べます。"}, {"text": "降り立ち", "is_correct": false, "explanation": "連用形では文を終えられず、述語になりません。"}, {"text": "降り立とう", "is_correct": false, "explanation": "意志形になると、すずめの意志を表す文になり、事実を述べられません。"}, {"text": "降り立てば", "is_correct": false, "explanation": "仮定形では文を終えられず、条件節になります。"}], "correct_form": "降り立つ", "base_form": "降り立つ", "form_label": "辞書形", "sentence_index": 1, "explanations": {"降り立つ": "「枝に降り立つ」の辞書形で、すずめが止まる事実を文末で述べます。", "降り立ち": "連用形では文を終えられず、述語になりません。", "降り立とう": "意志形になると、すずめの意志を表す文になり、事実を述べられません。", "降り立てば": "仮定形では文を終えられず、条件節になります。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53565, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨上がりの空から、白い鳥が畑と降り立つ。", "corrected_sentence": "雨上がりの空から、白い鳥が畑に降り立つ。", "error_description": "「降り立つ」の到達先は「に」で示します。「と」は並列を表すため、到達先には使えません。正しくは「畑に」です。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "降り立つ", "is_correct": true, "explanation": "「白鳥が川に降り立つ」の辞書形で、白鳥が着く事実を文末で述べます。"}, {"text": "降り立って", "is_correct": false, "explanation": "て形では文を終えられず、述語になりません。"}, {"text": "降り立たない", "is_correct": false, "explanation": "否定形にすると、白鳥が降り立たないという逆の内容になります。"}, {"text": "降り立てば", "is_correct": false, "explanation": "仮定形では文を終えられず、条件節になります。"}], "correct_form": "降り立つ", "base_form": "降り立つ", "form_label": "辞書形", "sentence_index": 7, "explanations": {"降り立つ": "「白鳥が川に降り立つ」の辞書形で、白鳥が着く事実を文末で述べます。", "降り立って": "て形では文を終えられず、述語になりません。", "降り立たない": "否定形にすると、白鳥が降り立たないという逆の内容になります。", "降り立てば": "仮定形では文を終えられず、条件節になります。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53566, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「滑走路に降り立つ」の「に」で、着地点を示します。"}, {"text": "を", "is_correct": false, "explanation": "「滑走路を降り立つ」は降り立つを他動詞のように扱う誤りです。"}, {"text": "が", "is_correct": false, "explanation": "「滑走路が降り立つ」では場所が主語になり、文が通りません。"}, {"text": "と", "is_correct": false, "explanation": "「滑走路と降り立つ」は並列になり、着地点を示せません。"}], "correct_answer": "に", "explanations": {"に": "「滑走路に降り立つ」の「に」で、着地点を示します。", "を": "「滑走路を降り立つ」は降り立つを他動詞のように扱う誤りです。", "が": "「滑走路が降り立つ」では場所が主語になり、文が通りません。", "と": "「滑走路と降り立つ」は並列になり、着地点を示せません。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "飛び立つ", "is_correct": true, "explanation": "地面から空へ出発する意味で、降り立つの対義語として辞書に並べられる語です。"}, {"text": "歩く", "is_correct": false, "explanation": "地上の移動を表す動詞で、空から下りる動きの対義にはなりません。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠を表す動詞で、降下の動きとは対になりません。"}, {"text": "拾う", "is_correct": false, "explanation": "物を取る動作で、降りる動きの対義語にはなりません。"}], "correct_answer": "飛び立つ", "explanations": {"飛び立つ": "地面から空へ出発する意味で、降り立つの対義語として辞書に並べられる語です。", "歩く": "地上の移動を表す動詞で、空から下りる動きの対義にはなりません。", "眠る": "睡眠を表す動詞で、降下の動きとは対になりません。", "拾う": "物を取る動作で、降りる動きの対義語にはなりません。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53566, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「ツルが降り立つ」の「が」で、降り立つ主語を示します。"}, {"text": "で", "is_correct": false, "explanation": "「ツルで降り立つ」は手段の意味になり、主語を示せません。"}, {"text": "より", "is_correct": false, "explanation": "「ツルより降り立つ」は比較の形になり、主語にはなりません。"}, {"text": "へ", "is_correct": false, "explanation": "「ツルへ降り立つ」は方向の形になり、降り立つの主語を示せません。"}], "correct_answer": "が", "explanations": {"が": "「ツルが降り立つ」の「が」で、降り立つ主語を示します。", "で": "「ツルで降り立つ」は手段の意味になり、主語を示せません。", "より": "「ツルより降り立つ」は比較の形になり、主語にはなりません。", "へ": "「ツルへ降り立つ」は方向の形になり、降り立つの主語を示せません。"}, "error_tags": {"で": "手段", "より": "比較", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "飛び立つ", "is_correct": true, "explanation": "地面から空へ出発する意味で、降り立つの対義語として辞書に並べられる語です。"}, {"text": "泳ぐ", "is_correct": false, "explanation": "水中を移動する動詞で、空から下りる動きの対義にはなりません。"}, {"text": "話す", "is_correct": false, "explanation": "言葉を発する動詞で、降りる動きとは対になりません。"}, {"text": "眺める", "is_correct": false, "explanation": "見る動作を表す動詞で、降下の対義語にはなりません。"}], "correct_answer": "飛び立つ", "explanations": {"飛び立つ": "地面から空へ出発する意味で、降り立つの対義語として辞書に並べられる語です。", "泳ぐ": "水中を移動する動詞で、空から下りる動きの対義にはなりません。", "話す": "言葉を発する動詞で、降りる動きとは対になりません。", "眺める": "見る動作を表す動詞で、降下の対義語にはなりません。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53566, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "航空機や動物などが着陸すること。高い所から地面まで下りてくるときの動作です。", "primary_collocate": null, "pronunciation": "おりたつ", "ipa": "oɾitatsɯ", "syllable_count": 4, "sentences": [{"text": "大きな鳥が、夕方に湖の岸へ降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "大[おお]きな鳥[とり]が、夕方[ゆうがた]に湖[みずうみ]の岸[きし]へ降[お]り立[た]つ。", "sentence_source": "generated"}, {"text": "飛行機が滑走路に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "ひこうきがかっそうろにおりたつ。", "sentence_source": "generated"}, {"text": "白い鳥が湖のほとりに降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "しろいとりがみずうみのほとりにおりたつ。", "sentence_source": "generated"}, {"text": "ヘリコプターが病院の屋上に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "ヘリコプターがびょういんのおくじょうにおりたつ。", "sentence_source": "generated"}, {"text": "大きなワシが、岩の上に静かに降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "おおきなワシが、いわのうえにしずかにおりたつ。", "sentence_source": "generated"}, {"text": "宇宙船が月の表面に降り立つ瞬間を、世界中が見守った。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "うちゅうせんがつきのひょうめんにおりたつしゅんかんを、せかいじゅうがみまもった。", "sentence_source": "generated"}, {"text": "渡り鳥が、冬になると池に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "わたりどりが、ふゆになるといけにおりたつ。", "sentence_source": "generated"}, {"text": "雪の中に、一羽のツルが降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "ゆきのなかに、いちわのツルがおりたつ。", "sentence_source": "generated"}, {"text": "ドローンが庭の中央に降り立つと、子どもたちが集まった。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "ドローンがにわのちゅうおうにおりたつと、こどもたちがあつまった。", "sentence_source": "generated"}, {"text": "夜明けとともに、カモメが港の船に降り立つ。", "target_word": "降り立つ", "complexity_tier": "T3", "furigana": "よあけとともに、カモメがみなとのふねにおりたつ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "降り立つ", "label": "辞書形"}, {"form": "降り立ち", "label": "連用形"}, {"form": "降り立たない", "label": "否定形"}, {"form": "降り立った", "label": "過去形"}, {"form": "降り立って", "label": "て形"}, {"form": "降り立てば", "label": "仮定形"}, {"form": "降り立とう", "label": "意志形"}], "register": "標準（やや書き言葉）", "sense_fingerprint": "飛行機・鳥などが空から地面や水面に着くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53566, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降り立つ", "is_correct": true, "explanation": "「湖の岸へ降り立つ」は鳥が着地する意味で、この文脈に合います。"}, {"text": "鳴く", "is_correct": false, "explanation": "トレンドは鳴かないため、「地上に鳴くトレンド」は文として成り立ちません。"}, {"text": "結ぶ", "is_correct": false, "explanation": "「地上に結ぶ」では対象と動作が合わず、文の意味が通りません。"}, {"text": "凍る", "is_correct": false, "explanation": "トレンドは凍らないため、流行を表す文脈に合いません。"}], "explanations": {"降り立つ": "「湖の岸へ降り立つ」は鳥が着地する意味で、この文脈に合います。", "鳴く": "トレンドは鳴かないため、「地上に鳴くトレンド」は文として成り立ちません。", "結ぶ": "「地上に結ぶ」では対象と動作が合わず、文の意味が通りません。", "凍る": "トレンドは凍らないため、流行を表す文脈に合いません。"}, "sentence_index": 0, "correct_answer": "降り立つ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボールが屋根から降り立つ。", "explanation": "ここは〈落下する〉の意味です。降り立つは人や機体が地面に下りて着く意味で、物が落ちる動きには使いません。"}, {"text": "鳥の群れが一斉に空へ降り立つ。", "explanation": "ここは〈舞い上がる〉の意味です。降り立つは上空から下りて着く動きで、上昇には使いません。"}, {"text": "ロケットが宇宙へ降り立つ。", "explanation": "ここは〈上昇する〉の意味です。降り立つは下りてくる動きで、上がっていく場合には使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53566, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降り立つ", "is_correct": true, "explanation": "「池に降り立つ」は、渡り鳥が冬に池へ着く意味で、この文脈に合います。"}, {"text": "踊る", "is_correct": false, "explanation": "渡り鳥が池で踊るという文脈にはならず、着く動作を表せません。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "「池に叫ぶ」は着く動作とは無関係で、文の意味が通りません。"}, {"text": "割る", "is_correct": false, "explanation": "「池を割る」では鳥の行動として成り立たず、着く動作になりません。"}], "explanations": {"降り立つ": "「池に降り立つ」は、渡り鳥が冬に池へ着く意味で、この文脈に合います。", "踊る": "渡り鳥が池で踊るという文脈にはならず、着く動作を表せません。", "叫ぶ": "「池に叫ぶ」は着く動作とは無関係で、文の意味が通りません。", "割る": "「池を割る」では鳥の行動として成り立たず、着く動作になりません。"}, "sentence_index": 6, "correct_answer": "降り立つ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝日が、港の船に降り立つ。", "explanation": "ここは〈差す〉の意味です。降り立つは生き物や機体が地面や水面に着く意味で、光には使いません。"}, {"text": "雨が港の船に降り立つ。", "explanation": "ここは〈降りかかる〉の意味です。降り立つは生き物や機体の着地に使い、雨粒の落下には使いません。"}, {"text": "船が港の底に降り立つ。", "explanation": "ここは〈沈む〉の意味です。降り立つは空から下りて着く動きで、水没には使いません。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53566, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雪のなか、一羽のタカが山頂を降り立つ。", "corrected_sentence": "雪のなか、一羽のタカが山頂に降り立つ。", "error_description": "「降り立つ」の到達先は「に」で示します。「を」は到達先を表せないため誤りです。正しくは「山頂に」です。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "降り立つ", "is_correct": true, "explanation": "「滑走路に降り立つ」の辞書形で、飛行機が着く事実を文末で述べます。"}, {"text": "降り立ち", "is_correct": false, "explanation": "連用形では文を終えられず、述語になりません。"}, {"text": "降り立とう", "is_correct": false, "explanation": "意志形になると、降り立とうという意志の文になり、事実を述べられません。"}, {"text": "降り立てば", "is_correct": false, "explanation": "仮定形では文を終えられず、条件節になります。"}], "correct_form": "降り立つ", "base_form": "降り立つ", "form_label": "辞書形", "sentence_index": 1, "explanations": {"降り立つ": "「滑走路に降り立つ」の辞書形で、飛行機が着く事実を文末で述べます。", "降り立ち": "連用形では文を終えられず、述語になりません。", "降り立とう": "意志形になると、降り立とうという意志の文になり、事実を述べられません。", "降り立てば": "仮定形では文を終えられず、条件節になります。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (53566, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夕暮れ、カモメが桟橋と降り立った。", "corrected_sentence": "夕暮れ、カモメが桟橋に降り立った。", "error_description": "「降り立つ」の到達先は「に」で示します。「と」は並列を表すため、到達先には使えません。正しくは「桟橋に」です。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "降り立つ", "is_correct": true, "explanation": "「ツルが降り立つ」の辞書形で、ツルが着く事実を文末で述べます。"}, {"text": "降り立って", "is_correct": false, "explanation": "て形では文を終えられず、述語になりません。"}, {"text": "降り立たない", "is_correct": false, "explanation": "否定形にすると、ツルが降り立たないという逆の内容になります。"}, {"text": "降り立てば", "is_correct": false, "explanation": "仮定形では文を終えられず、条件節になります。"}], "correct_form": "降り立つ", "base_form": "降り立つ", "form_label": "辞書形", "sentence_index": 7, "explanations": {"降り立つ": "「ツルが降り立つ」の辞書形で、ツルが着く事実を文末で述べます。", "降り立って": "て形では文を終えられず、述語になりません。", "降り立たない": "否定形にすると、ツルが降り立たないという逆の内容になります。", "降り立てば": "仮定形では文を終えられず、条件節になります。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
